trait RecoverMutex<T> {
    fn lock_recover(&self, label: &str) -> MutexGuard<'_, T>;
}

impl<T> RecoverMutex<T> for Mutex<T> {
    fn lock_recover(&self, label: &str) -> MutexGuard<'_, T> {
        match self.lock() {
            Ok(guard) => guard,
            Err(poisoned) => {
                eprintln!(
                    "Mayhem gateway recovered poisoned {label}; request containment preserved"
                );
                poisoned.into_inner()
            }
        }
    }
}

