#[derive(Debug)]
struct GatewayWalletSpendState {
    balance_au: MoneyAu,
    reservations: BTreeMap<String, MoneyAu>,
}

#[derive(Debug)]
struct GatewaySpendReservationInner {
    id: String,
    remaining_au: Mutex<Option<MoneyAu>>,
    wallet_spend: Arc<Mutex<GatewayWalletSpendState>>,
    access_control: Arc<GatewayAccessControl>,
    access_token: Option<GatewayTokenAttribution>,
}

impl GatewaySpendReservationInner {
    fn settle(&self, delta_au: MoneyAu, terminal: bool) -> Result<(), ApiError> {
        let mut remaining = self.remaining_au.lock_recover("gateway spend reservation");
        let Some(current_remaining) = *remaining else {
            return Ok(());
        };
        if delta_au > current_remaining {
            return Err(ApiError::payment_required(
                "signed settlement exceeds the reserved session maximum",
                Some("model"),
            ));
        }
        self.access_control
            .settle_reservation(&self.access_token, &self.id, delta_au, terminal)?;
        let next_remaining = current_remaining.saturating_sub(delta_au);
        let mut wallet = self.wallet_spend.lock_recover("gateway wallet spend state");
        wallet.balance_au = wallet.balance_au.saturating_sub(delta_au);
        if terminal {
            wallet.reservations.remove(&self.id);
            *remaining = None;
        } else {
            wallet.reservations.insert(self.id.clone(), next_remaining);
            *remaining = Some(next_remaining);
        }
        Ok(())
    }

    fn release(&self) {
        let mut remaining = self.remaining_au.lock_recover("gateway spend reservation");
        if remaining.take().is_none() {
            return;
        }
        self.access_control
            .release_reservation(&self.access_token, &self.id);
        self.wallet_spend
            .lock_recover("gateway wallet spend state")
            .reservations
            .remove(&self.id);
    }
}

impl Drop for GatewaySpendReservationInner {
    fn drop(&mut self) {
        self.release();
    }
}

#[derive(Clone, Debug)]
struct GatewaySpendReservation(Arc<GatewaySpendReservationInner>);

impl GatewaySpendReservation {
    fn settle(&self, delta_au: MoneyAu, terminal: bool) -> Result<(), ApiError> {
        self.0.settle(delta_au, terminal)
    }

    fn release(&self) {
        self.0.release();
    }
}

impl GatewayReceiptRecorder {
    fn record(&self, receipt: StoredReceipt) -> Result<(), ApiError> {
        {
            let mut receipts = self.receipts.lock_recover("receipt store");
            if let Some(existing) = receipts.iter().find(|existing| {
                existing.receipt.body.session_id == receipt.receipt.body.session_id
                    && existing.receipt.body.seq == receipt.receipt.body.seq
            }) {
                if existing == &receipt {
                    return Ok(());
                }
                return Err(ApiError::conflict(
                    "receipt sequence already contains different signed settlement data",
                    None,
                ));
            }
            let billing_id = receipt.receipt.body.billing_id.as_str();
            let cumulative = receipt.receipt.body.au_owed_cum;
            let previous = receipts
                .iter()
                .filter(|existing| existing.receipt.body.billing_id == billing_id)
                .map(|existing| existing.receipt.body.au_owed_cum)
                .max()
                .unwrap_or(0);
            let spend_delta = cumulative.checked_sub(previous).ok_or_else(|| {
                ApiError::conflict("logical billing cumulative amount regressed", None)
            })?;
            self.spend_reservation
                .settle(spend_delta, receipt.receipt.body.final_receipt)?;
            receipts.push(receipt);
            if let Some(history) = &self.history {
                if receipts.len() > history.receipt_limit {
                    let remove = receipts.len() - history.receipt_limit;
                    receipts.drain(..remove);
                }
            }
        }
        if let Some(history) = &self.history {
            persist_gateway_dashboard_history(
                &history.path,
                &history.write,
                &self.receipts,
                &history.paused_sessions,
            )?;
        }
        Ok(())
    }

    fn release_reservation(&self) {
        self.spend_reservation.release();
    }

    fn queue_settlement_feature(&self, feature: &Value) -> Result<(), GatewaySessionError> {
        let publisher = self.settlement_publisher.as_ref().as_ref().ok_or_else(|| {
            GatewaySessionError::new("gateway receipt settlement publisher is not configured")
        })?;
        publisher.queue(feature).map_err(|err| {
            GatewaySessionError::new(format!("queueing receipt settlement failed: {err}"))
        })
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct GatewayMediaLimits {
    max_items_per_request: u32,
    max_image_bytes: u64,
    max_image_pixels: u64,
    max_audio_bytes: u64,
    max_audio_seconds: u64,
    max_video_bytes: u64,
    max_video_frames: u64,
}

impl Default for GatewayMediaLimits {
    fn default() -> Self {
        Self {
            max_items_per_request: DEFAULT_GATEWAY_MAX_CHAT_MEDIA_ITEMS,
            max_image_bytes: DEFAULT_GATEWAY_MAX_CHAT_IMAGE_BYTES,
            max_image_pixels: DEFAULT_GATEWAY_MAX_CHAT_IMAGE_PIXELS,
            max_audio_bytes: DEFAULT_GATEWAY_MAX_CHAT_AUDIO_BYTES,
            max_audio_seconds: DEFAULT_GATEWAY_MAX_CHAT_AUDIO_SECONDS,
            max_video_bytes: DEFAULT_GATEWAY_MAX_CHAT_VIDEO_BYTES,
            max_video_frames: DEFAULT_GATEWAY_MAX_CHAT_VIDEO_FRAMES,
        }
    }
}

impl GatewayMediaLimits {
    fn from_env() -> Result<Self, String> {
        Ok(Self {
            max_items_per_request: configured_bounded_media_u64(
                "MAYHEM_GATEWAY_MAX_MEDIA_ITEMS_PER_REQUEST",
                u64::from(DEFAULT_GATEWAY_MAX_CHAT_MEDIA_ITEMS),
                u64::from(GATEWAY_MEDIA_SCHEMA_MAX_ITEMS),
            )?
            .try_into()
            .map_err(|_| "gateway media item limit exceeds u32".to_owned())?,
            max_image_bytes: configured_bounded_media_u64(
                "MAYHEM_GATEWAY_MAX_IMAGE_BYTES",
                DEFAULT_GATEWAY_MAX_CHAT_IMAGE_BYTES,
                GATEWAY_MEDIA_SCHEMA_MAX_ITEM_BYTES,
            )?,
            max_image_pixels: configured_bounded_media_u64(
                "MAYHEM_GATEWAY_MAX_IMAGE_PIXELS",
                DEFAULT_GATEWAY_MAX_CHAT_IMAGE_PIXELS,
                GATEWAY_MEDIA_SCHEMA_MAX_ITEM_UNITS,
            )?,
            max_audio_bytes: configured_bounded_media_u64(
                "MAYHEM_GATEWAY_MAX_AUDIO_BYTES",
                DEFAULT_GATEWAY_MAX_CHAT_AUDIO_BYTES,
                GATEWAY_MEDIA_SCHEMA_MAX_ITEM_BYTES,
            )?,
            max_audio_seconds: configured_bounded_media_u64(
                "MAYHEM_GATEWAY_MAX_AUDIO_SECONDS",
                DEFAULT_GATEWAY_MAX_CHAT_AUDIO_SECONDS,
                GATEWAY_MEDIA_SCHEMA_MAX_ITEM_UNITS,
            )?,
            max_video_bytes: configured_bounded_media_u64(
                "MAYHEM_GATEWAY_MAX_VIDEO_BYTES",
                DEFAULT_GATEWAY_MAX_CHAT_VIDEO_BYTES,
                GATEWAY_MEDIA_SCHEMA_MAX_ITEM_BYTES,
            )?,
            max_video_frames: configured_bounded_media_u64(
                "MAYHEM_GATEWAY_MAX_VIDEO_FRAMES",
                DEFAULT_GATEWAY_MAX_CHAT_VIDEO_FRAMES,
                GATEWAY_MEDIA_SCHEMA_MAX_ITEM_UNITS,
            )?,
        })
    }

    fn schema_ceiling() -> Self {
        Self {
            max_items_per_request: GATEWAY_MEDIA_SCHEMA_MAX_ITEMS,
            max_image_bytes: GATEWAY_MEDIA_SCHEMA_MAX_ITEM_BYTES,
            max_image_pixels: GATEWAY_MEDIA_SCHEMA_MAX_ITEM_UNITS,
            max_audio_bytes: GATEWAY_MEDIA_SCHEMA_MAX_ITEM_BYTES,
            max_audio_seconds: GATEWAY_MEDIA_SCHEMA_MAX_ITEM_UNITS,
            max_video_bytes: GATEWAY_MEDIA_SCHEMA_MAX_ITEM_BYTES,
            max_video_frames: GATEWAY_MEDIA_SCHEMA_MAX_ITEM_UNITS,
        }
    }
}

fn configured_bounded_media_u64(name: &str, default: u64, max: u64) -> Result<u64, String> {
    let value = match std::env::var(name) {
        Ok(value) => value
            .trim()
            .parse::<u64>()
            .map_err(|_| format!("{name} must be a positive integer"))?,
        Err(std::env::VarError::NotPresent) => default,
        Err(err) => return Err(format!("reading {name}: {err}")),
    };
    if value == 0 || value > max {
        return Err(format!("{name} must be between 1 and {max}"));
    }
    Ok(value)
}

