struct GatewayModalityAdmissionGuard {
    active: Arc<Mutex<BTreeMap<(ProviderKey, String), u32>>>,
    reservations: Vec<(ProviderKey, String, u32)>,
}

impl Drop for GatewayModalityAdmissionGuard {
    fn drop(&mut self) {
        let mut active = self.active.lock_recover("modality admission map");
        for (provider, modality, count) in self.reservations.iter().rev() {
            let key = (provider.clone(), modality.clone());
            let remove = if let Some(current) = active.get_mut(&key) {
                *current = current.saturating_sub(*count);
                *current == 0
            } else {
                false
            };
            if remove {
                active.remove(&key);
            }
        }
    }
}

#[derive(Clone, Copy, Debug)]
struct GatewayRetentionLimits {
    receipts: usize,
    paused_sessions: usize,
    chat_affinities: usize,
    jobs: usize,
    job_bytes: usize,
    job_ttl_seconds: u64,
}

impl Default for GatewayRetentionLimits {
    fn default() -> Self {
        let session_artifact_bytes = configured_positive_usize(
            "MAYHEM_SESSION_MAX_ARTIFACT_BYTES",
            DEFAULT_SESSION_MAX_ARTIFACT_BYTES,
        );
        Self {
            receipts: configured_positive_usize(
                "MAYHEM_GATEWAY_MAX_STORED_RECEIPTS",
                DEFAULT_GATEWAY_MAX_STORED_RECEIPTS,
            ),
            paused_sessions: configured_positive_usize(
                "MAYHEM_GATEWAY_MAX_STORED_PAUSED_SESSIONS",
                DEFAULT_GATEWAY_MAX_STORED_PAUSED_SESSIONS,
            ),
            chat_affinities: configured_positive_usize(
                "MAYHEM_GATEWAY_MAX_CHAT_AFFINITIES",
                DEFAULT_GATEWAY_MAX_CHAT_AFFINITIES,
            ),
            jobs: configured_positive_usize(
                "MAYHEM_GATEWAY_MAX_STORED_JOBS",
                DEFAULT_GATEWAY_MAX_STORED_JOBS,
            ),
            job_bytes: configured_positive_usize(
                "MAYHEM_GATEWAY_MAX_STORED_JOB_BYTES",
                DEFAULT_GATEWAY_MAX_STORED_JOB_BYTES,
            )
            .max(session_artifact_bytes),
            job_ttl_seconds: u64::try_from(configured_positive_usize(
                "MAYHEM_GATEWAY_JOB_TTL_SECONDS",
                usize::try_from(DEFAULT_GATEWAY_JOB_TTL_SECONDS).unwrap_or(3_600),
            ))
            .unwrap_or(DEFAULT_GATEWAY_JOB_TTL_SECONDS),
        }
    }
}

fn push_bounded<T>(items: &mut VecDeque<T>, item: T, max_items: usize) {
    let max_items = max_items.max(1);
    while items.len() >= max_items {
        items.pop_front();
    }
    items.push_back(item);
}

struct DashboardSession {
    bootstrap_token: String,
    browser_token: String,
    bootstrap_consumed: Mutex<bool>,
}

impl fmt::Debug for DashboardSession {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("DashboardSession")
            .field("bootstrap_token", &"<redacted>")
            .field("browser_token", &"<redacted>")
            .field("bootstrap_consumed", &"<redacted>")
            .finish()
    }
}

impl DashboardSession {
    fn new() -> Self {
        Self {
            bootstrap_token: new_dashboard_token(),
            browser_token: new_dashboard_token(),
            bootstrap_consumed: Mutex::new(false),
        }
    }

    fn authorize_bootstrap(&self, token: &str) -> Option<String> {
        if token != self.bootstrap_token {
            return None;
        }
        let mut consumed = self
            .bootstrap_consumed
            .lock_recover("dashboard bootstrap state");
        if *consumed {
            return None;
        }
        *consumed = true;
        Some(self.browser_token.clone())
    }

    fn bootstrap_matches(&self, token: &str) -> bool {
        token == self.bootstrap_token
    }

    fn authorize_browser(&self, token: &str) -> Option<String> {
        if token != self.browser_token {
            return None;
        }
        Some(self.browser_token.clone())
    }
}

