#[derive(Clone, Debug)]
pub struct CanonicalHfAsrObjectInput {
    pub contract_request: Value,
    pub audio: Vec<u8>,
    pub content_type: String,
    pub filename: String,
}

pub fn canonicalize_hf_asr_object_input(
    mut contract_request: Value,
) -> Result<Option<CanonicalHfAsrObjectInput>, String> {
    let Some(input) = contract_request.get("inputs").and_then(Value::as_object) else {
        return Ok(None);
    };
    let encoded = input
        .get("data")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "HF ASR inputs object requires base64 data".to_owned())?;
    let bytes = BASE64_STANDARD
        .decode(encoded)
        .map_err(|err| format!("inputs.data is not valid base64 audio: {err}"))?;
    let declared_content_type = input.get("content_type").and_then(Value::as_str);
    let audio =
        bounded_audio_metadata(&bytes, declared_content_type).map_err(|error| error.message)?;
    let filename = input
        .get("filename")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .unwrap_or(audio.filename)
        .to_owned();
    let content_type = audio.content_type.to_owned();
    contract_request["inputs"] = json!({
        "encoding": "raw",
        "bytes": bytes.len(),
        "blake3": blake3_hex(&bytes),
        "content_type": content_type,
    });
    Ok(Some(CanonicalHfAsrObjectInput {
        contract_request,
        audio: bytes,
        content_type,
        filename,
    }))
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct EndpointRequestNormalization {
    pub endpoint_family: String,
    pub contract_fingerprint: String,
    pub normalized_request_fingerprint: String,
    pub normalized_request: Value,
}

pub fn normalize_endpoint_request_for_provider(
    contract: &EndpointFamilyContract,
    raw_request: &Value,
) -> Result<EndpointRequestNormalization, String> {
    mayhem_proto::validate_endpoint_request(contract, raw_request).map_err(|violations| {
        violations
            .iter()
            .map(|violation| format!("{}: {}", violation.path, violation.reason))
            .collect::<Vec<_>>()
            .join("; ")
    })?;
    let defaulted_request =
        mayhem_proto::materialize_endpoint_request_defaults(contract, raw_request)?;
    mayhem_proto::validate_endpoint_request(contract, &defaulted_request).map_err(
        |violations| {
            format!(
                "request with signed defaults violates contract: {}",
                violations
                    .iter()
                    .map(|violation| format!("{}: {}", violation.path, violation.reason))
                    .collect::<Vec<_>>()
                    .join("; ")
            )
        },
    )?;
    match contract.family.as_str() {
        mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS
        | mayhem_proto::ENDPOINT_HF_MULTIMODAL_CHAT => {
            serde_json::from_value::<ChatCompletionRequest>(defaulted_request.clone())
                .map_err(|err| format!("invalid chat request: {err}"))?;
        }
        mayhem_proto::ENDPOINT_OPENAI_COMPLETIONS => {
            serde_json::from_value::<CompletionRequest>(defaulted_request.clone())
                .map_err(|err| format!("invalid completion request: {err}"))?;
        }
        mayhem_proto::ENDPOINT_OPENAI_RESPONSES => {
            serde_json::from_value::<ResponsesRequest>(defaulted_request.clone())
                .map_err(|err| format!("invalid Responses request: {err}"))?;
        }
        mayhem_proto::ENDPOINT_OPENAI_EMBEDDINGS => {
            serde_json::from_value::<EmbeddingRequest>(defaulted_request.clone())
                .map_err(|err| format!("invalid embedding request: {err}"))?;
        }
        mayhem_proto::ENDPOINT_OPENAI_IMAGE_GENERATIONS => {
            serde_json::from_value::<ImageGenerationRequest>(defaulted_request.clone())
                .map_err(|err| format!("invalid image request: {err}"))?;
        }
        mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH => {
            serde_json::from_value::<AudioSpeechRequest>(defaulted_request.clone())
                .map_err(|err| format!("invalid speech request: {err}"))?;
        }
        mayhem_proto::ENDPOINT_OPENAI_AUDIO_TRANSCRIPTIONS => {}
        mayhem_proto::ENDPOINT_HF_FEATURE_EXTRACTION
        | mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE
        | mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION
        | mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH
        | mayhem_proto::ENDPOINT_OPENAI_VIDEOS
        | mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO
        | mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS
        | mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS
        | mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO
        | mayhem_proto::ENDPOINT_MAYHEM_COMFY_WORKFLOWS => {}
        other => {
            return Err(format!(
                "endpoint family {other} has no gateway normalization path"
            ))
        }
    }
    let mut normalized_request = defaulted_request;
    let canonical_raw_request =
        mayhem_proto::canonicalize_endpoint_request_aliases(contract, raw_request)?;
    restore_explicit_null_attributes(&canonical_raw_request, &mut normalized_request);
    if let Some(path) =
        changed_supplied_endpoint_path(&canonical_raw_request, &normalized_request, "")
    {
        return Err(format!(
            "gateway normalization changed or dropped supplied attribute {path}"
        ));
    }
    mayhem_proto::validate_endpoint_request(contract, &normalized_request).map_err(
        |violations| {
            format!(
                "normalized request violates contract: {}",
                violations
                    .iter()
                    .map(|violation| format!("{}: {}", violation.path, violation.reason))
                    .collect::<Vec<_>>()
                    .join("; ")
            )
        },
    )?;
    Ok(EndpointRequestNormalization {
        endpoint_family: contract.family.clone(),
        contract_fingerprint: mayhem_proto::endpoint_contract_fingerprint(contract),
        normalized_request_fingerprint: mayhem_proto::endpoint_request_fingerprint(
            &normalized_request,
        ),
        normalized_request,
    })
}

fn changed_supplied_endpoint_path(raw: &Value, normalized: &Value, path: &str) -> Option<String> {
    let Value::Object(raw) = raw else {
        return (raw != normalized).then(|| path.to_owned());
    };
    let Value::Object(normalized) = normalized else {
        return Some(path.to_owned());
    };
    for (key, raw_value) in raw {
        let child_path = if path.is_empty() {
            key.clone()
        } else {
            format!("{path}.{key}")
        };
        let Some(normalized_value) = normalized.get(key) else {
            return Some(child_path);
        };
        if let Some(changed) =
            changed_supplied_endpoint_path(raw_value, normalized_value, &child_path)
        {
            return Some(changed);
        }
    }
    None
}

fn restore_explicit_null_attributes(raw_request: &Value, normalized_request: &mut Value) {
    let (Some(raw), Some(normalized)) =
        (raw_request.as_object(), normalized_request.as_object_mut())
    else {
        return;
    };
    for (key, value) in raw {
        if value.is_null() && !normalized.contains_key(key) {
            normalized.insert(key.clone(), Value::Null);
        }
    }
}

#[derive(Debug)]
struct ApiError {
    status: StatusCode,
    message: String,
    param: Option<&'static str>,
}

pub type GatewaySessionFuture<'a> =
    Pin<Box<dyn Future<Output = Result<GatewaySessionResult, GatewaySessionError>> + Send + 'a>>;

pub type GatewayEmbeddingFuture<'a> =
    Pin<Box<dyn Future<Output = Result<GatewayEmbeddingResult, GatewaySessionError>> + Send + 'a>>;

pub type GatewayImageGenerationFuture<'a> = Pin<
    Box<dyn Future<Output = Result<GatewayImageGenerationResult, GatewaySessionError>> + Send + 'a>,
>;

pub type GatewayAudioSpeechFuture<'a> = Pin<
    Box<dyn Future<Output = Result<GatewayAudioSpeechResult, GatewaySessionError>> + Send + 'a>,
>;

pub type GatewayAudioTranscriptionFuture<'a> = Pin<
    Box<
        dyn Future<Output = Result<GatewayAudioTranscriptionResult, GatewaySessionError>>
            + Send
            + 'a,
    >,
>;

pub type GatewayArtifactGenerationFuture<'a> = Pin<
    Box<
        dyn Future<Output = Result<GatewayArtifactGenerationResult, GatewaySessionError>>
            + Send
            + 'a,
    >,
>;

pub type GatewayHedgeProbeFuture<'a> =
    Pin<Box<dyn Future<Output = Result<GatewayHedgeProbeResult, GatewaySessionError>> + Send + 'a>>;

pub type GatewayTpmActivationFuture<'a> =
    Pin<Box<dyn Future<Output = Result<ActivatedTpmIdentity, GatewaySessionError>> + Send + 'a>>;

pub trait GatewaySessionBackend: Send + Sync + std::fmt::Debug {
    fn name(&self) -> &str;
    fn bridge_stream_config(&self) -> Option<ScBridgeGatewaySessionConfig> {
        None
    }
    fn hedge_probe<'a>(
        &'a self,
        _model: &'a GatewayModel,
        _request: &'a ChatCompletionRequest,
        invocation: &'a GatewayHedgeProbeInvocation,
    ) -> GatewayHedgeProbeFuture<'a> {
        Box::pin(async move {
            Ok(GatewayHedgeProbeResult {
                provider: invocation.provider_pubkey.clone().unwrap_or_default(),
                ttft_ms: 0,
            })
        })
    }

    fn activate_tpm<'a>(
        &'a self,
        _invocation: &'a GatewayTpmActivationInvocation,
    ) -> GatewayTpmActivationFuture<'a> {
        Box::pin(async move {
            Err(GatewaySessionError::new(format!(
                "{} backend does not support TPM activation",
                self.name()
            )))
        })
    }

    fn run_chat<'a>(
        &'a self,
        model: &'a GatewayModel,
        request: &'a ChatCompletionRequest,
        invocation: &'a GatewaySessionInvocation,
    ) -> GatewaySessionFuture<'a>;

    fn run_embedding<'a>(
        &'a self,
        _model: &'a GatewayModel,
        _request: &'a EmbeddingRequest,
        _invocation: &'a GatewaySessionInvocation,
    ) -> GatewayEmbeddingFuture<'a> {
        Box::pin(async move {
            Err(GatewaySessionError::new(format!(
                "{} backend does not support embeddings",
                self.name()
            )))
        })
    }

    fn run_image_generation<'a>(
        &'a self,
        _model: &'a GatewayModel,
        _request: &'a ImageGenerationRequest,
        _invocation: &'a GatewaySessionInvocation,
    ) -> GatewayImageGenerationFuture<'a> {
        Box::pin(async move {
            Err(GatewaySessionError::new(format!(
                "{} backend does not support image generation",
                self.name()
            )))
        })
    }

    fn run_audio_speech<'a>(
        &'a self,
        _model: &'a GatewayModel,
        _request: &'a AudioSpeechRequest,
        _invocation: &'a GatewaySessionInvocation,
    ) -> GatewayAudioSpeechFuture<'a> {
        Box::pin(async move {
            Err(GatewaySessionError::new(format!(
                "{} backend does not support audio speech",
                self.name()
            )))
        })
    }

    fn run_audio_transcription<'a>(
        &'a self,
        _model: &'a GatewayModel,
        _request: &'a AudioTranscriptionRequest,
        _invocation: &'a GatewaySessionInvocation,
    ) -> GatewayAudioTranscriptionFuture<'a> {
        Box::pin(async move {
            Err(GatewaySessionError::new(format!(
                "{} backend does not support audio transcription",
                self.name()
            )))
        })
    }

    fn run_artifact_generation<'a>(
        &'a self,
        _model: &'a GatewayModel,
        request: &'a ArtifactGenerationRequest,
        _invocation: &'a GatewaySessionInvocation,
    ) -> GatewayArtifactGenerationFuture<'a> {
        Box::pin(async move {
            Err(GatewaySessionError::new(format!(
                "{} backend does not support {} generation",
                self.name(),
                request.output_modality
            )))
        })
    }
}

