fn normalize_catalog_endpoint_request(
    state: &GatewayState,
    model_id: &str,
    endpoint_family: &str,
    raw_request: &Value,
) -> Result<Value, ApiError> {
    normalize_catalog_endpoint_request_with_metadata(state, model_id, endpoint_family, raw_request)
        .map(|prepared| prepared.normalized)
}

fn normalize_catalog_endpoint_request_with_metadata(
    state: &GatewayState,
    model_id: &str,
    endpoint_family: &str,
    raw_request: &Value,
) -> Result<PreparedCatalogEndpointRequest, ApiError> {
    let contract = catalog_endpoint_contract(state, model_id, endpoint_family)?;
    let (prepared_request, mut video) = if uses_video_generation_aliases(endpoint_family) {
        let (request, video) = canonicalize_video_generation_request(
            &contract,
            endpoint_family,
            raw_request,
            &state.media_limits,
        )
        .map_err(|err| ApiError::bad_request(err, Some("request")))?;
        (Some(request), video)
    } else if uses_audio_generation_aliases(endpoint_family) {
        let request = canonicalize_artifact_generation_request(
            &contract,
            endpoint_family,
            raw_request,
            state.media_limits.max_audio_bytes,
        )
        .map_err(|err| ApiError::bad_request(err, Some("request")))?;
        (Some(request), VideoRequestPreparation::default())
    } else {
        (None, VideoRequestPreparation::default())
    };
    let prepared_request = prepared_request.as_ref().unwrap_or(raw_request);
    let normalized = normalize_endpoint_request_for_provider(&contract, prepared_request)
        .map(|normalized| normalized.normalized_request)
        .map_err(|err| {
            ApiError::bad_request(
                format!("request normalization failed: {err}"),
                Some("request"),
            )
        })?;
    if uses_video_generation_aliases(endpoint_family) {
        validate_video_prompt_enhancement_opt_in(&contract, prepared_request, &normalized)
            .map_err(|err| ApiError::bad_request(err, Some("prompt_enhancement")))?;
        video = finalize_video_request_preparation(&contract, endpoint_family, &normalized, video)
            .map_err(|err| ApiError::bad_request(err, Some("request")))?;
    }
    Ok(PreparedCatalogEndpointRequest { normalized, video })
}

fn uses_audio_generation_aliases(endpoint_family: &str) -> bool {
    matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS
            | mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS
            | mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO
    )
}

fn uses_video_generation_aliases(endpoint_family: &str) -> bool {
    matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_OPENAI_VIDEOS | mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO
    )
}

fn canonicalize_video_generation_request(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    raw_request: &Value,
    limits: &GatewayMediaLimits,
) -> Result<(Value, VideoRequestPreparation), String> {
    if let Some(path) = video_generation_server_image_path(raw_request, "") {
        return Err(format!(
            "{path} is forbidden; image conditioning must use bounded inline base64 or a base64 data URL"
        ));
    }
    let mut request = raw_request.clone();
    for aliases in [
        ARTIFACT_GENERATION_PROMPT_ALIASES,
        &["seed"][..],
        &["width"][..],
        &["height"][..],
        &["size"][..],
        VIDEO_GENERATION_FPS_ALIASES,
        VIDEO_GENERATION_FRAME_ALIASES,
        &["seconds", "duration_seconds", "duration", "target_duration"][..],
        VIDEO_GENERATION_PROMPT_ENHANCEMENT_ALIASES,
    ] {
        canonicalize_signed_video_generation_alias_group(
            contract,
            endpoint_family,
            &mut request,
            aliases,
        )?;
    }

    let inline_image =
        canonicalize_video_generation_conditions(contract, endpoint_family, &mut request, limits)?;

    let frame_candidates =
        artifact_generation_alias_candidates(endpoint_family, VIDEO_GENERATION_FRAME_ALIASES);
    let frame_resolution = artifact_generation_alias_target(contract, &frame_candidates)
        .map(|path| {
            let spec = contract.request_attribute_specs.get(&path).ok_or_else(|| {
                format!("signed frame attribute {path} is missing its specification")
            })?;
            let supplied = json_path_value(&request, &path)
                .map(|value| {
                    endpoint_positive_integer(value)
                        .ok_or_else(|| format!("{path} must be a positive integer"))
                })
                .transpose()?;
            let signed_default = spec
                .default
                .as_ref()
                .map(|value| {
                    endpoint_positive_integer(value).ok_or_else(|| {
                        format!("signed frame default for {path} must be a positive integer")
                    })
                })
                .transpose()?;
            Ok::<_, String>((path, spec, supplied, signed_default))
        })
        .transpose()?;
    let requested_frames = if let Some((path, spec, supplied, signed_default)) =
        frame_resolution.as_ref()
    {
        if let Some(requested) = supplied.or(*signed_default) {
            let actual = if supplied.is_some() {
                canonical_video_frame_count(requested, spec)?
            } else {
                requested
            };
            set_json_path(&mut request, path, json!(actual))?;
            Some(requested)
        } else if endpoint_family == mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO {
            return Err(format!(
                    "signed HF text-to-video contract must resolve {path} from the request or a default"
                ));
        } else {
            None
        }
    } else {
        None
    };

    Ok((
        request,
        VideoRequestPreparation {
            requested_frames,
            canonical_frames: None,
            inline_image,
        },
    ))
}

fn finalize_video_request_preparation(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    normalized: &Value,
    mut video: VideoRequestPreparation,
) -> Result<VideoRequestPreparation, String> {
    if video.requested_frames.is_some() {
        let frames = artifact_generation_request_value(
            normalized,
            endpoint_family,
            VIDEO_GENERATION_FRAME_ALIASES,
        )
        .and_then(endpoint_positive_integer)
        .ok_or_else(|| {
            "signed video frame request did not survive endpoint normalization".to_owned()
        })?;
        video.canonical_frames = Some(frames);
        return Ok(video);
    }

    let duration = artifact_generation_request_value(
        normalized,
        endpoint_family,
        ARTIFACT_GENERATION_DURATION_ALIASES,
    )
    .and_then(generation_duration_seconds)
    .or_else(|| {
        normalized
            .get("seconds")
            .and_then(generation_duration_seconds)
    })
    .unwrap_or(4.0);
    let fps = artifact_generation_request_value(
        normalized,
        endpoint_family,
        VIDEO_GENERATION_FPS_ALIASES,
    )
    .and_then(endpoint_positive_number)
    .unwrap_or(
        if endpoint_family == mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO {
            8.0
        } else {
            DEFAULT_VIDEO_GENERATION_FPS as f64
        },
    );
    let requested_frames_f64 = duration * fps;
    if !requested_frames_f64.is_finite()
        || requested_frames_f64 < 1.0
        || requested_frames_f64 > u64::MAX as f64
    {
        return Err("video duration/fps produced an invalid frame count".to_owned());
    }
    let requested_frames = requested_frames_f64.floor().max(1.0) as u64;
    let canonical_frames = artifact_generation_alias_target(
        contract,
        &artifact_generation_alias_candidates(endpoint_family, VIDEO_GENERATION_FRAME_ALIASES),
    )
    .and_then(|path| contract.request_attribute_specs.get(&path))
    .map(|spec| {
        mayhem_proto::canonicalize_positive_integer_at_most_for_spec(requested_frames, spec)
    })
    .transpose()?
    .unwrap_or(requested_frames);
    video.requested_frames = Some(requested_frames);
    video.canonical_frames = Some(canonical_frames);
    Ok(video)
}

fn canonicalize_signed_video_generation_alias_group(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    request: &mut Value,
    aliases: &[&str],
) -> Result<(), String> {
    let candidates = artifact_generation_alias_candidates(endpoint_family, aliases);
    let signed = candidates
        .iter()
        .filter(|path| endpoint_contract_supports_request_path(contract, path))
        .collect::<Vec<_>>();
    let Some(target) = signed.first().map(|path| (*path).clone()) else {
        return Ok(());
    };
    let supplied = signed
        .iter()
        .filter_map(|path| json_path_value(request, path).map(|value| (*path, value)))
        .collect::<Vec<_>>();
    let Some((_, value)) = supplied.first() else {
        return Ok(());
    };
    if supplied.len() > 1 {
        return Err(format!(
            "conflicting signed aliases supplied for {}",
            aliases.join("/")
        ));
    }
    let value = (*value).clone();
    for path in signed {
        remove_json_path(request, path);
    }
    set_json_path(request, &target, value)
}

fn signed_video_alias_value(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    request: &Value,
    aliases: &[&str],
) -> Result<Option<(String, Value)>, String> {
    let supplied = artifact_generation_alias_candidates(endpoint_family, aliases)
        .into_iter()
        .filter(|path| endpoint_contract_supports_request_path(contract, path))
        .filter_map(|path| {
            json_path_value(request, &path)
                .cloned()
                .map(|value| (path, value))
        })
        .filter(|(_, value)| !value.is_null())
        .collect::<Vec<_>>();
    if supplied.len() > 1 {
        return Err(format!(
            "conflicting signed aliases supplied for {}",
            aliases.join("/")
        ));
    }
    Ok(supplied.into_iter().next())
}

fn remove_signed_video_aliases(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    request: &mut Value,
    aliases: &[&str],
) {
    for path in artifact_generation_alias_candidates(endpoint_family, aliases) {
        if endpoint_contract_supports_request_path(contract, &path) {
            remove_json_path(request, &path);
        }
    }
}

fn canonicalize_video_generation_conditions(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    request: &mut Value,
    limits: &GatewayMediaLimits,
) -> Result<InlineImageLoad, String> {
    let conditions_path = artifact_generation_alias_target(
        contract,
        &artifact_generation_alias_candidates(endpoint_family, &["conditions"]),
    );
    let image = signed_video_alias_value(
        contract,
        endpoint_family,
        request,
        VIDEO_GENERATION_IMAGE_ALIASES,
    )?;
    let strength = signed_video_alias_value(
        contract,
        endpoint_family,
        request,
        VIDEO_GENERATION_STRENGTH_ALIASES,
    )?;
    let crf = signed_video_alias_value(
        contract,
        endpoint_family,
        request,
        VIDEO_GENERATION_CRF_ALIASES,
    )?;

    if image.is_none() && (strength.is_some() || crf.is_some()) {
        return Err("video conditioning strength/crf requires a signed image alias".to_owned());
    }
    let Some((image_path, image_value)) = image else {
        let Some(conditions_path) = conditions_path else {
            return Ok(InlineImageLoad::default());
        };
        return canonicalize_signed_video_conditions(request, &conditions_path, limits);
    };
    let conditions_path = conditions_path.ok_or_else(|| {
        format!("signed image alias {image_path} requires a signed canonical conditions attribute")
    })?;
    if json_path_value(request, &conditions_path).is_some_and(|value| !value.is_null()) {
        return Err(format!(
            "{image_path} cannot be combined with {conditions_path}"
        ));
    }
    let strength = strength
        .as_ref()
        .map(|(path, value)| {
            value
                .as_f64()
                .filter(|value| value.is_finite() && (0.0..=1.0).contains(value))
                .ok_or_else(|| format!("{path} must be a finite number between 0 and 1"))
        })
        .transpose()?
        .unwrap_or(1.0);
    let crf = crf
        .as_ref()
        .map(|(path, value)| {
            value
                .as_u64()
                .filter(|value| *value <= 51)
                .ok_or_else(|| format!("{path} must be an integer between 0 and 51"))
        })
        .transpose()?
        .unwrap_or(33);
    let (data_url, bytes, pixels) =
        canonical_inline_image_data_url(&image_value, &image_path, limits)?;

    remove_signed_video_aliases(
        contract,
        endpoint_family,
        request,
        VIDEO_GENERATION_IMAGE_ALIASES,
    );
    remove_signed_video_aliases(
        contract,
        endpoint_family,
        request,
        VIDEO_GENERATION_STRENGTH_ALIASES,
    );
    remove_signed_video_aliases(
        contract,
        endpoint_family,
        request,
        VIDEO_GENERATION_CRF_ALIASES,
    );
    set_json_path(
        request,
        &conditions_path,
        json!([{
            "image_url": data_url,
            "frame_index": 0,
            "strength": strength,
            "crf": crf,
        }]),
    )?;
    Ok(InlineImageLoad {
        item_count: 1,
        max_item_bytes: bytes,
        max_item_pixels: pixels,
    })
}

fn canonicalize_signed_video_conditions(
    request: &mut Value,
    conditions_path: &str,
    limits: &GatewayMediaLimits,
) -> Result<InlineImageLoad, String> {
    let Some(value) = json_path_value(request, conditions_path).cloned() else {
        return Ok(InlineImageLoad::default());
    };
    let conditions = value
        .as_array()
        .ok_or_else(|| format!("{conditions_path} must be an ordered array"))?;
    let mut normalized = Vec::with_capacity(conditions.len());
    let mut load = InlineImageLoad::default();
    for (index, condition) in conditions.iter().enumerate() {
        let mut condition = condition
            .as_object()
            .cloned()
            .ok_or_else(|| format!("{conditions_path}[{index}] must be an object"))?;
        let image = condition
            .get("image_url")
            .cloned()
            .ok_or_else(|| format!("{conditions_path}[{index}] must contain image_url"))?;
        let (data_url, bytes, pixels) = canonical_inline_image_data_url(
            &image,
            &format!("{conditions_path}[{index}].image_url"),
            limits,
        )?;
        condition.insert("image_url".to_owned(), json!(data_url));
        normalized.push(Value::Object(condition));
        load.item_count = load.item_count.saturating_add(1);
        load.max_item_bytes = load.max_item_bytes.max(bytes);
        load.max_item_pixels = load.max_item_pixels.max(pixels);
    }
    set_json_path(request, conditions_path, Value::Array(normalized))?;
    Ok(load)
}

fn video_generation_server_image_path(value: &Value, parent: &str) -> Option<String> {
    let object = value.as_object()?;
    for (key, child) in object {
        let path = if parent.is_empty() {
            key.clone()
        } else {
            format!("{parent}.{key}")
        };
        if VIDEO_GENERATION_SERVER_IMAGE_PATH_FIELDS.contains(&key.as_str()) && !child.is_null() {
            return Some(path);
        }
        if let Some(path) = video_generation_server_image_path(child, &path) {
            return Some(path);
        }
    }
    None
}

fn canonical_inline_image_data_url(
    value: &Value,
    path: &str,
    limits: &GatewayMediaLimits,
) -> Result<(String, u64, u64), String> {
    let (encoded, declared_content_type) = match value {
        Value::String(value) => (value.as_str(), None),
        Value::Object(image) => {
            if let Some(unsupported) = image.keys().find(|key| {
                !matches!(
                    key.as_str(),
                    "image_url" | "url" | "data" | "encoding" | "content_type"
                )
            }) {
                return Err(format!(
                    "{path}.{unsupported} is not a supported inline image field"
                ));
            }
            if image
                .get("encoding")
                .is_some_and(|encoding| encoding.as_str() != Some("base64"))
            {
                return Err(format!("{path}.encoding must be the string base64"));
            }
            let encoded = image
                .get("image_url")
                .or_else(|| image.get("url"))
                .or_else(|| image.get("data"))
                .and_then(Value::as_str)
                .ok_or_else(|| format!("{path} must contain image_url, url, or base64 data"))?;
            let content_type = image
                .get("content_type")
                .map(|value| {
                    value
                        .as_str()
                        .ok_or_else(|| format!("{path}.content_type must be a string"))
                })
                .transpose()?;
            (encoded, content_type)
        }
        _ => {
            return Err(format!(
                "{path} must be inline base64, a base64 image data URL, or an inline image object"
            ))
        }
    };

    let data_url = if encoded.starts_with("data:") {
        if declared_content_type.is_some() {
            return Err(format!(
                "{path}.content_type must be omitted when a data URL supplies the media type"
            ));
        }
        encoded.to_owned()
    } else {
        if encoded.contains("://") || encoded.starts_with('/') || encoded.contains("\\\\") {
            return Err(format!(
                "{path} cannot fetch URLs or read server paths; use inline base64 image data"
            ));
        }
        let encoded_limit = usize::try_from(limits.max_image_bytes)
            .unwrap_or(usize::MAX / 4)
            .saturating_mul(4)
            .div_ceil(3)
            .saturating_add(4);
        if encoded.is_empty() || encoded.len() > encoded_limit {
            return Err(format!(
                "{path} exceeds the {}-byte gateway image limit",
                limits.max_image_bytes
            ));
        }
        let bytes = BASE64_STANDARD
            .decode(encoded)
            .map_err(|_| format!("{path} contains invalid base64 image data"))?;
        let detected = match image::guess_format(&bytes) {
            Ok(image::ImageFormat::Png) => "image/png",
            Ok(image::ImageFormat::Jpeg) => "image/jpeg",
            _ => return Err(format!("{path} must contain a PNG or JPEG image")),
        };
        if declared_content_type.is_some_and(|content_type| content_type != detected) {
            return Err(format!(
                "{path}.content_type does not match the decoded image"
            ));
        }
        format!("data:{detected};base64,{encoded}")
    };
    let (bytes, pixels) = validate_chat_image_data_url(&data_url, limits)
        .map_err(|error| format!("{path}: {}", error.message))?;
    Ok((data_url, bytes, pixels))
}

fn endpoint_positive_integer(value: &Value) -> Option<u64> {
    value.as_u64().filter(|value| *value > 0).or_else(|| {
        value
            .as_str()?
            .parse::<u64>()
            .ok()
            .filter(|value| *value > 0)
    })
}

fn canonical_video_frame_count(
    requested: u64,
    spec: &mayhem_proto::EndpointAttributeSpec,
) -> Result<u64, String> {
    mayhem_proto::canonicalize_positive_integer_for_spec(requested, spec)
}

fn validate_video_prompt_enhancement_opt_in(
    contract: &EndpointFamilyContract,
    prepared_request: &Value,
    normalized_request: &Value,
) -> Result<(), String> {
    let candidates = artifact_generation_alias_candidates(
        &contract.family,
        VIDEO_GENERATION_PROMPT_ENHANCEMENT_ALIASES,
    );
    let Some(path) = artifact_generation_alias_target(contract, &candidates) else {
        return Ok(());
    };
    if json_path_value(normalized_request, &path).and_then(Value::as_bool) == Some(true)
        && json_path_value(prepared_request, &path).and_then(Value::as_bool) != Some(true)
    {
        return Err(format!(
            "{path} must be explicitly enabled by the request; signed defaults may not silently rewrite prompts"
        ));
    }
    Ok(())
}

fn canonicalize_artifact_generation_request(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    raw_request: &Value,
    max_audio_bytes: u64,
) -> Result<Value, String> {
    if let Some(path) = artifact_generation_server_audio_path(raw_request, "") {
        return Err(format!(
            "{path} is forbidden; source and reference audio must be inline base64 or a base64 data URL"
        ));
    }

    let mut request = raw_request.clone();
    for aliases in ARTIFACT_GENERATION_ALIAS_GROUPS {
        canonicalize_artifact_generation_alias_group(
            contract,
            endpoint_family,
            &mut request,
            aliases,
        )?;
    }
    canonicalize_music_no_fsq_alias(endpoint_family, &mut request)?;
    canonicalize_optional_music_prompt(contract, endpoint_family, &mut request)?;
    canonicalize_artifact_generation_negative_prompt(contract, endpoint_family, &mut request)?;
    canonicalize_artifact_generation_tags(contract, endpoint_family, &mut request)?;
    canonicalize_artifact_generation_inline_audio(
        contract,
        endpoint_family,
        &mut request,
        max_audio_bytes,
    )?;
    Ok(request)
}

fn canonicalize_music_no_fsq_alias(
    endpoint_family: &str,
    request: &mut Value,
) -> Result<(), String> {
    if endpoint_family != mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS {
        return Ok(());
    }
    let Some(no_fsq) = request.get("no_fsq").cloned() else {
        return Ok(());
    };
    let no_fsq = no_fsq
        .as_bool()
        .ok_or_else(|| "no_fsq must be a boolean".to_owned())?;
    request
        .as_object_mut()
        .ok_or_else(|| "music generation request must be a JSON object".to_owned())?
        .remove("no_fsq");
    let task = request.get("task_type").and_then(Value::as_str);
    if no_fsq {
        if task.is_some_and(|task| !matches!(task, "cover" | "cover-nofsq")) {
            return Err("no_fsq=true is compatible only with cover tasks".to_owned());
        }
        request
            .as_object_mut()
            .expect("validated music request object")
            .insert("task_type".to_owned(), json!("cover-nofsq"));
    } else if task == Some("cover-nofsq") {
        return Err("no_fsq=false conflicts with task_type=cover-nofsq".to_owned());
    }
    Ok(())
}

fn canonicalize_optional_music_prompt(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    request: &mut Value,
) -> Result<(), String> {
    if endpoint_family != mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS {
        return Ok(());
    }
    let candidates =
        artifact_generation_alias_candidates(endpoint_family, ARTIFACT_GENERATION_PROMPT_ALIASES);
    let Some(target) = artifact_generation_alias_target(contract, &candidates) else {
        return Ok(());
    };
    if json_path_value(request, &target).is_none() {
        set_json_path(request, &target, json!(""))?;
    }
    Ok(())
}

fn canonicalize_artifact_generation_alias_group(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    request: &mut Value,
    aliases: &[&str],
) -> Result<(), String> {
    let candidates = artifact_generation_alias_candidates(endpoint_family, aliases);
    let Some(target) = artifact_generation_alias_target(contract, &candidates) else {
        return Ok(());
    };
    let supplied = candidates
        .iter()
        .filter_map(|path| json_path_value(request, path).map(|value| (path, value)))
        .collect::<Vec<_>>();
    let Some((_, value)) = supplied.first() else {
        return Ok(());
    };
    if supplied.len() > 1 {
        return Err(format!(
            "conflicting aliases supplied for {}",
            aliases.join("/")
        ));
    }
    let value = (*value).clone();
    for path in &candidates {
        remove_json_path(request, path);
    }
    set_json_path(request, &target, value)?;
    Ok(())
}

fn canonicalize_artifact_generation_negative_prompt(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    request: &mut Value,
) -> Result<(), String> {
    let lm_candidates =
        artifact_generation_alias_candidates(endpoint_family, &["lm_negative_prompt"]);
    if artifact_generation_alias_target(contract, &lm_candidates).is_some() {
        return canonicalize_artifact_generation_alias_group(
            contract,
            endpoint_family,
            request,
            &["lm_negative_prompt", "negative_prompt"],
        );
    }
    canonicalize_artifact_generation_alias_group(
        contract,
        endpoint_family,
        request,
        &["negative_prompt"],
    )?;
    canonicalize_artifact_generation_alias_group(
        contract,
        endpoint_family,
        request,
        &["lm_negative_prompt"],
    )
}

fn canonicalize_artifact_generation_tags(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    request: &mut Value,
) -> Result<(), String> {
    let candidates =
        artifact_generation_alias_candidates(endpoint_family, ARTIFACT_GENERATION_TAG_ALIASES);
    let Some(target) = artifact_generation_alias_target(contract, &candidates) else {
        return Ok(());
    };
    let Some(value) = json_path_value(request, &target).cloned() else {
        return Ok(());
    };
    let Value::Array(values) = value else {
        if value.is_string() || value.is_null() {
            return Ok(());
        }
        return Err(format!("{target} must be a string or an array of strings"));
    };
    let max_chars = contract
        .request_attribute_specs
        .get(&target)
        .and_then(|spec| spec.max_length)
        .ok_or_else(|| format!("signed {target} string contract must declare max_length"))?;
    let mut normalized = Vec::with_capacity(values.len());
    let mut combined_chars = 0_u64;
    for (index, value) in values.into_iter().enumerate() {
        let tag = value
            .as_str()
            .ok_or_else(|| format!("{target}[{index}] must be a string"))?
            .trim();
        if tag.is_empty() {
            return Err(format!("{target}[{index}] must not be empty"));
        }
        let tag_chars = u64::try_from(tag.chars().count()).unwrap_or(u64::MAX);
        if tag_chars > max_chars {
            return Err(format!(
                "{target}[{index}] exceeds the signed {max_chars}-character limit"
            ));
        }
        if !normalized.is_empty() {
            combined_chars = combined_chars.saturating_add(2);
        }
        combined_chars = combined_chars.saturating_add(tag_chars);
        if combined_chars > max_chars {
            return Err(format!(
                "{target} array canonicalizes beyond the signed {max_chars}-character limit"
            ));
        }
        normalized.push(tag.to_owned());
    }
    set_json_path(request, &target, Value::String(normalized.join(", ")))
}

fn artifact_generation_alias_target(
    contract: &EndpointFamilyContract,
    candidates: &[String],
) -> Option<String> {
    candidates
        .iter()
        .find(|path| endpoint_contract_supports_request_path(contract, path))
        .cloned()
}

fn artifact_generation_alias_candidates(endpoint_family: &str, aliases: &[&str]) -> Vec<String> {
    let hf = matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO | mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO
    );
    let mut candidates = Vec::new();
    if hf && aliases.contains(&"prompt") {
        candidates.push("inputs".to_owned());
    }
    if hf {
        candidates.extend(aliases.iter().map(|alias| format!("parameters.{alias}")));
        candidates.extend(aliases.iter().map(|alias| (*alias).to_owned()));
    } else {
        candidates.extend(aliases.iter().map(|alias| (*alias).to_owned()));
        candidates.extend(aliases.iter().map(|alias| format!("parameters.{alias}")));
    }
    candidates.dedup();
    candidates
}

fn endpoint_contract_supports_request_path(contract: &EndpointFamilyContract, path: &str) -> bool {
    contract.request_attribute_specs.contains_key(path)
        || contract
            .request_attributes
            .iter()
            .any(|candidate| candidate == path)
}

fn json_path_value<'a>(value: &'a Value, path: &str) -> Option<&'a Value> {
    path.split('.')
        .try_fold(value, |current, component| current.get(component))
}

fn remove_json_path(value: &mut Value, path: &str) -> Option<Value> {
    let (head, tail) = path.split_once('.').unwrap_or((path, ""));
    let object = value.as_object_mut()?;
    if tail.is_empty() {
        return object.remove(head);
    }
    let child = object.get_mut(head)?;
    let removed = remove_json_path(child, tail);
    if child.as_object().is_some_and(serde_json::Map::is_empty) {
        object.remove(head);
    }
    removed
}

fn set_json_path(value: &mut Value, path: &str, inserted: Value) -> Result<(), String> {
    let (head, tail) = path.split_once('.').unwrap_or((path, ""));
    let object = value
        .as_object_mut()
        .ok_or_else(|| "artifact generation request must be a JSON object".to_owned())?;
    if tail.is_empty() {
        object.insert(head.to_owned(), inserted);
        return Ok(());
    }
    let child = object.entry(head.to_owned()).or_insert_with(|| json!({}));
    if !child.is_object() {
        return Err(format!("{head} must be an object"));
    }
    set_json_path(child, tail, inserted)
}

fn artifact_generation_server_audio_path(value: &Value, parent: &str) -> Option<String> {
    let object = value.as_object()?;
    for (key, child) in object {
        let path = if parent.is_empty() {
            key.clone()
        } else {
            format!("{parent}.{key}")
        };
        if ARTIFACT_GENERATION_SERVER_AUDIO_PATH_FIELDS.contains(&key.as_str()) && !child.is_null()
        {
            return Some(path);
        }
        if let Some(path) = artifact_generation_server_audio_path(child, &path) {
            return Some(path);
        }
    }
    None
}

fn canonicalize_artifact_generation_inline_audio(
    contract: &EndpointFamilyContract,
    endpoint_family: &str,
    request: &mut Value,
    max_audio_bytes: u64,
) -> Result<(), String> {
    let mut total_bytes = 0_u64;
    for aliases in [
        ARTIFACT_GENERATION_SOURCE_AUDIO_ALIASES,
        ARTIFACT_GENERATION_REFERENCE_AUDIO_ALIASES,
    ] {
        for path in artifact_generation_alias_candidates(endpoint_family, aliases) {
            let Some(value) = json_path_value(request, &path).cloned() else {
                continue;
            };
            if value.is_null() {
                continue;
            }
            let object_target = contract
                .request_attribute_specs
                .get(&path)
                .is_some_and(|spec| spec.value_types.contains(&EndpointValueType::Object));
            let (canonical, decoded_len) =
                canonical_inline_audio_value(&value, &path, max_audio_bytes, object_target)?;
            total_bytes = total_bytes.checked_add(decoded_len).ok_or_else(|| {
                "combined inline source/reference audio length overflowed".to_owned()
            })?;
            if total_bytes > max_audio_bytes {
                return Err(format!(
                    "combined inline source/reference audio exceeds the {max_audio_bytes}-byte gateway limit"
                ));
            }
            set_json_path(request, &path, canonical)?;
        }
    }
    Ok(())
}

fn canonical_inline_audio_value(
    value: &Value,
    path: &str,
    max_audio_bytes: u64,
    object_target: bool,
) -> Result<(Value, u64), String> {
    let (original, declared_content_type) = match value {
        Value::String(encoded) => (encoded.as_str(), None),
        Value::Object(audio) => {
            if let Some(unsupported) = audio
                .keys()
                .find(|key| !matches!(key.as_str(), "data" | "encoding" | "content_type"))
            {
                return Err(format!(
                    "{path}.{unsupported} is not a supported inline audio field"
                ));
            }
            if audio
                .get("encoding")
                .is_some_and(|encoding| encoding.as_str() != Some("base64"))
            {
                return Err(format!("{path}.encoding must be the string base64"));
            }
            let encoded = audio
                .get("data")
                .and_then(Value::as_str)
                .ok_or_else(|| format!("{path}.data must contain base64 audio"))?;
            let content_type = audio
                .get("content_type")
                .map(|content_type| {
                    content_type
                        .as_str()
                        .ok_or_else(|| format!("{path}.content_type must be a string"))
                })
                .transpose()?;
            (encoded, content_type)
        }
        _ => {
            return Err(format!(
                "{path} must be inline base64, a base64 data URL, or an inline audio object"
            ))
        }
    };
    let (encoded, data_url_content_type) = inline_audio_payload(original, path)?;
    if declared_content_type.is_some()
        && data_url_content_type.is_some()
        && declared_content_type != data_url_content_type
    {
        return Err(format!(
            "{path}.content_type conflicts with the inline data URL media type"
        ));
    }
    let content_type = declared_content_type
        .or(data_url_content_type)
        .unwrap_or("audio/octet-stream");
    if !valid_inline_audio_content_type(content_type) {
        return Err(format!(
            "{path}.content_type must be a valid audio/* media type"
        ));
    }
    let decoded_len = decoded_inline_audio_len(encoded, path, max_audio_bytes)?;
    let canonical = if object_target {
        json!({
            "data": encoded,
            "encoding": "base64",
            "content_type": content_type,
        })
    } else {
        value.clone()
    };
    Ok((canonical, decoded_len))
}

fn inline_audio_payload<'a>(
    value: &'a str,
    path: &str,
) -> Result<(&'a str, Option<&'a str>), String> {
    let Some(data_url) = value.strip_prefix("data:") else {
        return Ok((value, None));
    };
    let (metadata, encoded) = data_url
        .split_once(',')
        .ok_or_else(|| format!("{path} is not a valid data URL"))?;
    if !metadata
        .split(';')
        .any(|component| component.eq_ignore_ascii_case("base64"))
    {
        return Err(format!("{path} data URL must use base64 encoding"));
    }
    let content_type = metadata
        .split(';')
        .next()
        .filter(|content_type| !content_type.is_empty());
    Ok((encoded, content_type))
}

fn valid_inline_audio_content_type(content_type: &str) -> bool {
    let Some(subtype) = content_type.strip_prefix("audio/") else {
        return false;
    };
    !subtype.is_empty()
        && subtype.bytes().all(|byte| {
            byte.is_ascii_alphanumeric()
                || matches!(
                    byte,
                    b'!' | b'#' | b'$' | b'&' | b'^' | b'_' | b'.' | b'+' | b'-'
                )
        })
}

fn decoded_inline_audio_len(value: &str, path: &str, max_audio_bytes: u64) -> Result<u64, String> {
    if value.is_empty() {
        return Err(format!("{path} audio data must not be empty"));
    }
    let encoded_limit = usize::try_from(max_audio_bytes)
        .unwrap_or(usize::MAX / 4)
        .saturating_mul(4)
        .div_ceil(3)
        .saturating_add(4);
    if value.len() > encoded_limit {
        return Err(format!(
            "{path} exceeds the {max_audio_bytes}-byte gateway audio limit"
        ));
    }
    let bytes = BASE64_STANDARD
        .decode(value)
        .map_err(|_| format!("{path} contains invalid base64 audio"))?;
    let decoded_len = u64::try_from(bytes.len()).unwrap_or(u64::MAX);
    if decoded_len == 0 || decoded_len > max_audio_bytes {
        return Err(format!(
            "{path} audio must contain 1..={max_audio_bytes} decoded bytes"
        ));
    }
    Ok(decoded_len)
}

fn catalog_endpoint_contract(
    state: &GatewayState,
    model_id: &str,
    endpoint_family: &str,
) -> Result<EndpointFamilyContract, ApiError> {
    let model = require_model(state, model_id)?;
    model
        .mayhem
        .adapter
        .endpoint_families
        .into_iter()
        .find(|contract| contract.family == endpoint_family)
        .ok_or_else(|| {
            ApiError::bad_request(
                format!(
                    "model {} does not expose endpoint family {endpoint_family}",
                    model.id
                ),
                Some("model"),
            )
        })
}

fn endpoint_request_model(raw_request: &Value) -> Result<&str, ApiError> {
    raw_request
        .get("model")
        .and_then(Value::as_str)
        .filter(|model| !model.trim().is_empty())
        .ok_or_else(|| ApiError::bad_request("request missing model", Some("model")))
}

enum PreparedGatewayJob {
    Started(GatewayJobHandle),
    InProgress(String),
    Existing(StoredGatewayJob),
}

async fn prepare_gateway_job(
    state: &GatewayState,
    headers: &HeaderMap,
    endpoint_family: &str,
    model: &str,
    normalized_request: &Value,
    access_token: &Option<GatewayTokenAttribution>,
) -> Result<PreparedGatewayJob, ApiError> {
    prepare_gateway_job_with_cancellation(
        state,
        headers,
        endpoint_family,
        model,
        normalized_request,
        access_token,
        None,
    )
    .await
}

async fn prepare_gateway_job_with_cancellation(
    state: &GatewayState,
    headers: &HeaderMap,
    endpoint_family: &str,
    model: &str,
    normalized_request: &Value,
    access_token: &Option<GatewayTokenAttribution>,
    cancellation: Option<GatewayRequestCancellation>,
) -> Result<PreparedGatewayJob, ApiError> {
    let idempotency_key = headers
        .get("idempotency-key")
        .map(|value| {
            value.to_str().map(str::to_owned).map_err(|_| {
                ApiError::bad_request(
                    "Idempotency-Key must be valid ASCII",
                    Some("Idempotency-Key"),
                )
            })
        })
        .transpose()?;
    let owner_token_id = access_token
        .as_ref()
        .map(|access_token| access_token.token_id.clone());
    let id = gateway_job_id(
        state.receipt_config.user_seed,
        owner_token_id.as_deref(),
        endpoint_family,
        idempotency_key.as_deref(),
    )
    .map_err(|err| ApiError::bad_request(err, Some("Idempotency-Key")))?;
    let request_fingerprint = stable_value_hash(normalized_request);
    let cancellation = cancellation.unwrap_or_else(GatewayRequestCancellation::new);
    let store = state.jobs.clone();
    let active_cancellations = state.active_job_cancellations.clone();
    let begin_id = id.clone();
    let begin_endpoint = endpoint_family.to_owned();
    let begin_model = model.to_owned();
    let begin_cancellation = cancellation.clone();
    let begin = tokio::task::spawn_blocking(move || {
        let mut store = store.lock_recover("gateway job vault");
        if store.is_active(&begin_id) {
            return store.begin(
                begin_id,
                begin_endpoint,
                begin_model,
                owner_token_id,
                request_fingerprint,
                now_secs(),
            );
        }

        let mut cancellations =
            active_cancellations.lock_recover("active gateway job cancellations");
        cancellations.insert(begin_id.clone(), begin_cancellation.clone());
        let begin = store.begin(
            begin_id.clone(),
            begin_endpoint,
            begin_model,
            owner_token_id,
            request_fingerprint,
            now_secs(),
        );
        if !matches!(begin, Ok(BeginGatewayJob::Started))
            && cancellations
                .get(&begin_id)
                .is_some_and(|registered| registered == &begin_cancellation)
        {
            cancellations.remove(&begin_id);
        }
        begin
    })
    .await
    .map_err(|err| ApiError::internal_message(format!("gateway job task failed: {err}")))?
    .map_err(|err| ApiError::conflict(err, Some("Idempotency-Key")))?;
    Ok(match begin {
        BeginGatewayJob::Started => PreparedGatewayJob::Started(GatewayJobHandle {
            id,
            store: state.jobs.clone(),
            cancellation,
            active_cancellations: state.active_job_cancellations.clone(),
            settlement_reconciliation_started: Arc::new(AtomicBool::new(false)),
        }),
        BeginGatewayJob::InProgress => PreparedGatewayJob::InProgress(id),
        BeginGatewayJob::Existing(job) => PreparedGatewayJob::Existing(job),
    })
}

fn gateway_job_metadata(job: &StoredGatewayJob) -> Value {
    gateway_job_summary_metadata(&StoredGatewayJobSummary::from(job))
}

fn gateway_job_summary_metadata(job: &StoredGatewayJobSummary) -> Value {
    json!({
        "id": job.id,
        "object": "mayhem.job",
        "status": job.status.as_str(),
        "endpoint_family": job.endpoint_family,
        "model": job.model,
        "created_at": job.created_at,
        "finished_at": job.finished_at,
        "expires_at": job.expires_at,
        "result_url": format!("/v1/jobs/{}/result", job.id),
        "artifacts": job.artifacts.iter().map(|artifact| json!({
            "id": artifact.id,
            "content_type": artifact.content_type,
            "bytes": artifact.bytes,
            "blake3": artifact.blake3,
            "content_url": format!("/v1/jobs/{}/artifacts/{}", job.id, artifact.id),
        })).collect::<Vec<_>>(),
        "receipt": job.receipt,
        "error": job.error,
    })
}

fn gateway_job_pending_response(id: &str) -> Response {
    let mut response = (
        StatusCode::ACCEPTED,
        Json(json!({
            "id": id,
            "object": "mayhem.job",
            "status": "in_progress",
            "status_url": format!("/v1/jobs/{id}"),
        })),
    )
        .into_response();
    attach_gateway_job_headers(&mut response, id);
    response
}

fn request_gateway_job_cancellation(state: &GatewayState, id: &str) -> bool {
    let cancellation = state
        .active_job_cancellations
        .lock_recover("active gateway job cancellations")
        .get(id)
        .cloned();
    if let Some(cancellation) = cancellation {
        cancellation.cancel();
        true
    } else {
        false
    }
}

fn gateway_job_cancelling_response(id: &str) -> Response {
    let mut response = (
        StatusCode::ACCEPTED,
        Json(json!({
            "id": id,
            "object": "mayhem.job",
            "status": "cancelling",
            "deleted": false,
            "status_url": format!("/v1/jobs/{id}"),
        })),
    )
        .into_response();
    attach_gateway_job_headers(&mut response, id);
    response
}

fn gateway_existing_job_response(job: StoredGatewayJob) -> Response {
    let status = match job.status {
        GatewayJobStatus::Completed => StatusCode::OK,
        GatewayJobStatus::ReconciliationPending => StatusCode::ACCEPTED,
        GatewayJobStatus::Cancelled | GatewayJobStatus::Failed => StatusCode::CONFLICT,
    };
    let id = job.id.clone();
    let mut response = (status, Json(gateway_job_metadata(&job))).into_response();
    attach_gateway_job_headers(&mut response, &id);
    response
}

fn attach_gateway_job_headers(response: &mut Response, id: &str) {
    if let Ok(value) = HeaderValue::from_str(id) {
        response.headers_mut().insert("x-mayhem-job-id", value);
    }
    if let Ok(value) = HeaderValue::from_str(&format!("/v1/jobs/{id}")) {
        response.headers_mut().insert(header::LOCATION, value);
    }
}

fn gateway_prefers_async_response(headers: &HeaderMap) -> bool {
    headers
        .get_all("prefer")
        .iter()
        .filter_map(|value| value.to_str().ok())
        .flat_map(|value| value.split(','))
        .filter_map(|preference| preference.trim().split(';').next())
        .any(|preference| preference.eq_ignore_ascii_case("respond-async"))
}

fn gateway_job_in_progress_metadata(
    id: &str,
    endpoint_family: &str,
    model: &str,
    created_at: u64,
) -> Value {
    json!({
        "id": id,
        "object": "mayhem.job",
        "status": "in_progress",
        "endpoint_family": endpoint_family,
        "model": model,
        "created_at": created_at,
        "status_url": format!("/v1/jobs/{id}"),
        "result_url": format!("/v1/jobs/{id}/result"),
        "artifacts": [],
        "receipt": Value::Null,
        "error": Value::Null,
    })
}

fn gateway_job_lookup_id(job: &GatewayJobLookup) -> &str {
    match job {
        GatewayJobLookup::InProgress { id, .. } => id,
        GatewayJobLookup::Terminal(job) => &job.id,
    }
}

fn gateway_job_lookup_model(job: &GatewayJobLookup) -> &str {
    match job {
        GatewayJobLookup::InProgress { model, .. } => model,
        GatewayJobLookup::Terminal(job) => &job.model,
    }
}

fn gateway_job_lookup_owner(job: &GatewayJobLookup) -> Option<&str> {
    match job {
        GatewayJobLookup::InProgress { owner_token_id, .. } => owner_token_id.as_deref(),
        GatewayJobLookup::Terminal(job) => job.owner_token_id.as_deref(),
    }
}

fn gateway_job_lookup_metadata(job: &GatewayJobLookup) -> Value {
    match job {
        GatewayJobLookup::InProgress {
            id,
            endpoint_family,
            model,
            created_at,
            ..
        } => gateway_job_in_progress_metadata(id, endpoint_family, model, *created_at),
        GatewayJobLookup::Terminal(job) => gateway_job_metadata(job),
    }
}

fn gateway_job_list_entry_id(job: &GatewayJobListEntry) -> &str {
    match job {
        GatewayJobListEntry::InProgress { id, .. } => id,
        GatewayJobListEntry::Terminal(job) => &job.id,
    }
}

fn gateway_job_list_entry_created_at(job: &GatewayJobListEntry) -> u64 {
    match job {
        GatewayJobListEntry::InProgress { created_at, .. } => *created_at,
        GatewayJobListEntry::Terminal(job) => job.created_at,
    }
}

fn gateway_job_list_entry_metadata(job: &GatewayJobListEntry) -> Value {
    match job {
        GatewayJobListEntry::InProgress {
            id,
            endpoint_family,
            model,
            created_at,
        } => gateway_job_in_progress_metadata(id, endpoint_family, model, *created_at),
        GatewayJobListEntry::Terminal(job) => gateway_job_summary_metadata(job),
    }
}

async fn lookup_gateway_job(
    state: &GatewayState,
    id: &str,
) -> Result<Option<GatewayJobLookup>, ApiError> {
    let store = state.jobs.clone();
    let id = id.to_owned();
    tokio::task::spawn_blocking(move || {
        store
            .lock_recover("gateway job vault")
            .lookup(&id, now_secs())
    })
    .await
    .map_err(|err| ApiError::internal_message(format!("gateway job lookup task failed: {err}")))?
    .map_err(ApiError::internal_message)
}

fn authorize_gateway_job(
    state: &GatewayState,
    headers: &HeaderMap,
    job: &GatewayJobLookup,
) -> Result<Option<GatewayTokenAttribution>, ApiError> {
    let access_token =
        state.authorize_gateway_request(headers, Some(gateway_job_lookup_model(job)))?;
    let owner_token_id = access_token
        .as_ref()
        .map(|access_token| access_token.token_id.as_str());
    if owner_token_id != gateway_job_lookup_owner(job) {
        return Err(ApiError::not_found(
            "gateway job was not found",
            Some("job_id"),
        ));
    }
    Ok(access_token)
}

async fn list_gateway_jobs(
    State(state): State<SharedState>,
    headers: HeaderMap,
    Query(query): Query<VideoListQuery>,
) -> Response {
    let access_token = match state.authorize_gateway_request(&headers, None) {
        Ok(access_token) => access_token,
        Err(err) => return err.into_response(),
    };
    let limit = query.limit.unwrap_or(20);
    if !(1..=100).contains(&limit) {
        return ApiError::bad_request("limit must be between 1 and 100", Some("limit"))
            .into_response();
    }
    let descending = match query.order.as_deref().unwrap_or("desc") {
        "desc" => true,
        "asc" => false,
        _ => {
            return ApiError::bad_request("order must be asc or desc", Some("order"))
                .into_response()
        }
    };
    let owner = access_token
        .as_ref()
        .map(|access_token| access_token.token_id.clone());
    let store = state.jobs.clone();
    let mut jobs = match tokio::task::spawn_blocking(move || {
        store
            .lock_recover("gateway job vault")
            .list_entries_for_owner(owner.as_deref(), now_secs())
    })
    .await
    {
        Ok(Ok(jobs)) => jobs,
        Ok(Err(err)) => return ApiError::internal_message(err).into_response(),
        Err(err) => {
            return ApiError::internal_message(format!("gateway job list task failed: {err}"))
                .into_response()
        }
    };
    jobs.sort_by_key(|job| {
        (
            gateway_job_list_entry_created_at(job),
            gateway_job_list_entry_id(job).to_owned(),
        )
    });
    if descending {
        jobs.reverse();
    }
    let start = if let Some(after) = query.after.as_deref() {
        match jobs
            .iter()
            .position(|job| gateway_job_list_entry_id(job) == after)
        {
            Some(index) => index.saturating_add(1),
            None => {
                return ApiError::bad_request("after cursor was not found", Some("after"))
                    .into_response()
            }
        }
    } else {
        0
    };
    let has_more = jobs.len().saturating_sub(start) > limit;
    let data = jobs
        .into_iter()
        .skip(start)
        .take(limit)
        .map(|job| gateway_job_list_entry_metadata(&job))
        .collect::<Vec<_>>();
    let first_id = data
        .first()
        .and_then(|job| job.get("id"))
        .cloned()
        .unwrap_or(Value::Null);
    let last_id = data
        .last()
        .and_then(|job| job.get("id"))
        .cloned()
        .unwrap_or(Value::Null);
    Json(json!({
        "object": "list",
        "data": data,
        "first_id": first_id,
        "last_id": last_id,
        "has_more": has_more,
    }))
    .into_response()
}

async fn retrieve_gateway_job(
    State(state): State<SharedState>,
    Path(job_id): Path<String>,
    headers: HeaderMap,
) -> Response {
    let job = match lookup_gateway_job(&state, &job_id).await {
        Ok(Some(job)) => job,
        Ok(None) => {
            return ApiError::not_found("gateway job was not found", Some("job_id")).into_response()
        }
        Err(err) => return err.into_response(),
    };
    if let Err(err) = authorize_gateway_job(&state, &headers, &job) {
        return err.into_response();
    }
    let status = if matches!(job, GatewayJobLookup::InProgress { .. })
        || matches!(
            &job,
            GatewayJobLookup::Terminal(job)
                if job.status == GatewayJobStatus::ReconciliationPending
        ) {
        StatusCode::ACCEPTED
    } else {
        StatusCode::OK
    };
    let mut response = (status, Json(gateway_job_lookup_metadata(&job))).into_response();
    attach_gateway_job_headers(&mut response, gateway_job_lookup_id(&job));
    response
}

async fn retrieve_gateway_job_result(
    State(state): State<SharedState>,
    Path(job_id): Path<String>,
    headers: HeaderMap,
) -> Response {
    let job = match lookup_gateway_job(&state, &job_id).await {
        Ok(Some(job)) => job,
        Ok(None) => {
            return ApiError::not_found("gateway job was not found", Some("job_id")).into_response()
        }
        Err(err) => return err.into_response(),
    };
    if let Err(err) = authorize_gateway_job(&state, &headers, &job) {
        return err.into_response();
    }
    let GatewayJobLookup::Terminal(job) = job else {
        return gateway_job_pending_response(&job_id);
    };
    if !matches!(
        job.status,
        GatewayJobStatus::Completed | GatewayJobStatus::ReconciliationPending
    ) {
        return gateway_existing_job_response(job);
    }
    let mut response = Json(json!({
        "id": job.id,
        "object": "mayhem.job.result",
        "status": job.status.as_str(),
        "result": job.result,
        "receipt": job.receipt,
    }))
    .into_response();
    attach_gateway_job_headers(&mut response, &job_id);
    response
}

async fn retrieve_gateway_job_artifact(
    State(state): State<SharedState>,
    Path((job_id, artifact_id)): Path<(String, String)>,
    headers: HeaderMap,
) -> Response {
    let job = match lookup_gateway_job(&state, &job_id).await {
        Ok(Some(job)) => job,
        Ok(None) => {
            return ApiError::not_found("gateway job was not found", Some("job_id")).into_response()
        }
        Err(err) => return err.into_response(),
    };
    if let Err(err) = authorize_gateway_job(&state, &headers, &job) {
        return err.into_response();
    }
    let GatewayJobLookup::Terminal(job) = job else {
        return gateway_job_pending_response(&job_id);
    };
    if !matches!(
        job.status,
        GatewayJobStatus::Completed | GatewayJobStatus::ReconciliationPending
    ) {
        return gateway_existing_job_response(job);
    }
    let Some(artifact) = job
        .artifacts
        .into_iter()
        .find(|artifact| artifact.id == artifact_id)
    else {
        return ApiError::not_found("gateway job artifact was not found", Some("artifact_id"))
            .into_response();
    };
    let mut response = Body::from(artifact.bytes).into_response();
    let content_type = match HeaderValue::from_str(&artifact.content_type) {
        Ok(content_type) => content_type,
        Err(err) => {
            return ApiError::internal_message(format!(
                "stored gateway job content type is invalid: {err}"
            ))
            .into_response()
        }
    };
    response
        .headers_mut()
        .insert(header::CONTENT_TYPE, content_type);
    if let Ok(blake3) = HeaderValue::from_str(&artifact.blake3) {
        response
            .headers_mut()
            .insert("x-mayhem-artifact-blake3", blake3);
    }
    attach_gateway_job_headers(&mut response, &job_id);
    response
}

async fn delete_gateway_job(
    State(state): State<SharedState>,
    Path(job_id): Path<String>,
    headers: HeaderMap,
) -> Response {
    let job = match lookup_gateway_job(&state, &job_id).await {
        Ok(Some(job)) => job,
        Ok(None) => {
            return ApiError::not_found("gateway job was not found", Some("job_id")).into_response()
        }
        Err(err) => return err.into_response(),
    };
    let access_token = match authorize_gateway_job(&state, &headers, &job) {
        Ok(access_token) => access_token,
        Err(err) => return err.into_response(),
    };
    if matches!(job, GatewayJobLookup::InProgress { .. }) {
        if request_gateway_job_cancellation(&state, &job_id) {
            return gateway_job_cancelling_response(&job_id);
        }
        return ApiError::conflict(
            "the in-progress job no longer has a live execution to cancel",
            Some("job_id"),
        )
        .into_response();
    }
    if matches!(
        &job,
        GatewayJobLookup::Terminal(job)
            if job.status == GatewayJobStatus::ReconciliationPending
    ) {
        return ApiError::conflict(
            "the completed result is still reconciling its signed receipt acknowledgement",
            Some("job_id"),
        )
        .into_response();
    }
    let owner = access_token
        .as_ref()
        .map(|access_token| access_token.token_id.clone());
    let store = state.jobs.clone();
    let remove_id = job_id.clone();
    let removed = match tokio::task::spawn_blocking(move || {
        store
            .lock_recover("gateway job vault")
            .remove(&remove_id, owner.as_deref(), now_secs())
    })
    .await
    {
        Ok(Ok(removed)) => removed,
        Ok(Err(err)) => return ApiError::internal_message(err).into_response(),
        Err(err) => {
            return ApiError::internal_message(format!("gateway job delete task failed: {err}"))
                .into_response()
        }
    };
    if removed.is_none() {
        return ApiError::not_found("gateway job was not found", Some("job_id")).into_response();
    }
    Json(json!({
        "id": job_id,
        "object": "mayhem.job.deleted",
        "deleted": true,
    }))
    .into_response()
}

async fn create_chat_completion(
    State(state): State<SharedState>,
    headers: HeaderMap,
    Json(raw_request): Json<Value>,
) -> Response {
    let model_id = match endpoint_request_model(&raw_request) {
        Ok(model) => model,
        Err(err) => return err.into_response(),
    };
    let access_token = match state.authorize_gateway_request(&headers, Some(model_id)) {
        Ok(access_token) => access_token,
        Err(err) => return err.into_response(),
    };
    let endpoint_family = match chat_endpoint_family(&state, model_id, &raw_request) {
        Ok(family) => family,
        Err(err) => return err.into_response(),
    };
    let (mut request, normalized_request) = match parse_catalog_endpoint_request::<
        ChatCompletionRequest,
    >(&state, &raw_request, &endpoint_family)
    {
        Ok(request) => request,
        Err(err) => return err.into_response(),
    };
    request.endpoint_family = Some(endpoint_family);
    request.endpoint_request = Some(normalized_request);
    let mut options = match state.request_options_from_headers(&headers) {
        Ok(options) => options,
        Err(err) => return err.into_response(),
    };
    options.access_token = access_token;
    if request.stream {
        return match build_chat_completion(state, request, options).await {
            Ok(ChatResponse::Json(value)) => Json(value).into_response(),
            Ok(ChatResponse::Sse(chunks)) => sse_response(chunks),
            Ok(ChatResponse::SseStream(events)) => sse_stream_response(events),
            Err(err) => err.into_response(),
        };
    }
    let endpoint_family = request
        .endpoint_family
        .as_deref()
        .expect("normalized chat endpoint family is present");
    let job = match prepare_gateway_job(
        &state,
        &headers,
        endpoint_family,
        &request.model,
        request
            .endpoint_request
            .as_ref()
            .expect("normalized chat request is present"),
        &options.access_token,
    )
    .await
    {
        Ok(PreparedGatewayJob::Started(job)) => job,
        Ok(PreparedGatewayJob::InProgress(id)) => return gateway_job_pending_response(&id),
        Ok(PreparedGatewayJob::Existing(job)) => return gateway_existing_job_response(job),
        Err(err) => return err.into_response(),
    };
    options.job = Some(job.clone());
    let cancellation = job.cancellation();
    options.client_cancellation = Some(cancellation.clone());
    if gateway_prefers_async_response(&headers) {
        let job_id = job.id.clone();
        spawn_gateway_job_request(job, async move {
            build_chat_completion(state, request, options).await
        });
        return gateway_job_pending_response(&job_id);
    }
    let result = run_detached_gateway_job_request(cancellation, job.clone(), async move {
        build_chat_completion(state, request, options).await
    })
    .await;
    match result {
        Ok(ChatResponse::Json(value)) => {
            if let Err(err) = job
                .persist_completed_if_active(value.clone(), Vec::new(), None)
                .await
            {
                return err.into_response();
            }
            let mut response = Json(value).into_response();
            attach_gateway_job_headers(&mut response, &job.id);
            response
        }
        Ok(ChatResponse::Sse(chunks)) => sse_response(chunks),
        Ok(ChatResponse::SseStream(events)) => sse_stream_response(events),
        Err(err) => err.into_response(),
    }
}

fn chat_endpoint_family(
    state: &GatewayState,
    model_id: &str,
    raw_request: &Value,
) -> Result<String, ApiError> {
    let model = require_model(state, model_id)?;
    let has_family = |family: &str| {
        model
            .mayhem
            .adapter
            .endpoint_families
            .iter()
            .any(|contract| contract.family == family)
    };
    let has_video = raw_request
        .get("messages")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|message| message.get("content").and_then(Value::as_array))
        .flatten()
        .any(|part| part.get("type").and_then(Value::as_str) == Some("video"));
    if has_video {
        if has_family(mayhem_proto::ENDPOINT_HF_MULTIMODAL_CHAT) {
            return Ok(mayhem_proto::ENDPOINT_HF_MULTIMODAL_CHAT.to_owned());
        }
        return Err(ApiError::bad_request(
            format!(
                "model {} does not expose the signed video-chat endpoint family",
                model.id
            ),
            Some("messages"),
        ));
    }
    if has_family(mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS) {
        return Ok(mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS.to_owned());
    }
    if has_family(mayhem_proto::ENDPOINT_HF_MULTIMODAL_CHAT) {
        return Ok(mayhem_proto::ENDPOINT_HF_MULTIMODAL_CHAT.to_owned());
    }
    Err(ApiError::bad_request(
        format!("model {} does not expose a chat endpoint family", model.id),
        Some("model"),
    ))
}

