async fn create_hf_inference(
    State(state): State<SharedState>,
    Path(model_path): Path<String>,
    headers: HeaderMap,
    body: Bytes,
) -> Response {
    let (model_id, endpoint_family) = match hf_inference_target(&state, &model_path) {
        Ok(target) => target,
        Err(err) => return err.into_response(),
    };
    let access_token = match state.authorize_gateway_request(&headers, Some(&model_id)) {
        Ok(access_token) => access_token,
        Err(err) => return err.into_response(),
    };
    let payload = match parse_hf_inference_payload(&headers, &endpoint_family, body) {
        Ok(payload) => payload,
        Err(err) => return err.into_response(),
    };
    let prepared = match normalize_catalog_endpoint_request_with_metadata(
        &state,
        &model_id,
        &endpoint_family,
        &payload.contract_request,
    ) {
        Ok(prepared) => prepared,
        Err(err) => return err.into_response(),
    };
    let payload = HfInferencePayload {
        contract_request: prepared.normalized,
        raw_audio: payload.raw_audio,
        video: prepared.video,
    };
    let mut options = match state.request_options_from_headers(&headers) {
        Ok(options) => options,
        Err(err) => return err.into_response(),
    };
    options.access_token = access_token;
    let job = match prepare_gateway_job(
        &state,
        &headers,
        &endpoint_family,
        &model_id,
        &payload.contract_request,
        &options.access_token,
    )
    .await
    {
        Ok(PreparedGatewayJob::Started(job)) => job,
        Ok(PreparedGatewayJob::InProgress(id)) => return gateway_job_pending_response(&id),
        Ok(PreparedGatewayJob::Existing(job)) => return gateway_existing_job_response(job),
        Err(err) => return err.into_response(),
    };
    options.job = Some(job.clone());
    let cancellation = job.cancellation();
    options.client_cancellation = Some(cancellation.clone());
    if gateway_prefers_async_response(&headers) {
        let job_id = job.id.clone();
        spawn_gateway_job_request(
            job,
            execute_hf_inference_job(state, model_id, endpoint_family, payload, options),
        );
        return gateway_job_pending_response(&job_id);
    }
    let result = run_detached_gateway_job_request(
        cancellation,
        job.clone(),
        execute_hf_inference_job(state, model_id, endpoint_family, payload, options),
    )
    .await;
    match result {
        Ok(mut response) => {
            attach_gateway_job_headers(&mut response, &job.id);
            response
        }
        Err(err) => err.into_response(),
    }
}

fn parse_hf_inference_payload(
    headers: &HeaderMap,
    endpoint_family: &str,
    body: Bytes,
) -> Result<HfInferencePayload, ApiError> {
    let declared_content_type = headers
        .get(header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let json_body = declared_content_type.is_some_and(|value| {
        value.eq_ignore_ascii_case("application/json")
            || value.to_ascii_lowercase().starts_with("application/json;")
    }) || declared_content_type.is_none()
        && body
            .iter()
            .copied()
            .find(|byte| !byte.is_ascii_whitespace())
            == Some(b'{');
    if json_body {
        let contract_request = serde_json::from_slice::<Value>(&body).map_err(|err| {
            ApiError::bad_request(format!("invalid HF JSON request: {err}"), Some("body"))
        })?;
        let (contract_request, raw_audio) = if endpoint_family
            == mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION
            && contract_request.get("inputs").is_some_and(Value::is_object)
        {
            let canonical = canonicalize_hf_asr_object_input(contract_request)
                .map_err(|error| ApiError::bad_request(error, Some("inputs")))?
                .expect("object input was checked above");
            (
                canonical.contract_request,
                Some(HfRawAudio {
                    bytes: canonical.audio,
                    content_type: canonical.content_type,
                    filename: canonical.filename,
                }),
            )
        } else {
            (contract_request, None)
        };
        return Ok(HfInferencePayload {
            contract_request,
            raw_audio,
            video: VideoRequestPreparation::default(),
        });
    }
    if endpoint_family != mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION {
        return Err(ApiError::bad_request(
            "this HF task endpoint requires an application/json request",
            Some("body"),
        ));
    }
    if body.is_empty() {
        return Err(ApiError::bad_request(
            "raw HF ASR request body must not be empty",
            Some("body"),
        ));
    }
    let bytes = body.to_vec();
    let audio = bounded_audio_metadata(&bytes, declared_content_type)?;
    let contract_request = json!({
        "inputs": {
            "encoding": "raw",
            "bytes": bytes.len(),
            "blake3": blake3_hex(&bytes),
            "content_type": audio.content_type,
        },
    });
    Ok(HfInferencePayload {
        contract_request,
        raw_audio: Some(HfRawAudio {
            bytes,
            content_type: audio.content_type.to_owned(),
            filename: audio.filename.to_owned(),
        }),
        video: VideoRequestPreparation::default(),
    })
}

async fn execute_hf_inference_job(
    state: SharedState,
    model_id: String,
    endpoint_family: String,
    payload: HfInferencePayload,
    options: GatewayRequestOptions,
) -> Result<Response, ApiError> {
    let HfInferencePayload {
        contract_request: raw_request,
        raw_audio,
        video,
    } = payload;
    match endpoint_family.as_str() {
        mayhem_proto::ENDPOINT_HF_FEATURE_EXTRACTION => {
            let request = hf_embedding_request(&model_id, raw_request)?;
            let value = build_embedding(&state, request, options).await?;
            Ok(Json(hf_embedding_response(value)?).into_response())
        }
        mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE => {
            let request = hf_image_generation_request(&model_id, raw_request)?;
            let value = build_image_generation(&state, request, options).await?;
            hf_image_response(value)
        }
        mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH => {
            let request = hf_audio_speech_request(&model_id, raw_request)?;
            build_audio_speech(&state, request, options).await
        }
        mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION => {
            let request = hf_audio_transcription_request(&model_id, raw_request, raw_audio)?;
            build_audio_transcription(&state, request, options).await
        }
        mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO | mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO => {
            let request =
                artifact_generation_request(&model_id, &endpoint_family, raw_request, video)?;
            let response_request = request.clone();
            let run = build_artifact_generation(&state, request, options).await?;
            artifact_generation_raw_response(&response_request, &run)
        }
        _ => Err(ApiError::bad_request(
            format!("endpoint family {endpoint_family} is not an HF task route"),
            Some("model"),
        )),
    }
}

fn hf_inference_target(
    state: &GatewayState,
    model_path: &str,
) -> Result<(String, String), ApiError> {
    let path = model_path.trim_start_matches('/');
    let (model_id, forced_family) = path
        .strip_suffix("/pipeline/feature-extraction")
        .map(|model| (model, Some(mayhem_proto::ENDPOINT_HF_FEATURE_EXTRACTION)))
        .unwrap_or((path, None));
    if model_id.trim().is_empty() {
        return Err(ApiError::bad_request(
            "HF route missing model",
            Some("model"),
        ));
    }
    let model = require_model(state, model_id)?;
    if let Some(family) = forced_family {
        if model
            .mayhem
            .adapter
            .endpoint_families
            .iter()
            .any(|contract| contract.family == family)
        {
            return Ok((model.id, family.to_owned()));
        }
        return Err(ApiError::bad_request(
            format!(
                "model {} does not expose endpoint family {family}",
                model.id
            ),
            Some("model"),
        ));
    }

    let candidates = model
        .mayhem
        .adapter
        .endpoint_families
        .iter()
        .filter(|contract| {
            matches!(
                contract.family.as_str(),
                mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE
                    | mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO
                    | mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION
                    | mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH
                    | mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO
            )
        })
        .map(|contract| contract.family.clone())
        .collect::<Vec<_>>();
    match candidates.as_slice() {
        [family] => Ok((model.id, family.clone())),
        [] => Err(ApiError::bad_request(
            format!("model {} has no HF task endpoint", model.id),
            Some("model"),
        )),
        _ => Err(ApiError::bad_request(
            format!(
                "model {} has ambiguous HF task endpoints: {}",
                model.id,
                candidates.join(", ")
            ),
            Some("model"),
        )),
    }
}

fn hf_embedding_request(model_id: &str, raw_request: Value) -> Result<EmbeddingRequest, ApiError> {
    let input = raw_request
        .get("inputs")
        .cloned()
        .ok_or_else(|| ApiError::bad_request("request missing inputs", Some("inputs")))?;
    let dimensions = raw_request
        .get("dimensions")
        .and_then(Value::as_u64)
        .map(usize::try_from)
        .transpose()
        .map_err(|_| ApiError::bad_request("dimensions is too large", Some("dimensions")))?;
    Ok(EmbeddingRequest {
        model: model_id.to_owned(),
        input,
        encoding_format: Some("float".to_owned()),
        dimensions,
        user: None,
        endpoint_family: Some(mayhem_proto::ENDPOINT_HF_FEATURE_EXTRACTION.to_owned()),
        endpoint_request: Some(raw_request),
    })
}

fn hf_embedding_response(value: Value) -> Result<Value, ApiError> {
    let data = value
        .get("data")
        .and_then(Value::as_array)
        .ok_or_else(|| ApiError::bad_gateway("embedding response missing data", Some("model")))?;
    Ok(Value::Array(
        data.iter()
            .map(|item| {
                item.get("embedding").cloned().ok_or_else(|| {
                    ApiError::bad_gateway("embedding response item missing vector", Some("model"))
                })
            })
            .collect::<Result<Vec<_>, _>>()?,
    ))
}

fn hf_image_generation_request(
    model_id: &str,
    raw_request: Value,
) -> Result<ImageGenerationRequest, ApiError> {
    let prompt = raw_request
        .get("inputs")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| ApiError::bad_request("request missing inputs", Some("inputs")))?
        .to_owned();
    let parameters = raw_request.get("parameters").unwrap_or(&Value::Null);
    let width = parameters.get("width").and_then(Value::as_u64);
    let height = parameters.get("height").and_then(Value::as_u64);
    if width.is_some() != height.is_some() {
        return Err(ApiError::bad_request(
            "parameters.width and parameters.height must be supplied together",
            Some("parameters"),
        ));
    }
    Ok(ImageGenerationRequest {
        model: model_id.to_owned(),
        prompt,
        background: None,
        moderation: None,
        n: parameters
            .get("num_images_per_prompt")
            .and_then(Value::as_u64)
            .map(u32::try_from)
            .transpose()
            .map_err(|_| {
                ApiError::bad_request(
                    "parameters.num_images_per_prompt is too large",
                    Some("parameters"),
                )
            })?,
        output_compression: None,
        output_format: None,
        partial_images: None,
        size: None,
        width: width.map(u32::try_from).transpose().map_err(|_| {
            ApiError::bad_request("parameters.width is too large", Some("parameters"))
        })?,
        height: height.map(u32::try_from).transpose().map_err(|_| {
            ApiError::bad_request("parameters.height is too large", Some("parameters"))
        })?,
        response_format: Some("b64_json".to_owned()),
        quality: None,
        style: None,
        negative_prompt: parameters
            .get("negative_prompt")
            .and_then(Value::as_str)
            .map(str::to_owned),
        steps: parameters
            .get("num_inference_steps")
            .and_then(Value::as_u64),
        cfg_scale: parameters
            .get("guidance_scale")
            .and_then(Value::as_f64)
            .map(|value| value as f32),
        shift: parameters
            .get("shift")
            .and_then(Value::as_f64)
            .map(|value| value as f32),
        seed: parameters.get("seed").and_then(Value::as_i64),
        scheduler: parameters
            .get("scheduler")
            .and_then(Value::as_str)
            .map(str::to_owned),
        stream: None,
        user: None,
        endpoint_family: Some(mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE.to_owned()),
        endpoint_request: Some(raw_request),
    })
}

fn hf_image_response(value: Value) -> Result<Response, ApiError> {
    let encoded = value
        .pointer("/data/0/b64_json")
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::bad_gateway("image response missing bytes", Some("model")))?;
    let bytes = BASE64_STANDARD.decode(encoded).map_err(|err| {
        ApiError::bad_gateway(
            format!("image response has invalid base64: {err}"),
            Some("model"),
        )
    })?;
    let content_type = value
        .pointer("/mayhem/artifacts/0/content_type")
        .and_then(Value::as_str)
        .unwrap_or("image/png");
    let mut response = Body::from(bytes).into_response();
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_str(content_type).map_err(|err| {
            ApiError::bad_gateway(format!("invalid image content type: {err}"), Some("model"))
        })?,
    );
    Ok(response)
}

fn hf_audio_speech_request(
    model_id: &str,
    raw_request: Value,
) -> Result<AudioSpeechRequest, ApiError> {
    let input = raw_request
        .get("inputs")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| ApiError::bad_request("request missing inputs", Some("inputs")))?
        .to_owned();
    let parameters = raw_request.get("parameters").unwrap_or(&Value::Null);
    let generation_parameters = parameters
        .get("generation_parameters")
        .unwrap_or(&Value::Null);
    let voice = parameters
        .get("voice")
        .or_else(|| parameters.get("speaker_id"))
        .and_then(|value| {
            value
                .as_str()
                .map(str::to_owned)
                .or_else(|| value.as_i64().map(|value| value.to_string()))
        });
    Ok(AudioSpeechRequest {
        model: model_id.to_owned(),
        input,
        voice,
        response_format: Some("wav".to_owned()),
        speed: parameters.get("speed").and_then(Value::as_f64),
        instructions: None,
        stream_format: None,
        reference_audio: parameters.get("reference_audio").cloned(),
        exaggeration: parameters.get("exaggeration").and_then(Value::as_f64),
        cfg_weight: parameters.get("cfg_weight").and_then(Value::as_f64),
        temperature: generation_parameters
            .get("temperature")
            .and_then(Value::as_f64),
        min_p: generation_parameters.get("min_p").and_then(Value::as_f64),
        top_p: generation_parameters.get("top_p").and_then(Value::as_f64),
        repetition_penalty: generation_parameters
            .get("repetition_penalty")
            .and_then(Value::as_f64),
        seed: parameters.get("seed").and_then(Value::as_u64),
        endpoint_family: Some(mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH.to_owned()),
        endpoint_request: Some(raw_request),
    })
}

fn hf_audio_transcription_request(
    model_id: &str,
    raw_request: Value,
    raw_audio: Option<HfRawAudio>,
) -> Result<AudioTranscriptionRequest, ApiError> {
    let (audio, content_type, filename) = if let Some(raw_audio) = raw_audio {
        let descriptor = raw_request
            .get("inputs")
            .and_then(Value::as_object)
            .ok_or_else(|| {
                ApiError::bad_request(
                    "raw HF ASR request is missing its signed input descriptor",
                    Some("inputs"),
                )
            })?;
        let raw_blake3 = blake3_hex(&raw_audio.bytes);
        if descriptor.get("encoding").and_then(Value::as_str) != Some("raw")
            || descriptor.get("bytes").and_then(Value::as_u64)
                != Some(u64::try_from(raw_audio.bytes.len()).unwrap_or(u64::MAX))
            || descriptor.get("blake3").and_then(Value::as_str) != Some(raw_blake3.as_str())
            || descriptor.get("content_type").and_then(Value::as_str)
                != Some(raw_audio.content_type.as_str())
        {
            return Err(ApiError::bad_request(
                "raw HF ASR input descriptor does not match the request body",
                Some("inputs"),
            ));
        }
        (raw_audio.bytes, raw_audio.content_type, raw_audio.filename)
    } else {
        let encoded = raw_request
            .get("inputs")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| ApiError::bad_request("request missing inputs", Some("inputs")))?;
        let audio = BASE64_STANDARD.decode(encoded).map_err(|err| {
            ApiError::bad_request(
                format!("inputs is not valid base64 audio: {err}"),
                Some("inputs"),
            )
        })?;
        let metadata = bounded_audio_metadata(&audio, None)?;
        (
            audio,
            metadata.content_type.to_owned(),
            metadata.filename.to_owned(),
        )
    };
    let audio_seconds = audio_duration_seconds_ceil(&audio).ok_or_else(|| {
        ApiError::bad_request(
            "HF ASR input must be a valid bounded WAV or FLAC file",
            Some("inputs"),
        )
    })?;
    let temperature = raw_request
        .pointer("/parameters/generation_parameters/temperature")
        .and_then(Value::as_f64);
    let timestamp_granularities = match raw_request.pointer("/parameters/return_timestamps") {
        None | Some(Value::Null) | Some(Value::Bool(false)) => Vec::new(),
        Some(Value::Bool(true)) => vec!["segment".to_owned()],
        Some(Value::String(granularity)) if matches!(granularity.as_str(), "word" | "segment") => {
            vec![granularity.clone()]
        }
        Some(_) => {
            return Err(ApiError::bad_request(
                "parameters.return_timestamps must be false, true, word, or segment",
                Some("parameters.return_timestamps"),
            ))
        }
    };
    Ok(AudioTranscriptionRequest {
        model: model_id.to_owned(),
        audio,
        audio_seconds,
        content_type: Some(content_type),
        filename: Some(filename),
        response_format: Some("json".to_owned()),
        language: None,
        prompt: None,
        temperature,
        timestamp_granularities,
        stream: false,
        endpoint_family: mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION.to_owned(),
        contract_request: raw_request,
    })
}

fn artifact_generation_request(
    model_id: &str,
    endpoint_family: &str,
    raw_request: Value,
    video: VideoRequestPreparation,
) -> Result<ArtifactGenerationRequest, ApiError> {
    artifact_generation_request_with_workflow_policy(
        model_id,
        endpoint_family,
        raw_request,
        video,
        None,
    )
}

fn artifact_generation_request_with_workflow_policy(
    model_id: &str,
    endpoint_family: &str,
    raw_request: Value,
    video: VideoRequestPreparation,
    workflow_policy: Option<&mayhem_proto::ComfyWorkflowCatalogPolicy>,
) -> Result<ArtifactGenerationRequest, ApiError> {
    let inline_audio = artifact_generation_inline_audio_load(&raw_request).map_err(|error| {
        ApiError::bad_request(
            format!("invalid inline artifact-generation audio: {error}"),
            Some("request"),
        )
    })?;
    let prompt = artifact_generation_request_value(
        &raw_request,
        endpoint_family,
        ARTIFACT_GENERATION_PROMPT_ALIASES,
    )
    .and_then(Value::as_str)
    .unwrap_or_default()
    .to_owned();
    let duration_seconds = artifact_generation_request_value(
        &raw_request,
        endpoint_family,
        ARTIFACT_GENERATION_DURATION_ALIASES,
    )
    .and_then(generation_duration_seconds_ceil)
    .or_else(|| {
        raw_request
            .get("seconds")
            .and_then(generation_duration_seconds_ceil)
    });
    let normalized_frames = artifact_generation_request_value(
        &raw_request,
        endpoint_family,
        VIDEO_GENERATION_FRAME_ALIASES,
    )
    .and_then(endpoint_positive_integer);
    let frame_rate = artifact_generation_request_value(
        &raw_request,
        endpoint_family,
        VIDEO_GENERATION_FPS_ALIASES,
    )
    .and_then(endpoint_positive_number);
    let (
        output_modality,
        transport_kind,
        duration_seconds,
        requested_frame_count,
        frame_count,
        frame_rate,
        response_format,
        workflow,
        workflow_output,
    ) = match endpoint_family {
        mayhem_proto::ENDPOINT_OPENAI_VIDEOS => {
            let fps = frame_rate.unwrap_or(DEFAULT_VIDEO_GENERATION_FPS as f64);
            let requested_frames = video.requested_frames.unwrap_or_else(|| {
                ((duration_seconds.unwrap_or(4).max(1) as f64) * fps)
                    .floor()
                    .max(1.0) as u64
            });
            let frames = video
                .canonical_frames
                .or(normalized_frames)
                .unwrap_or(requested_frames);
            let duration = ((frames as f64) / fps).ceil().max(1.0) as u64;
            (
                "video",
                "video_generation",
                duration,
                requested_frames,
                frames,
                fps,
                "mp4",
                None,
                None,
            )
        }
        mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO => {
            let frames = video
                .canonical_frames
                .or(normalized_frames)
                .ok_or_else(|| {
                    ApiError::bad_request(
                        "signed HF text-to-video contract did not resolve num_frames",
                        Some("request"),
                    )
                })?;
            let requested_frames = video.requested_frames.unwrap_or(frames);
            let fps = frame_rate.unwrap_or(8.0);
            let duration = ((frames as f64) / fps).ceil().max(1.0) as u64;
            (
                "video",
                "video_generation",
                duration,
                requested_frames,
                frames,
                fps,
                "mp4",
                None,
                None,
            )
        }
        mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS => (
            "audio",
            "music_generation",
            duration_seconds
                .unwrap_or(inline_audio.max_item_seconds.max(1))
                .max(1),
            0,
            0,
            0.0,
            artifact_generation_request_value(
                &raw_request,
                endpoint_family,
                ARTIFACT_GENERATION_FORMAT_ALIASES,
            )
            .and_then(Value::as_str)
            .unwrap_or("wav"),
            None,
            None,
        ),
        mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS => (
            "audio",
            "audio_generation",
            duration_seconds
                .unwrap_or(inline_audio.max_item_seconds.max(1))
                .max(1),
            0,
            0,
            0.0,
            artifact_generation_request_value(
                &raw_request,
                endpoint_family,
                ARTIFACT_GENERATION_FORMAT_ALIASES,
            )
            .and_then(Value::as_str)
            .unwrap_or("wav"),
            None,
            None,
        ),
        mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO => (
            "audio",
            "audio_generation",
            duration_seconds
                .unwrap_or(inline_audio.max_item_seconds.max(1))
                .max(1),
            0,
            0,
            0.0,
            "wav",
            None,
            None,
        ),
        mayhem_proto::ENDPOINT_MAYHEM_COMFY_WORKFLOWS => {
            let workflow_graph = raw_request.get("workflow").ok_or_else(|| {
                ApiError::bad_request("workflow request is missing workflow", Some("workflow"))
            })?;
            let policy = gateway_comfy_workflow_derivation_policy(workflow_policy)
                .map_err(|err| ApiError::bad_request(err.to_string(), Some("workflow")))?;
            let derivation = mayhem_proto::derive_comfy_workflow(workflow_graph, &policy)
                .map_err(|err| ApiError::bad_request(err.to_string(), Some("workflow")))?;
            let output_modality = if derivation
                .outcome_spec
                .output_modalities
                .iter()
                .any(|modality| modality == "video")
            {
                "video"
            } else if derivation
                .outcome_spec
                .output_modalities
                .iter()
                .any(|modality| modality == "audio")
            {
                "audio"
            } else {
                "image"
            };
            let runtime_id = raw_request
                .get("runtime_id")
                .and_then(Value::as_str)
                .unwrap_or_else(|| {
                    workflow_policy
                        .map(|policy| policy.runtime_id())
                        .unwrap_or(mayhem_proto::DEFAULT_COMFY_WORKFLOW_RUNTIME_ID)
                })
                .to_owned();
            let outcome_class = raw_request
                .get("outcome_class")
                .and_then(Value::as_str)
                .map(str::to_owned)
                .unwrap_or_else(|| {
                    workflow_policy
                        .map(|policy| policy.outcome_class_for(output_modality))
                        .unwrap_or_else(|| format!("{output_modality}.workflow"))
                });
            let binding = WorkflowBinding {
                endpoint_family: mayhem_proto::ENDPOINT_MAYHEM_COMFY_WORKFLOWS.to_owned(),
                graph_hash: derivation.graph_hash,
                runtime_id,
                outcome_class,
                quoted_usage: derivation.quoted_usage,
            };
            (
                output_modality,
                "workflow_generation",
                derivation.outcome_spec.duration_seconds.unwrap_or(1).max(1),
                derivation.outcome_spec.frames.unwrap_or(0),
                derivation.outcome_spec.frames.unwrap_or(0),
                frame_rate.unwrap_or(DEFAULT_VIDEO_GENERATION_FPS as f64),
                artifact_generation_request_value(
                    &raw_request,
                    endpoint_family,
                    ARTIFACT_GENERATION_FORMAT_ALIASES,
                )
                .and_then(Value::as_str)
                .unwrap_or("artifact"),
                Some(binding),
                Some(derivation.workflow_output),
            )
        }
        _ => {
            return Err(ApiError::bad_request(
                format!("endpoint family {endpoint_family} is not an artifact generation API"),
                Some("model"),
            ))
        }
    };
    let step_count = artifact_generation_request_value(
        &raw_request,
        endpoint_family,
        ARTIFACT_GENERATION_STEP_ALIASES,
    )
    .and_then(Value::as_u64)
    .or_else(|| {
        artifact_generation_request_value(
            &raw_request,
            endpoint_family,
            &["max_new_tokens", "generation_parameters.max_new_tokens"],
        )
        .and_then(Value::as_u64)
    })
    .unwrap_or(1)
    .max(1);
    let artifact_count = artifact_generation_request_value(
        &raw_request,
        endpoint_family,
        ARTIFACT_GENERATION_COUNT_ALIASES,
    )
    .map(|value| {
        value.as_u64().filter(|count| *count > 0).ok_or_else(|| {
            ApiError::bad_request(
                "signed endpoint contract resolved a non-positive artifact count",
                Some("request"),
            )
        })
    })
    .transpose()?
    .unwrap_or(1);
    let response_format = response_format.to_owned();
    Ok(ArtifactGenerationRequest {
        model: model_id.to_owned(),
        prompt,
        endpoint_family: endpoint_family.to_owned(),
        contract_request: raw_request,
        workflow,
        workflow_output,
        effective_specialities: BTreeMap::new(),
        output_modality: output_modality.to_owned(),
        transport_kind: transport_kind.to_owned(),
        duration_seconds,
        requested_frame_count,
        frame_count,
        frame_rate,
        step_count,
        artifact_count,
        input_image_count: video.inline_image.item_count,
        input_image_max_bytes: video.inline_image.max_item_bytes,
        input_image_max_pixels: video.inline_image.max_item_pixels,
        input_audio_count: inline_audio.item_count,
        input_audio_max_bytes: inline_audio.max_item_bytes,
        input_audio_max_seconds: inline_audio.max_item_seconds,
        response_format,
    })
}

fn gateway_comfy_workflow_derivation_policy(
    workflow_policy: Option<&mayhem_proto::ComfyWorkflowCatalogPolicy>,
) -> Result<mayhem_proto::ComfyWorkflowDerivationPolicy, mayhem_proto::ComfyWorkflowDerivationError>
{
    if let Some(policy) = workflow_policy {
        return policy.derivation_policy();
    }
    Ok(mayhem_proto::ComfyWorkflowDerivationPolicy {
        whitelisted_nodes: [
            "EmptyImage",
            "EmptyLatentImage",
            "PreviewImage",
            "SaveImage",
            "ImageScale",
            "ImageScaleBy",
        ]
        .into_iter()
        .map(str::to_owned)
        .collect::<BTreeSet<_>>(),
        ..mayhem_proto::ComfyWorkflowDerivationPolicy::default()
    })
}

fn artifact_generation_request_value<'a>(
    request: &'a Value,
    endpoint_family: &str,
    aliases: &[&str],
) -> Option<&'a Value> {
    artifact_generation_alias_candidates(endpoint_family, aliases)
        .into_iter()
        .find_map(|path| json_path_value(request, &path))
}

fn generation_duration_seconds_ceil(value: &Value) -> Option<u64> {
    generation_duration_seconds(value).map(|value| value.ceil() as u64)
}

fn generation_duration_seconds(value: &Value) -> Option<f64> {
    endpoint_positive_number(value).filter(|value| *value <= u64::MAX as f64)
}

fn endpoint_positive_number(value: &Value) -> Option<f64> {
    value
        .as_f64()
        .or_else(|| value.as_str()?.parse::<f64>().ok())
        .filter(|value| value.is_finite() && *value > 0.0)
}

fn artifact_generation_response_value(
    request: &ArtifactGenerationRequest,
    run: &CompletedArtifactGeneration,
) -> Value {
    let output = &run.output;
    let artifact_field = match request.endpoint_family.as_str() {
        mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS => "music",
        mayhem_proto::ENDPOINT_MAYHEM_COMFY_WORKFLOWS => "artifact",
        _ => "audio",
    };
    let data = output
        .artifacts
        .iter()
        .map(|artifact| {
            let mut item = json!({
                "id": artifact.id,
                "content_type": artifact.content_type,
                "blake3": artifact.blake3,
            });
            item[artifact_field] = json!(BASE64_STANDARD.encode(&artifact.bytes));
            item
        })
        .collect::<Vec<_>>();
    let first = data.first();
    let id = first
        .and_then(|artifact| artifact.get("id"))
        .cloned()
        .unwrap_or_else(|| json!(make_id("artifact")));
    let encoded = first
        .and_then(|artifact| artifact.get(artifact_field))
        .cloned()
        .unwrap_or_else(|| json!(""));
    let content_type = first
        .and_then(|artifact| artifact.get("content_type"))
        .cloned()
        .unwrap_or_else(|| json!("application/octet-stream"));
    let mayhem = json!({
        "backend": run.backend,
        "direct_session": run.direct_session,
        "billable": run.billable,
        "session_id": run.session_id,
        "artifact_blake3": output.artifacts.first().map(|artifact| artifact.blake3.as_str()),
        "artifacts": artifact_summaries(&output.artifacts),
        "quality": run.quality.map(|quality| json!({
            "ttft_ms": quality.ttft_ms,
            "tok_s": quality.tok_s,
        })),
        "receipt": run.receipt,
    });
    match request.endpoint_family.as_str() {
        mayhem_proto::ENDPOINT_OPENAI_VIDEOS => video_generation_metadata(
            request,
            run,
            &video_job_id(&run.session_id),
            now_secs(),
            DEFAULT_GATEWAY_JOB_TTL_SECONDS,
        ),
        mayhem_proto::ENDPOINT_MAYHEM_COMFY_WORKFLOWS => json!({
            "id": id,
            "object": "workflow.generation",
            "created": now_secs(),
            "model": request.model,
            "status": "completed",
            "artifacts": data,
            "usage": output.usage,
            "mayhem": mayhem,
        }),
        mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS => json!({
            "id": id,
            "object": "music.generation",
            "created": now_secs(),
            "model": request.model,
            "music": encoded,
            "content_type": content_type,
            "data": data,
            "usage": output.usage,
            "mayhem": mayhem,
        }),
        _ => json!({
            "id": id,
            "object": "audio.generation",
            "created": now_secs(),
            "model": request.model,
            "audio": encoded,
            "content_type": content_type,
            "data": data,
            "usage": output.usage,
            "mayhem": mayhem,
        }),
    }
}

fn video_job_id(session_id: &str) -> String {
    let digest = blake3_hex(format!("mayhem-video-job:{session_id}").as_bytes());
    format!("video_{}", &digest[..24])
}

fn video_generation_metadata(
    request: &ArtifactGenerationRequest,
    run: &CompletedArtifactGeneration,
    id: &str,
    created_at: u64,
    ttl_seconds: u64,
) -> Value {
    let artifact = run.output.artifacts.first();
    json!({
        "id": id,
        "object": "video",
        "model": request.model,
        "status": "completed",
        "progress": 100,
        "created_at": created_at,
        "completed_at": created_at,
        "expires_at": created_at.saturating_add(ttl_seconds),
        "error": Value::Null,
        "prompt": request.prompt,
        "size": request.contract_request.get("size").cloned().unwrap_or_else(|| json!("720x1280")),
        "seconds": request.duration_seconds.to_string(),
        "usage": run.output.usage,
        "mayhem": {
            "backend": run.backend,
            "direct_session": run.direct_session,
            "billable": run.billable,
            "session_id": run.session_id,
            "artifact_blake3": artifact.map(|artifact| artifact.blake3.as_str()),
            "video": {
                "requested_frames": request.requested_frame_count,
                "actual_frames": request.frame_count,
                "fps": request.frame_rate,
            },
            "quality": run.quality.map(|quality| json!({
                "ttft_ms": quality.ttft_ms,
                "tok_s": quality.tok_s,
            })),
            "receipt": run.receipt,
        },
    })
}

fn artifact_generation_raw_response(
    request: &ArtifactGenerationRequest,
    run: &CompletedArtifactGeneration,
) -> Result<Response, ApiError> {
    if run.output.artifacts.len() > 1 {
        return Ok(Json(artifact_generation_response_value(request, run)).into_response());
    }
    let artifact = run.output.artifacts.first().ok_or_else(|| {
        ApiError::bad_gateway("artifact generation response is empty", Some("model"))
    })?;
    let mut response = Body::from(artifact.bytes.clone()).into_response();
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_str(&artifact.content_type).map_err(|err| {
            ApiError::bad_gateway(
                format!("invalid artifact content type: {err}"),
                Some("model"),
            )
        })?,
    );
    response.headers_mut().insert(
        "x-mayhem-backend",
        HeaderValue::from_str(&run.backend)
            .map_err(|err| ApiError::bad_gateway(format!("invalid backend header: {err}"), None))?,
    );
    response.headers_mut().insert(
        "x-mayhem-direct-session",
        HeaderValue::from_static(if run.direct_session { "true" } else { "false" }),
    );
    response.headers_mut().insert(
        "x-mayhem-usage",
        HeaderValue::from_str(
            &serde_json::to_string(&run.output.usage).map_err(ApiError::internal)?,
        )
        .map_err(|err| ApiError::bad_gateway(format!("invalid usage header: {err}"), None))?,
    );
    if request.output_modality == "video" {
        response.headers_mut().insert(
            "x-mayhem-video-frames-requested",
            HeaderValue::from_str(&request.requested_frame_count.to_string()).map_err(|err| {
                ApiError::bad_gateway(format!("invalid requested-frame header: {err}"), None)
            })?,
        );
        response.headers_mut().insert(
            "x-mayhem-video-frames-actual",
            HeaderValue::from_str(&request.frame_count.to_string()).map_err(|err| {
                ApiError::bad_gateway(format!("invalid actual-frame header: {err}"), None)
            })?,
        );
    }
    if let Some(receipt) = &run.receipt {
        response.headers_mut().insert(
            "x-mayhem-receipt",
            HeaderValue::from_str(&receipt.to_string()).map_err(|err| {
                ApiError::bad_gateway(format!("invalid receipt header: {err}"), None)
            })?,
        );
    }
    if request.endpoint_family == mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO {
        let sample_rate = wav_sample_rate(&artifact.bytes).ok_or_else(|| {
            ApiError::bad_gateway(
                "HF text-to-audio response is not a valid WAV",
                Some("model"),
            )
        })?;
        response.headers_mut().insert(
            "x-mayhem-sampling-rate",
            HeaderValue::from_str(&sample_rate.to_string()).map_err(|err| {
                ApiError::bad_gateway(format!("invalid sampling-rate header: {err}"), None)
            })?,
        );
    }
    Ok(response)
}

#[derive(Debug, Default, Deserialize)]
struct DashboardQuery {
    token: Option<String>,
    page: Option<String>,
    probe_page: Option<String>,
    kind: Option<String>,
    id: Option<String>,
    provider: Option<String>,
    model: Option<String>,
    enclave: Option<String>,
    room: Option<String>,
    rail: Option<String>,
}

async fn mayhem_dashboard(
    State(state): State<SharedState>,
    OriginalUri(original_uri): OriginalUri,
    Query(query): Query<DashboardQuery>,
    headers: HeaderMap,
) -> Response {
    dashboard_product_response(
        &state,
        &original_uri,
        &query,
        &headers,
        DashboardProductPage::Home,
    )
}

async fn mayhem_dashboard_root_redirect(
    State(state): State<SharedState>,
    Query(query): Query<DashboardQuery>,
    headers: HeaderMap,
) -> Response {
    let authorization = dashboard_request_authorized(&state, &headers, query.token.as_deref());
    let mut response = StatusCode::PERMANENT_REDIRECT.into_response();
    response.headers_mut().insert(
        header::LOCATION,
        HeaderValue::from_static("/mayhem/dashboard"),
    );
    if let Some(authorization) = authorization {
        if let Ok(value) = HeaderValue::from_str(&dashboard_cookie_value(
            &authorization.cookie_name,
            &authorization.browser_token,
        )) {
            response.headers_mut().append(header::SET_COOKIE, value);
        }
    }
    with_dashboard_security_headers(response)
}

async fn mayhem_dashboard_evidence(
    State(state): State<SharedState>,
    OriginalUri(original_uri): OriginalUri,
    Query(query): Query<DashboardQuery>,
    headers: HeaderMap,
) -> Response {
    let wants_json = dashboard_wants_json(&headers);
    let Some(authorization) =
        dashboard_request_authorized(&state, &headers, query.token.as_deref())
    else {
        return if wants_json {
            dashboard_unauthorized_json_response(
                StatusCode::UNAUTHORIZED,
                json!({"ok": false, "error": "dashboard_session_required"}),
                &headers,
            )
        } else {
            dashboard_unauthorized_html_response(dashboard_locked_html(), &headers)
        };
    };
    if let Some(response) = dashboard_bootstrap_redirect(&original_uri, &authorization) {
        return response;
    }
    let browser_token = authorization.browser_token;
    let Some(payload) = dashboard_evidence_payload(&state, &query) else {
        return if wants_json {
            dashboard_json_response(
                StatusCode::NOT_FOUND,
                json!({"ok": false, "error": "dashboard_evidence_not_found"}),
                Some((&authorization.cookie_name, &browser_token)),
            )
        } else {
            dashboard_html_response(
                StatusCode::NOT_FOUND,
                dashboard_html_document(
                    "Evidence not found",
                    r#"<main class="evidence-standalone"><section class="panel"><div class="empty-block"><div class="empty-block-inner"><div class="empty-symbol" aria-hidden="true">&mdash;</div><h1>Evidence not found</h1><p>The requested snapshot is no longer present in this gateway process.</p><a class="primary-button" href="/mayhem/dashboard">Return home</a></div></div></section></main>"#,
                ),
                Some((&authorization.cookie_name, &browser_token)),
            )
        };
    };
    if wants_json {
        dashboard_json_response(
            StatusCode::OK,
            payload,
            Some((&authorization.cookie_name, &browser_token)),
        )
    } else {
        dashboard_html_response(
            StatusCode::OK,
            render_dashboard_evidence_page(&payload),
            Some((&authorization.cookie_name, &browser_token)),
        )
    }
}

fn dashboard_wants_json(headers: &HeaderMap) -> bool {
    headers
        .get(header::ACCEPT)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| {
            value
                .split(',')
                .any(|part| part.trim().starts_with("application/json"))
        })
}

