#[derive(Clone, Debug, PartialEq)]
struct GatewayBillingContext {
    billing_id: String,
    billing_attempt: u32,
    prior_usage: ReceiptUsage,
    prior_au_owed_cum: MoneyAu,
}

impl GatewayBillingContext {
    fn initial(billing_id: String) -> Self {
        Self {
            billing_id,
            billing_attempt: 0,
            prior_usage: ReceiptUsage::default(),
            prior_au_owed_cum: 0,
        }
    }

    fn after_attempt(&self, receipt: Option<&ReceiptBody>) -> Self {
        let Some(receipt) = receipt else {
            return self.clone();
        };
        Self {
            billing_id: self.billing_id.clone(),
            billing_attempt: self.billing_attempt.saturating_add(1),
            prior_usage: receipt.usage.clone(),
            prior_au_owed_cum: receipt.au_owed_cum,
        }
    }
}

