fn canary_registry_from_catalog_root(
    root: &Value,
    canary_sets: &BTreeMap<String, Vec<GatewayCanaryPrompt>>,
) -> GatewayCanaryRegistry {
    let mut models = BTreeMap::new();
    let Some(model_values) = root.get("models").and_then(Value::as_array) else {
        return GatewayCanaryRegistry { models };
    };
    for model in model_values {
        let Some(model_id) = model.get("model_id").and_then(Value::as_str) else {
            continue;
        };
        let Some(canary) = model.get("canary") else {
            continue;
        };
        let Some(canary_set) = canary.get("set_id").and_then(Value::as_str) else {
            continue;
        };
        let requires_launch_evidence = model.get("tier").and_then(Value::as_str) == Some("launch");
        let Some(prompts) = canary_sets.get(canary_set).cloned() else {
            continue;
        };
        let prompts = prompts
            .into_iter()
            .filter(|prompt| !prompt.calibration_only)
            .collect::<Vec<_>>();
        if prompts.is_empty() {
            continue;
        }
        let match_min_bps = canary
            .get("match_min")
            .and_then(Value::as_f64)
            .map(|value| (value * 10_000.0).round().clamp(0.0, 10_000.0) as u32)
            .unwrap_or(DEFAULT_CANARY_MATCH_MIN_BPS);
        let verification_method = canary
            .get("verification_method")
            .and_then(Value::as_str)
            .unwrap_or(CANARY_VERIFICATION_TOKEN_FINGERPRINT)
            .to_owned();
        if !supported_canary_verification_method(&verification_method) {
            continue;
        }
        let verification_tolerance_bps = canary
            .get("verification_tolerance_bps")
            .and_then(Value::as_u64)
            .and_then(|value| u32::try_from(value).ok());
        let fingerprints = canary
            .get("fingerprints")
            .and_then(Value::as_object)
            .into_iter()
            .flat_map(|object| object.iter())
            .filter_map(|(artifact_name, value)| {
                value
                    .as_str()
                    .map(|fingerprint| (artifact_name.as_str(), fingerprint.to_owned()))
            })
            .collect::<BTreeMap<_, _>>();
        let token_prefixes = canary_token_prefixes_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_TOKEN_FINGERPRINT
            && (fingerprints.is_empty() || token_prefixes.is_empty())
        {
            continue;
        }
        let perceptual_hashes = canary_perceptual_hashes_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_SEED_PERCEPTUAL_HASH
            && perceptual_hashes.is_empty()
        {
            continue;
        }
        let embedding_vectors = canary_embedding_vectors_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_EMBEDDING_COSINE
            && embedding_vectors.is_empty()
        {
            continue;
        }
        let transcripts = canary_transcripts_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_TRANSCRIPT_MATCH && transcripts.is_empty() {
            continue;
        }
        let audio_fingerprints = canary_audio_fingerprints_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_AUDIO_FINGERPRINT
            && audio_fingerprints.is_empty()
        {
            continue;
        }
        let video_fingerprints = canary_video_fingerprints_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_VIDEO_AV_FINGERPRINT
            && video_fingerprints.is_empty()
        {
            continue;
        }
        let mut fingerprints_by_artifact_root = BTreeMap::new();
        let mut token_prefixes_by_artifact_root = BTreeMap::new();
        let mut perceptual_hashes_by_artifact_root = BTreeMap::new();
        let mut embedding_vectors_by_artifact_root = BTreeMap::new();
        let mut transcripts_by_artifact_root = BTreeMap::new();
        let mut audio_fingerprints_by_artifact_root = BTreeMap::new();
        let mut video_fingerprints_by_artifact_root = BTreeMap::new();
        let speciality_calibrations = speciality_calibrations_from_catalog_value(model);
        let mut speciality_calibrations_by_artifact_root = BTreeMap::new();
        if let Some(artifacts) = model.get("artifacts").and_then(Value::as_object) {
            for (artifact_name, artifact) in artifacts {
                if let Some(artifact_root) = artifact.get("artifact_root").and_then(Value::as_str) {
                    if let Some(calibrations) = speciality_calibrations.get(artifact_name) {
                        speciality_calibrations_by_artifact_root
                            .insert(artifact_root.to_owned(), calibrations.clone());
                    }
                    if verification_method == CANARY_VERIFICATION_TOKEN_FINGERPRINT {
                        let Some(fingerprint) = fingerprints.get(artifact_name.as_str()) else {
                            continue;
                        };
                        let Some(prefixes) = token_prefixes.get(artifact_name.as_str()) else {
                            continue;
                        };
                        let expected_fingerprint =
                            aggregate_token_prefixes_for_prompts(&prompts, prefixes);
                        if expected_fingerprint.as_deref() != Some(fingerprint.as_str()) {
                            continue;
                        }
                        fingerprints_by_artifact_root
                            .insert(artifact_root.to_owned(), fingerprint.clone());
                        token_prefixes_by_artifact_root
                            .insert(artifact_root.to_owned(), prefixes.clone());
                    } else if let Some(hashes) = perceptual_hashes.get(artifact_name.as_str()) {
                        perceptual_hashes_by_artifact_root
                            .insert(artifact_root.to_owned(), hashes.clone());
                    } else if let Some(vectors) = embedding_vectors.get(artifact_name.as_str()) {
                        embedding_vectors_by_artifact_root
                            .insert(artifact_root.to_owned(), vectors.clone());
                    } else if let Some(expected) = transcripts.get(artifact_name.as_str()) {
                        transcripts_by_artifact_root
                            .insert(artifact_root.to_owned(), expected.clone());
                    } else if let Some(expected) = audio_fingerprints.get(artifact_name.as_str()) {
                        audio_fingerprints_by_artifact_root
                            .insert(artifact_root.to_owned(), expected.clone());
                    } else if let Some(expected) = video_fingerprints.get(artifact_name.as_str()) {
                        video_fingerprints_by_artifact_root
                            .insert(artifact_root.to_owned(), expected.clone());
                    }
                }
            }
        }
        let default_fingerprint = fingerprints.values().next().cloned();
        let default_token_prefixes = token_prefixes.values().next().cloned();
        let default_perceptual_hashes = perceptual_hashes.values().next().cloned();
        let default_embedding_vectors = embedding_vectors.values().next().cloned();
        let default_transcripts = transcripts.values().next().cloned();
        let default_audio_fingerprints = audio_fingerprints.values().next().cloned();
        let default_video_fingerprints = video_fingerprints.values().next().cloned();
        models.insert(
            model_id.to_owned(),
            GatewayCanaryModelConfig {
                canary_set: canary_set.to_owned(),
                requires_launch_evidence,
                match_min_bps,
                verification_method,
                verification_tolerance_bps,
                prompts,
                fingerprints_by_artifact_root,
                token_prefixes_by_artifact_root,
                perceptual_hashes_by_artifact_root,
                embedding_vectors_by_artifact_root,
                transcripts_by_artifact_root,
                audio_fingerprints_by_artifact_root,
                video_fingerprints_by_artifact_root,
                speciality_calibrations_by_artifact_root,
                default_fingerprint,
                default_token_prefixes,
                default_perceptual_hashes,
                default_embedding_vectors,
                default_transcripts,
                default_audio_fingerprints,
                default_video_fingerprints,
            },
        );
    }
    GatewayCanaryRegistry { models }
}

fn canary_token_prefixes_by_artifact(
    canary: &Value,
) -> BTreeMap<String, BTreeMap<String, Vec<i32>>> {
    canary
        .get("token_prefixes")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|object| object.iter())
        .filter_map(|(artifact_name, value)| {
            let prompts = value.as_object()?;
            let prefixes = prompts
                .iter()
                .filter_map(|(prompt_id, raw_tokens)| {
                    let tokens = raw_tokens
                        .as_array()?
                        .iter()
                        .map(|token| token.as_i64().and_then(|token| i32::try_from(token).ok()))
                        .collect::<Option<Vec<_>>>()?;
                    (!tokens.is_empty()).then_some((prompt_id.clone(), tokens))
                })
                .collect::<BTreeMap<_, _>>();
            (!prefixes.is_empty()).then_some((artifact_name.clone(), prefixes))
        })
        .collect()
}

fn canary_perceptual_hashes_by_artifact(
    canary: &Value,
) -> BTreeMap<String, BTreeMap<String, String>> {
    canary
        .get("perceptual_hashes")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|object| object.iter())
        .filter_map(|(artifact_name, value)| {
            let prompts = value.as_object()?;
            let prompts = prompts
                .iter()
                .filter_map(|(prompt_id, hash)| {
                    hash.as_str()
                        .filter(|hash| !hash.is_empty())
                        .map(|hash| (prompt_id.clone(), hash.to_owned()))
                })
                .collect::<BTreeMap<_, _>>();
            (!prompts.is_empty()).then(|| (artifact_name.clone(), prompts))
        })
        .collect()
}

fn canary_embedding_vectors_by_artifact(
    canary: &Value,
) -> BTreeMap<String, BTreeMap<String, Vec<f32>>> {
    canary
        .get("embedding_vectors")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|object| object.iter())
        .filter_map(|(artifact_name, value)| {
            let prompts = value.as_object()?;
            let prompts = prompts
                .iter()
                .filter_map(|(prompt_id, raw_vector)| {
                    let vector = raw_vector
                        .as_array()?
                        .iter()
                        .map(|value| {
                            value.as_f64().and_then(|value| {
                                value
                                    .is_finite()
                                    .then_some(value as f32)
                                    .filter(|value| value.is_finite())
                            })
                        })
                        .collect::<Option<Vec<_>>>()?;
                    (!vector.is_empty()).then_some((prompt_id.clone(), vector))
                })
                .collect::<BTreeMap<_, _>>();
            (!prompts.is_empty()).then(|| (artifact_name.clone(), prompts))
        })
        .collect()
}

fn canary_transcripts_by_artifact(canary: &Value) -> BTreeMap<String, BTreeMap<String, String>> {
    canary
        .get("transcripts")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|object| object.iter())
        .filter_map(|(artifact_name, value)| {
            let prompts = value.as_object()?;
            let prompts = prompts
                .iter()
                .filter_map(|(prompt_id, transcript)| {
                    transcript
                        .as_str()
                        .filter(|transcript| !transcript.trim().is_empty())
                        .map(|transcript| (prompt_id.clone(), transcript.to_owned()))
                })
                .collect::<BTreeMap<_, _>>();
            (!prompts.is_empty()).then(|| (artifact_name.clone(), prompts))
        })
        .collect()
}

