fn aggregate_token_prefixes_for_prompts(
    prompts: &[GatewayCanaryPrompt],
    prefixes: &BTreeMap<String, Vec<i32>>,
) -> Option<String> {
    aggregate_token_prefixes_for_prompt_refs(prompts.iter(), prefixes)
}

fn aggregate_token_prefixes_for_prompt_refs<'a>(
    prompts: impl IntoIterator<Item = &'a GatewayCanaryPrompt>,
    prefixes: &BTreeMap<String, Vec<i32>>,
) -> Option<String> {
    let mut prompt_fingerprints = Vec::new();
    for prompt in prompts {
        let tokens = prefixes.get(&prompt.id)?;
        let fingerprint = token_fingerprint(tokens.iter().copied()).digest;
        prompt_fingerprints.push((prompt.id.as_str(), fingerprint));
    }
    Some(aggregate_canary_fingerprints(
        prompt_fingerprints
            .iter()
            .map(|(prompt_id, fingerprint)| (*prompt_id, fingerprint.as_str())),
    ))
}

fn embedded_canary_sets() -> BTreeMap<String, Vec<GatewayCanaryPrompt>> {
    [
        EMBEDDED_CANARY_DEV_V1,
        EMBEDDED_CANARY_LAUNCH_V1,
        EMBEDDED_CANARY_LAUNCH_V2,
        EMBEDDED_CANARY_IMAGE_LAUNCH_V1,
        EMBEDDED_CANARY_EMBEDDING_LAUNCH_V1,
        EMBEDDED_CANARY_TTS_LAUNCH_V1,
        EMBEDDED_CANARY_STT_LAUNCH_V2,
        EMBEDDED_CANARY_MUSIC_LAUNCH_V1,
    ]
    .into_iter()
    .filter_map(|raw| serde_json::from_str::<CanarySetDocument>(raw).ok())
    .map(|doc| (doc.set_id.clone(), gateway_canary_prompts(doc)))
    .collect()
}

fn gateway_canary_prompts(doc: CanarySetDocument) -> Vec<GatewayCanaryPrompt> {
    doc.prompts
        .into_iter()
        .map(|prompt| GatewayCanaryPrompt {
            id: prompt.id,
            calibration_only: prompt.calibration_only,
            messages: prompt.messages,
            tools: prompt.tools,
            specialities: prompt.specialities,
            max_tokens: prompt.max_tokens.unwrap_or(64).max(1),
            temperature: prompt.temperature,
            top_p: prompt.top_p,
            top_k: prompt.top_k,
            min_p: prompt.min_p,
            repeat_penalty: prompt.repeat_penalty,
            frequency_penalty: prompt.frequency_penalty,
            presence_penalty: prompt.presence_penalty,
            prompt: prompt.prompt,
            input: prompt.input,
            audio_b64: prompt.audio_b64,
            content_type: prompt.content_type,
            filename: prompt.filename,
            language: prompt.language,
            voice: prompt.voice,
            response_format: prompt.response_format,
            require_word_timestamps: prompt.require_word_timestamps,
            require_segment_timestamps: prompt.require_segment_timestamps,
            size: prompt.size,
            steps: prompt.steps,
            cfg_scale: prompt.cfg_scale,
            shift: prompt.shift,
            seed: prompt.seed,
            endpoint_attributes: prompt.endpoint_attributes,
        })
        .collect()
}

fn provider_table_from_models(
    models: &[GatewayModel],
    rules_ver: u64,
    authority: Option<&Arc<GatewayAttestationAuthority>>,
    heartbeat_advertisements: &BTreeMap<ProviderKey, LiveHeartbeatAttestationAdvertisement>,
    tpm_activation_cache: &BTreeMap<ProviderKey, GatewayTpmActivationCacheEntry>,
    verifier_command: Option<&HardwareQuoteVerifierCommand>,
) -> ProviderTable {
    let mut table = ProviderTable::new();
    for model in models {
        for candidate in &model.mayhem.route_candidates {
            table.upsert_contract(contract_snapshot_for_route(
                model,
                candidate,
                rules_ver,
                authority,
                heartbeat_advertisements,
                tpm_activation_cache,
                verifier_command,
            ));
        }
    }
    table
}

fn seed_dev_fallback_heartbeats(
    provider_table: &Arc<Mutex<ProviderTable>>,
    models: &[GatewayModel],
) {
    let now = now_millis_u64();
    let mut table = provider_table.lock_recover("provider table");
    for model in models {
        for candidate in &model.mayhem.route_candidates {
            table.upsert_fallback_heartbeat(heartbeat_for_route(model, candidate, now), now);
        }
    }
}

fn contract_snapshot_for_route(
    model: &GatewayModel,
    candidate: &GatewayRouteCandidate,
    rules_ver: u64,
    authority: Option<&Arc<GatewayAttestationAuthority>>,
    heartbeat_advertisements: &BTreeMap<ProviderKey, LiveHeartbeatAttestationAdvertisement>,
    tpm_activation_cache: &BTreeMap<ProviderKey, GatewayTpmActivationCacheEntry>,
    verifier_command: Option<&HardwareQuoteVerifierCommand>,
) -> ContractProviderSnapshot {
    let price = route_price_ref_au(model, Some(candidate));
    let route_key = route_key(candidate);
    let live_advertisement = heartbeat_advertisements.get(&route_key);
    let attestation_policy = route_attestation_policy_resolution(
        candidate,
        live_advertisement,
        authority,
        tpm_activation_cache,
        verifier_command,
        now_millis_u64(),
    )
    .map_or_else(
        |readiness| readiness,
        |resolved| {
            resolved
                .map(|resolved| resolved.readiness)
                .unwrap_or_else(|| {
                    RouteAttestationPolicyReadiness::not_required(candidate.att_tier)
                })
        },
    );
    ContractProviderSnapshot {
        provider: candidate.provider.clone(),
        provider_status: Some("active".to_owned()),
        enclave_id: candidate.enclave_id.clone(),
        model_id: model.id.clone(),
        room_id: candidate.room_id.clone(),
        consent_ver: rules_ver,
        reputation: f64::from(candidate.reputation_bps.min(10_000)) / 10_000.0,
        price_ver: price.ver,
        rate_map: price.rate_map.clone(),
        per_req_au: price.per_req_au,
        min_session_au: price.min_session_au,
        ref_rate_map: price.rate_map.clone(),
        probation: candidate.probation.clone(),
        caps: heartbeat_caps_for_route(model, candidate),
        attestation_head: Some(candidate.binary_hash.clone()),
        hardware_fingerprint: candidate.hardware_fingerprint.clone(),
        device_key: candidate.device_key.clone(),
        attestation_policy,
    }
}

fn signed_heartbeat_attestation_advertisement(
    signed_raw: &Value,
    heartbeat: &ProviderHeartbeat,
) -> Result<Option<LiveHeartbeatAttestationAdvertisement>, String> {
    let decoded: ProviderHeartbeat = serde_json::from_value(signed_raw.clone())
        .map_err(|err| format!("signed provider heartbeat is invalid: {err}"))?;
    if &decoded != heartbeat {
        return Err(
            "signed provider heartbeat does not match the validated heartbeat record".to_owned(),
        );
    }

    let provider_bytes: [u8; 32] = hex::decode(&heartbeat.provider)
        .map_err(|err| format!("provider heartbeat key is invalid: {err}"))?
        .try_into()
        .map_err(|_| "provider heartbeat key must be 32 bytes".to_owned())?;
    let provider_key = VerifyingKey::from_bytes(&provider_bytes)
        .map_err(|err| format!("provider heartbeat key is invalid: {err}"))?;
    let signature_bytes = hex::decode(&heartbeat.sig)
        .map_err(|err| format!("provider heartbeat signature is invalid: {err}"))?;
    let signature = Signature::from_slice(&signature_bytes)
        .map_err(|err| format!("provider heartbeat signature is invalid: {err}"))?;
    let signing_payload = crate::heartbeat_signing_payload(signed_raw)
        .map_err(|err| format!("provider heartbeat signing payload is invalid: {err}"))?;
    provider_key
        .verify_strict(&signing_payload, &signature)
        .map_err(|err| format!("provider heartbeat signature failed: {err}"))?;

    let attestation = signed_raw
        .get("att")
        .and_then(Value::as_object)
        .ok_or_else(|| "signed provider heartbeat att must be an object".to_owned())?;
    if let Some(unknown) = attestation.keys().find(|field| {
        !matches!(
            field.as_str(),
            "epoch" | "head" | "quote_kind" | "declared_platform" | "tpm_activation_hello"
        )
    }) {
        return Err(format!(
            "signed provider heartbeat att contains unsupported field {unknown}"
        ));
    }
    let quote_kind = match attestation.get("quote_kind") {
        None | Some(Value::Null) => None,
        Some(value) => Some(
            serde_json::from_value::<HardwareQuoteKind>(value.clone())
                .map_err(|err| format!("signed provider heartbeat quote_kind is invalid: {err}"))?,
        ),
    };
    let declared_platform = match attestation.get("declared_platform") {
        None | Some(Value::Null) => None,
        Some(Value::String(platform)) if valid_attestation_platform_hint(platform) => {
            Some(platform.clone())
        }
        Some(Value::String(_)) => {
            return Err("signed provider heartbeat declared_platform is invalid".to_owned())
        }
        Some(_) => {
            return Err("signed provider heartbeat declared_platform must be a string".to_owned())
        }
    };
    let tpm_activation_hello = match attestation.get("tpm_activation_hello") {
        None | Some(Value::Null) => None,
        Some(value) => Some(
            serde_json::from_value::<TpmActivateCredentialHello>(value.clone()).map_err(|err| {
                format!("signed provider heartbeat TPM activation hello is invalid: {err}")
            })?,
        ),
    };
    let Some(kind) = quote_kind else {
        if declared_platform.is_some() || tpm_activation_hello.is_some() {
            return Err(
                "signed provider heartbeat attestation details require quote_kind".to_owned(),
            );
        }
        return Ok(None);
    };
    if tpm_activation_hello.is_some() && kind != HardwareQuoteKind::Tpm2QuoteEk {
        return Err(
            "signed provider heartbeat TPM activation hello requires tpm2_quote_ek".to_owned(),
        );
    }
    Ok(Some(LiveHeartbeatAttestationAdvertisement {
        advertisement: HardwareQuoteRouteAdvertisement {
            kind,
            declared_platform,
        },
        tpm_activation_hello,
        heartbeat_ts: heartbeat.ts,
        transport_peer: heartbeat.transport_peer.clone(),
    }))
}

fn valid_attestation_platform_hint(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 128
        && value.bytes().enumerate().all(|(index, byte)| {
            byte.is_ascii_lowercase()
                || byte.is_ascii_digit()
                || (index > 0 && matches!(byte, b'.' | b'_' | b'-'))
        })
}

fn route_attestation_policy_resolution(
    candidate: &GatewayRouteCandidate,
    live_advertisement: Option<&LiveHeartbeatAttestationAdvertisement>,
    authority: Option<&Arc<GatewayAttestationAuthority>>,
    tpm_activation_cache: &BTreeMap<ProviderKey, GatewayTpmActivationCacheEntry>,
    verifier_command: Option<&HardwareQuoteVerifierCommand>,
    now_millis: u64,
) -> Result<Option<GatewayResolvedRouteAttestation>, RouteAttestationPolicyReadiness> {
    if !matches!(candidate.att_tier, 2 | 3) {
        return Ok(None);
    }

    let mut status = RouteAttestationPolicyReadiness::unavailable(
        candidate.att_tier,
        "authenticated attestation authority is not configured",
    );
    let Some(authority) = authority.cloned() else {
        return Err(status);
    };
    status.evaluated_epoch = Some(authority.policy_epoch);

    let key = route_key(candidate);
    let Some(live_advertisement) = live_advertisement else {
        status.reason = Some("route has no signed heartbeat quote-kind advertisement".to_owned());
        return Err(status);
    };
    let advertisement = &live_advertisement.advertisement;
    status.quote_kind = Some(advertisement.kind);
    if advertisement.kind.attestation_tier() != candidate.att_tier {
        status.reason = Some(format!(
            "quote kind {} proves Tier {}, not route Tier {}",
            advertisement.kind.as_str(),
            advertisement.kind.attestation_tier(),
            candidate.att_tier
        ));
        return Err(status);
    }

    let Some(device_id) = candidate
        .device_key
        .as_deref()
        .filter(|device_id| is_hex_len(device_id, 64))
    else {
        status.reason = Some("route has no canonical 32-byte device identity".to_owned());
        return Err(status);
    };
    let Some(policy) = authority.policy_chain.active_at(authority.policy_epoch) else {
        status.reason =
            Some("no admin attestation policy is active at the ledger epoch".to_owned());
        return Err(status);
    };
    status.policy_sequence = Some(policy.policy().sequence);
    status.policy_digest = Some(policy.digest().to_owned());
    status.policy_effective_epoch = Some(policy.policy().effective_epoch);
    let Some(kind_policy) = policy.quote_kind(advertisement.kind) else {
        status.reason = Some("active policy has no exact quote-kind entry".to_owned());
        return Err(status);
    };
    status.verifier_profile = Some(kind_policy.verifier_profile);
    status.evidence_schema_version = Some(kind_policy.evidence_schema_version);
    status.required_measurement_layers = kind_policy.required_measurement_layers.clone();

    let provisional_binding = HardwareQuoteRoutePolicyBinding {
        enclave_id: candidate.enclave_id.clone(),
        device_id: device_id.to_owned(),
        kind: advertisement.kind,
        evidence_schema_version: kind_policy.evidence_schema_version,
        policy_sequence: policy.policy().sequence,
        policy_digest: policy.digest().to_owned(),
        platform: advertisement.declared_platform.clone(),
    };
    let provisional_context = AttestationPolicyVerificationContext::new(
        &authority.policy_chain,
        &authority.collateral,
        &provisional_binding,
        authority.policy_epoch,
        device_id,
    );

    let mut capabilities = native_gateway_attestation_capabilities();
    if managed_quote_kind(advertisement.kind) {
        let Some(command) = verifier_command else {
            status.reason = Some(format!(
                "policy-authenticated {} verifier is not installed",
                advertisement.kind.as_str()
            ));
            return Err(status);
        };
        let managed = match crate::attestation_policy::authenticate_managed_verifier(
            &provisional_context,
            advertisement.kind,
            command,
        ) {
            Ok(managed) => managed,
            Err(reason) => {
                status.reason = Some(reason);
                return Err(status);
            }
        };
        capabilities.version = capabilities.version.max(managed.capabilities.version);
        capabilities.profiles.extend(managed.capabilities.profiles);
    }

    let readiness = AttestationReadiness::evaluate(
        &authority.policy_chain,
        &authority.collateral,
        &capabilities,
        authority.policy_epoch,
    );
    let route_binding = match readiness.bind_route(&candidate.enclave_id, device_id, advertisement)
    {
        Ok(binding) => binding,
        Err(error) => {
            status.reason = Some(error.to_string());
            return Err(status);
        }
    };
    let enclave_binding = match readiness.enclave_binding(&route_binding) {
        Ok(binding) => binding,
        Err(error) => {
            status.reason = Some(error.to_string());
            return Err(status);
        }
    };
    let actual_layers = enclave_binding
        .measurement_trust_data
        .keys()
        .copied()
        .collect::<BTreeSet<_>>();
    if actual_layers != kind_policy.required_measurement_layers {
        status.reason =
            Some("enclave binding does not carry every policy-required layer".to_owned());
        return Err(status);
    }

    let activated_tpm_identity = if advertisement.kind == HardwareQuoteKind::Tpm2QuoteEk {
        let Some(hello) = live_advertisement.tpm_activation_hello.as_ref() else {
            status.reason = Some("route has no signed TPM ActivateCredential hello".to_owned());
            return Err(status);
        };
        let hello_digest = match tpm_activation_hello_digest(hello) {
            Ok(digest) => digest,
            Err(reason) => {
                status.reason = Some(reason);
                return Err(status);
            }
        };
        let transport_peer = live_advertisement
            .transport_peer
            .as_deref()
            .filter(|peer| is_hex_len(peer, 64));
        let binding = transport_peer.map(|transport_peer| GatewayTpmActivationCacheBinding {
            policy_sequence: route_binding.policy_sequence,
            policy_digest: route_binding.policy_digest.clone(),
            device_id: route_binding.device_id.clone(),
            transport_peer: transport_peer.to_owned(),
            ek_public_spki_der_b64: hello.ek_public_spki_der_b64.clone(),
            ak_name_b64: hello.ak_name_b64.clone(),
            hello_digest,
        });
        let identity = binding.as_ref().and_then(|binding| {
            reusable_tpm_activation_entry(tpm_activation_cache, &key, binding, now_millis)
        });
        let Some(identity) = identity.map(|entry| entry.identity.clone()) else {
            status.tpm_activation_pending = transport_peer.is_some();
            status.reason = Some(if transport_peer.is_some() {
                "gateway has not completed TPM ActivateCredential for this signed route state"
                    .to_owned()
            } else {
                "route has no valid signed transport peer for TPM activation".to_owned()
            });
            return Err(status);
        };
        Some(identity)
    } else {
        None
    };

    status.locally_ready = true;
    status.reason = None;
    Ok(Some(GatewayResolvedRouteAttestation {
        readiness: status,
        authority,
        route_binding,
        activated_tpm_identity,
    }))
}

fn tpm_activation_hello_digest(hello: &TpmActivateCredentialHello) -> Result<String, String> {
    serde_json::to_value(hello)
        .and_then(|value| stable_json_bytes(&value))
        .map(|bytes| blake3_hex(&bytes))
        .map_err(|err| format!("signed TPM activation hello is not canonical JSON: {err}"))
}

fn tpm_activation_cache_entry_survives_catalog_refresh(
    key: &ProviderKey,
    expires_at_millis: u64,
    valid_route_keys: &BTreeSet<ProviderKey>,
    now_millis: u64,
) -> bool {
    expires_at_millis > now_millis && valid_route_keys.contains(key)
}

fn tpm_activation_ownership_scope(
    key: &ProviderKey,
    binding: &GatewayTpmActivationCacheBinding,
) -> GatewayTpmActivationOwnershipScope {
    GatewayTpmActivationOwnershipScope {
        provider: key.provider.clone(),
        policy_sequence: binding.policy_sequence,
        policy_digest: binding.policy_digest.clone(),
        device_id: binding.device_id.clone(),
        transport_peer: binding.transport_peer.clone(),
        ek_public_spki_der_b64: binding.ek_public_spki_der_b64.clone(),
        ak_name_b64: binding.ak_name_b64.clone(),
    }
}

fn reusable_tpm_activation_entry<'a>(
    cache: &'a BTreeMap<ProviderKey, GatewayTpmActivationCacheEntry>,
    key: &ProviderKey,
    binding: &GatewayTpmActivationCacheBinding,
    now_millis: u64,
) -> Option<&'a GatewayTpmActivationCacheEntry> {
    if let Some(exact) = cache
        .get(key)
        .filter(|entry| entry.expires_at_millis > now_millis && entry.binding == *binding)
    {
        return Some(exact);
    }
    let scope = tpm_activation_ownership_scope(key, binding);
    cache.iter().find_map(|(cached_key, entry)| {
        (entry.expires_at_millis > now_millis
            && tpm_activation_ownership_scope(cached_key, &entry.binding) == scope)
            .then_some(entry)
    })
}

fn native_gateway_attestation_capabilities() -> VerifierCapabilities {
    VerifierCapabilities::with_evidence_schemas(
        GATEWAY_ATTESTATION_VERIFIER_VERSION,
        BTreeMap::from([
            (
                AttestationVerifierProfile::AppleAppAttestNativeV1,
                BTreeSet::from([1]),
            ),
            (
                AttestationVerifierProfile::NvidiaGb10DeviceV1,
                BTreeSet::from([1]),
            ),
            (
                AttestationVerifierProfile::Tpm2EkActivateCredentialV1,
                BTreeSet::from([1]),
            ),
        ]),
    )
}

fn managed_quote_kind(kind: HardwareQuoteKind) -> bool {
    matches!(
        kind,
        HardwareQuoteKind::AmdSevSnpVcek
            | HardwareQuoteKind::IntelTdxDcap
            | HardwareQuoteKind::NvidiaNrasJwt
            | HardwareQuoteKind::NvidiaNvtrustOfflineJwt
    )
}

fn heartbeat_for_route(
    model: &GatewayModel,
    candidate: &GatewayRouteCandidate,
    now_millis: u64,
) -> ProviderHeartbeat {
    let price = route_price_ref_au(model, Some(candidate));
    ProviderHeartbeat {
        t: "hb".to_owned(),
        v: crate::HEARTBEAT_SCHEMA_VERSION,
        contract_version: CONTRACT_VERSION,
        provider: candidate.provider.clone(),
        enclave_id: candidate.enclave_id.clone(),
        model_id: model.id.clone(),
        room_id: candidate.room_id.clone(),
        sat: 0.0,
        slots: HeartbeatSlots {
            active: 0,
            active_requests: 0,
            max: 1,
        },
        q: HeartbeatQueue {
            free_slots: 1,
            engine_backlog: 0,
            est_wait_ms: 0,
        },
        perf: HeartbeatPerf {
            tok_s: Some(50.0),
            ttft_ms: 150,
        },
        price_ver: price.ver,
        min_ask_au: candidate.min_ask_au,
        transport_peer: Some(candidate.provider.clone()),
        identity_anchor: route_identity_anchor(candidate),
        inventory_root: None,
        runtime_id: None,
        workflow_classes: BTreeMap::new(),
        accepting_new: true,
        caps: heartbeat_caps_for_route(model, candidate),
        att: HeartbeatAttestation {
            epoch: 1,
            head: candidate.binary_hash.clone(),
        },
        ts: now_millis,
        nonce: blake3_hex(
            format!(
                "route:{}:{}:{}:{now_millis}",
                candidate.provider, candidate.enclave_id, candidate.room_id
            )
            .as_bytes(),
        ),
        sig: String::new(),
    }
}

fn route_identity_anchor(candidate: &GatewayRouteCandidate) -> Option<String> {
    candidate
        .device_key
        .as_deref()
        .map(|value| format!("device:{}", value.to_ascii_lowercase()))
        .or_else(|| {
            candidate
                .hardware_fingerprint
                .as_deref()
                .map(|value| format!("fingerprint:{}", value.to_ascii_lowercase()))
        })
}

fn heartbeat_caps_from_model(
    caps: &ModelCaps,
    modalities: &[String],
    specialities: &[ModelSpecialityDescriptor],
) -> HeartbeatCaps {
    HeartbeatCaps {
        tools: caps.tools,
        json: caps.json,
        ctx: caps.ctx,
        vision: caps.vision,
        served_modalities: modalities.to_vec(),
        modality_capacity: BTreeMap::new(),
        served_specialities: specialities
            .iter()
            .map(|descriptor| {
                (
                    descriptor.name.clone(),
                    descriptor
                        .levels
                        .iter()
                        .map(|level| level.name.clone())
                        .collect(),
                )
            })
            .collect(),
    }
}

fn heartbeat_caps_for_route(
    model: &GatewayModel,
    candidate: &GatewayRouteCandidate,
) -> HeartbeatCaps {
    let fallback = heartbeat_caps_from_model(
        &model.mayhem.caps,
        &model.mayhem.adapter.modality_set,
        &model.mayhem.adapter.specialities,
    );
    HeartbeatCaps {
        tools: candidate
            .caps
            .get("tools")
            .and_then(Value::as_bool)
            .unwrap_or(fallback.tools),
        json: candidate
            .caps
            .get("json")
            .and_then(Value::as_bool)
            .unwrap_or(fallback.json),
        ctx: candidate
            .served_ctx
            .filter(|ctx| *ctx > 0)
            .or_else(|| {
                candidate
                    .caps
                    .get("ctx")
                    .or_else(|| candidate.caps.get("ctx_max"))
                    .and_then(Value::as_u64)
                    .and_then(|ctx| u32::try_from(ctx).ok())
            })
            .unwrap_or(fallback.ctx),
        vision: candidate
            .caps
            .get("vision")
            .and_then(Value::as_bool)
            .unwrap_or(fallback.vision),
        served_modalities: candidate.served_modalities.clone(),
        modality_capacity: candidate
            .caps
            .get("modality_capacity")
            .cloned()
            .and_then(|value| serde_json::from_value(value).ok())
            .unwrap_or_default(),
        served_specialities: candidate.served_specialities.clone(),
    }
}

fn route_caps_ctx(model: &GatewayModel, candidate: &GatewayRouteCandidate) -> u32 {
    heartbeat_caps_for_route(model, candidate).ctx
}

fn model_served_ctx(model: &GatewayModel) -> u32 {
    model.mayhem.caps.ctx
}

fn sanitize_gateway_models(models: Vec<GatewayModel>) -> Vec<GatewayModel> {
    models
        .into_iter()
        .filter_map(|mut model| {
            model
                .mayhem
                .route_candidates
                .retain(canonical_route_candidate);
            model.mayhem.markets.retain(canonical_market_info);
            model.mayhem.markets.sort_by(|left, right| {
                left.att_tier
                    .cmp(&right.att_tier)
                    .then_with(|| left.quant.cmp(&right.quant))
                    .then_with(|| left.ctx_bracket.cmp(&right.ctx_bracket))
                    .then_with(|| left.enclave_id.cmp(&right.enclave_id))
            });
            model.mayhem.markets.dedup_by(|left, right| {
                left.enclave_id == right.enclave_id && left.ctx_bracket == right.ctx_bracket
            });
            if !model.mayhem.route_candidates.is_empty() {
                let providers = model
                    .mayhem
                    .route_candidates
                    .iter()
                    .map(|candidate| candidate.provider.as_str())
                    .collect::<BTreeSet<_>>();
                let rooms = model
                    .mayhem
                    .route_candidates
                    .iter()
                    .map(|candidate| candidate.room_id.as_str())
                    .collect::<BTreeSet<_>>();
                model.mayhem.providers_online = providers.len().min(u32::MAX as usize) as u32;
                if model.mayhem.markets.is_empty() {
                    model.mayhem.rooms = rooms.len().min(u32::MAX as usize) as u32;
                }
            }
            if !model.mayhem.markets.is_empty() {
                let rooms = model
                    .mayhem
                    .markets
                    .iter()
                    .flat_map(|market| market.room_ids.iter().map(String::as_str))
                    .collect::<BTreeSet<_>>();
                model.mayhem.rooms = rooms.len().min(u32::MAX as usize) as u32;
            }
            if model.mayhem.source == "contract" && model.mayhem.route_candidates.is_empty() {
                model.mayhem.providers_online = 0;
            }
            if model.mayhem.source == "contract"
                && model.mayhem.route_candidates.is_empty()
                && model.mayhem.markets.is_empty()
            {
                return None;
            }
            Some(model)
        })
        .collect()
}

fn canonical_route_candidate(candidate: &GatewayRouteCandidate) -> bool {
    is_hex_len(&candidate.provider, 64)
        && is_hex_len(&candidate.enclave_id, 64)
        && is_hex_len(&candidate.room_id, 32)
        && is_hex_len(&candidate.admin_pubkey, 64)
        && is_hex_len(&candidate.artifact_root, 64)
        && candidate
            .artifact_sidecar_roots
            .values()
            .all(|root| is_hex_len(root, 64))
        && is_hex_len(&candidate.manifest_hash, 64)
        && is_hex_len(&candidate.binary_hash, 64)
}

fn canonical_market_info(market: &GatewayMarketInfo) -> bool {
    let availability_matches_routes = match market.availability.as_str() {
        "routable" => market.route_count > 0 && market.providers_online > 0,
        "no_eligible_provider_yet" => market.route_count == 0 && market.providers_online == 0,
        _ => false,
    };
    is_hex_len(&market.enclave_id, 64)
        && (1..=3).contains(&market.att_tier)
        && !market.room_ids.is_empty()
        && market
            .room_ids
            .iter()
            .all(|room_id| is_hex_len(room_id, 32))
        && market.providers_online <= market.route_count
        && market.price_ref_au.denom == "au_usd"
        && !market.price_ref_au.rate_map.is_empty()
        && availability_matches_routes
}

impl GatewaySessionError {
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            failure_class: GatewaySessionFailureClass::ProviderFault,
            retryable: false,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: None,
        }
    }

    pub fn retryable(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            failure_class: GatewaySessionFailureClass::ProviderFault,
            retryable: true,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: None,
        }
    }

    pub fn retryable_before_output(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            failure_class: GatewaySessionFailureClass::ProviderFault,
            retryable: true,
            before_first_output: true,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: None,
        }
    }

    pub fn transport_closed(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            failure_class: GatewaySessionFailureClass::ProviderFault,
            retryable: true,
            before_first_output: false,
            transport_closed: true,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: None,
        }
    }

    fn wait_elapsed(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            failure_class: GatewaySessionFailureClass::ProviderFault,
            retryable: true,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: true,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: None,
        }
    }

    pub fn clean_refusal(message: impl Into<String>) -> Self {
        Self::clean_refusal_with_code(message, None)
    }

    pub fn clean_refusal_with_code(message: impl Into<String>, code: Option<&str>) -> Self {
        Self {
            message: message.into(),
            failure_class: GatewaySessionFailureClass::ProviderFault,
            retryable: true,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: true,
            clean_refusal_code: code.map(str::to_owned),
            partial: None,
            interrupted: None,
        }
    }

    pub fn retryable_partial(message: impl Into<String>, partial: GatewaySessionPartial) -> Self {
        Self {
            message: message.into(),
            failure_class: GatewaySessionFailureClass::ProviderFault,
            retryable: true,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: Some(Box::new(partial)),
            interrupted: None,
        }
    }

    pub fn retryable_interrupted(
        message: impl Into<String>,
        interrupted: GatewaySessionInterrupted,
    ) -> Self {
        Self {
            message: message.into(),
            failure_class: GatewaySessionFailureClass::ProviderFault,
            retryable: true,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: Some(Box::new(interrupted)),
        }
    }

    fn buyer_local(message: impl Into<String>) -> Self {
        let mut error = Self::new(message);
        error.failure_class = GatewaySessionFailureClass::BuyerLocal;
        error
    }

    fn buyer_local_transport_closed(message: impl Into<String>) -> Self {
        let mut error = Self::transport_closed(message);
        error.failure_class = GatewaySessionFailureClass::BuyerLocal;
        error
    }

    fn request_scoped(message: impl Into<String>) -> Self {
        let mut error = Self::new(message);
        error.failure_class = GatewaySessionFailureClass::RequestScoped;
        error
    }

    pub fn into_retryable(mut self) -> Self {
        self.retryable = true;
        self
    }

    fn into_retryable_before_output(mut self) -> Self {
        self.retryable = true;
        self.before_first_output = true;
        self
    }

    fn into_retryable_partial(mut self, partial: GatewaySessionPartial) -> Self {
        self.retryable = true;
        self.partial = Some(Box::new(partial));
        self
    }
}

fn provider_reported_session_error(
    frame: &Value,
    session_context: &str,
    retryable: bool,
) -> GatewaySessionError {
    let code = frame
        .get("code")
        .and_then(Value::as_str)
        .unwrap_or("provider_error");
    let message = frame
        .get("message")
        .and_then(Value::as_str)
        .unwrap_or("provider returned s.error");
    let message = format!("provider returned {code} on {session_context}: {message}");
    match code {
        "request_invalid" | "request_chunk_failed" | "request_reassembly_failed" => {
            GatewaySessionError::buyer_local(message)
        }
        "model_output_invalid" => GatewaySessionError::request_scoped(message),
        _ if retryable => GatewaySessionError::retryable(message),
        _ => GatewaySessionError::new(message),
    }
}

fn request_scoped_api_error(error: &GatewaySessionError) -> Option<ApiError> {
    error
        .failure_class
        .is_request_scoped()
        .then(|| ApiError::bad_request(error.message.clone(), Some("model")))
}

