fn signed_tools_only_chat_contract<'a>(
    model: &'a GatewayModel,
    request: &ChatCompletionRequest,
) -> Option<&'a EndpointFamilyContract> {
    model
        .mayhem
        .adapter
        .endpoint_families
        .iter()
        .find(|contract| contract.family == direct_chat_endpoint_family(request))
        .filter(|contract| {
            contract
                .required_request_attributes
                .iter()
                .any(|attribute| attribute == "tools")
                && contract
                    .request_attribute_specs
                    .get("tools")
                    .and_then(|spec| spec.min_items)
                    .is_some_and(|min_items| min_items > 0)
        })
}

fn tools_only_prompt_token_units(
    model: &GatewayModel,
    request: &ChatCompletionRequest,
    served_ctx: u32,
) -> Result<Option<u64>, GatewaySessionError> {
    if signed_tools_only_chat_contract(model, request).is_none() {
        return Ok(None);
    }
    let transport_body = direct_session_request_body(request);
    let normalized_request = direct_chat_contract_request(request, &transport_body);
    let has_tools = normalized_request
        .get("tools")
        .and_then(Value::as_array)
        .is_some_and(|tools| !tools.is_empty());
    if !has_tools {
        return Err(GatewaySessionError::new(
            "signed tools-only endpoint requires at least one normalized tool",
        ));
    }
    let prompt_units = tools_only_model_input_prompt_units(
        direct_chat_endpoint_family(request),
        &normalized_request,
    )
    .map_err(|err| {
        GatewaySessionError::new(format!("failed to meter tools-only model input: {err}"))
    })?;
    if prompt_units == 0 {
        return Err(GatewaySessionError::new(
            "tools-only model input produced zero prompt units",
        ));
    }
    if prompt_units > u64::from(served_ctx) {
        return Err(GatewaySessionError::new(format!(
            "normalized tools-only request requires {prompt_units} prompt units, exceeding served context {served_ctx}"
        )));
    }
    Ok(Some(prompt_units))
}

fn verified_tools_only_prompt_tokens(
    provider_usage: &ReceiptUsage,
    expected: u64,
) -> Result<u64, GatewaySessionError> {
    let prompt_tokens = provider_usage.prompt_tokens();
    if prompt_tokens != expected {
        return Err(GatewaySessionError::new(format!(
            "tools-only provider receipt prompt usage {prompt_tokens} does not match buyer-derived normalized request usage {expected}"
        )));
    }
    Ok(prompt_tokens)
}

fn direct_session_contract_request(transport_body: &Value) -> Value {
    let mut request = transport_body.clone();
    if let Some(object) = request.as_object_mut() {
        object.remove("kind");
        object.remove("endpoint_family");
        object.remove("mayhem_contract");
        object.remove("contract_request");
        object.remove("specialities");
    }
    request
}

fn seal_direct_session_request_body(
    model: &GatewayModel,
    endpoint_family: &str,
    transport_body: Value,
    contract_request: Value,
) -> Result<Value, GatewaySessionError> {
    seal_direct_session_request_body_with_workflow_output(
        model,
        endpoint_family,
        transport_body,
        contract_request,
        None,
    )
}

fn seal_direct_session_request_body_with_workflow_output(
    model: &GatewayModel,
    endpoint_family: &str,
    transport_body: Value,
    contract_request: Value,
    workflow_output: Option<&WorkflowOutputBinding>,
) -> Result<Value, GatewaySessionError> {
    let contract = model
        .mayhem
        .adapter
        .endpoint_families
        .iter()
        .find(|contract| contract.family == endpoint_family)
        .ok_or_else(|| {
            GatewaySessionError::new(format!(
                "model {} does not expose endpoint family {endpoint_family}",
                model.id
            ))
        })?;
    if let Err(violations) = mayhem_proto::validate_endpoint_request(contract, &contract_request) {
        let summary = violations
            .iter()
            .take(4)
            .map(|violation| format!("{}: {}", violation.path, violation.reason))
            .collect::<Vec<_>>()
            .join("; ");
        return Err(GatewaySessionError::new(format!(
            "normalized provider request violates endpoint contract: {summary}"
        )));
    }
    let mut sealed = json!({});
    for key in ["kind", "audio", "audio_seconds"] {
        if let Some(value) = transport_body.get(key) {
            sealed[key] = value.clone();
        }
    }
    let transport_request_fingerprint = stable_value_hash(&sealed);
    sealed["contract_request"] = contract_request.clone();
    sealed["mayhem_contract"] = json!({
        "schema_version": 1,
        "endpoint_family": endpoint_family,
        "endpoint_contract_fingerprint": mayhem_proto::endpoint_contract_fingerprint(contract),
        "normalized_request_fingerprint": mayhem_proto::endpoint_request_fingerprint(&contract_request),
        "transport_request_fingerprint": transport_request_fingerprint,
    });
    if let Some(workflow_output) = workflow_output {
        sealed["mayhem_contract"]["workflow_output"] = serde_json::to_value(workflow_output)
            .map_err(|err| {
                GatewaySessionError::new(format!("workflow output binding failed: {err}"))
            })?;
    }
    Ok(sealed)
}

