fn ensure_final_receipt_within_voucher(
    invocation: &GatewaySessionInvocation,
    au_owed_cum: MoneyAu,
) -> Result<(), GatewaySessionError> {
    if locked_increment_exceeds_voucher(invocation, au_owed_cum) {
        return Err(GatewaySessionError::new(
            "provider receipt exceeds signed spend voucher",
        ));
    }
    Ok(())
}

fn expected_text_usage_for_provider(
    provider_usage: Option<&ReceiptUsage>,
    observed_prompt_tokens: u64,
    observed_completion_tokens: u64,
    locked_rate_map: &[RateMapEntry],
    protocol_prompt_tokens: Option<u64>,
) -> Result<ReceiptUsage, GatewaySessionError> {
    if let (Some(provider_usage), Some(expected_prompt_tokens)) =
        (provider_usage, protocol_prompt_tokens)
    {
        verified_tools_only_prompt_tokens(provider_usage, expected_prompt_tokens)?;
        if provider_usage.output_tokens() != observed_completion_tokens {
            return Err(GatewaySessionError::new(
                "tools-only provider receipt output usage mismatch",
            ));
        }
        if provider_usage.cached_input_tokens() > 0
            && !locked_rate_map
                .iter()
                .any(|entry| entry.unit == USAGE_CACHED_INPUT_TOKEN)
        {
            return Err(GatewaySessionError::new(
                "provider receipt claimed cached input but locked rate_map lacks cached_input_token",
            ));
        }
        return Ok(provider_usage.clone());
    }
    let Some(provider_usage) = provider_usage else {
        return Ok(ReceiptUsage::text(
            observed_prompt_tokens,
            observed_completion_tokens,
        ));
    };
    if provider_usage.cached_input_tokens() == 0 {
        return Ok(ReceiptUsage::text(
            observed_prompt_tokens,
            observed_completion_tokens,
        ));
    }
    if !locked_rate_map
        .iter()
        .any(|entry| entry.unit == USAGE_CACHED_INPUT_TOKEN)
    {
        return Err(GatewaySessionError::new(
            "provider receipt claimed cached input but locked rate_map lacks cached_input_token",
        ));
    }
    if provider_usage.prompt_tokens() != observed_prompt_tokens {
        return Err(GatewaySessionError::new(
            "provider receipt cached prompt usage mismatch",
        ));
    }
    if provider_usage.output_tokens() != observed_completion_tokens {
        return Err(GatewaySessionError::new(
            "provider receipt cached output usage mismatch",
        ));
    }
    Ok(provider_usage.clone())
}

fn expected_chat_usage_for_provider(
    request: &ChatCompletionRequest,
    provider_usage: Option<&ReceiptUsage>,
    observed_prompt_tokens: u64,
    observed_completion_tokens: u64,
    locked_rate_map: &[RateMapEntry],
    protocol_prompt_tokens: Option<u64>,
) -> Result<ReceiptUsage, GatewaySessionError> {
    let text = expected_text_usage_for_provider(
        provider_usage,
        observed_prompt_tokens,
        observed_completion_tokens,
        locked_rate_map,
        protocol_prompt_tokens,
    )?;
    chat_media_stats(&request.messages, &GatewayMediaLimits::schema_ceiling())
        .map_err(|err| GatewaySessionError::new(err.message))?;
    if let Some(provider_usage) = provider_usage {
        if provider_usage.get(USAGE_IMAGE) != 0 {
            return Err(GatewaySessionError::new(
                "provider receipt must not double-bill LLM image input outside input tokens",
            ));
        }
        if provider_usage.get(USAGE_AUDIO_SECOND) != 0 {
            return Err(GatewaySessionError::new(
                "provider receipt must not double-bill LLM audio input outside input tokens",
            ));
        }
    }
    Ok(ReceiptUsage::from_units([
        (USAGE_INPUT_TOKEN, text.input_tokens()),
        (USAGE_CACHED_INPUT_TOKEN, text.cached_input_tokens()),
        (USAGE_OUTPUT_TOKEN, text.output_tokens()),
    ]))
}

fn expected_chat_usage_for_invocation(
    model: &GatewayModel,
    request: &ChatCompletionRequest,
    provider_usage: Option<&ReceiptUsage>,
    observed_prompt_tokens: u64,
    observed_completion_tokens: u64,
    locked_rate_map: &[RateMapEntry],
    invocation: &GatewaySessionInvocation,
) -> Result<ReceiptUsage, GatewaySessionError> {
    let protocol_prompt_tokens =
        tools_only_prompt_token_units(model, request, invocation.served_ctx)?;
    let prior_usage = &invocation.spend_voucher.body.billing_prior_usage;
    let prior_au_owed_cum = invocation.spend_voucher.body.billing_prior_au_owed_cum;
    if prior_au_owed_cum == 0 && prior_usage != &ReceiptUsage::default() {
        return Err(GatewaySessionError::new(
            "billing prior usage requires a nonzero prior cumulative amount",
        ));
    }
    if let Some(provider_usage) = provider_usage {
        if !provider_usage.is_monotonic_from(prior_usage) {
            return Err(GatewaySessionError::new(
                "provider receipt usage regressed across logical billing attempts",
            ));
        }
    }
    let local_provider_usage = provider_usage
        .filter(|_| prior_au_owed_cum == 0)
        .map(|usage| ReceiptUsage::saturating_delta(prior_usage, usage));
    let local_usage = expected_chat_usage_for_provider(
        request,
        local_provider_usage.as_ref(),
        observed_prompt_tokens,
        observed_completion_tokens,
        locked_rate_map,
        protocol_prompt_tokens,
    )?;
    let increment = if prior_au_owed_cum == 0 {
        local_usage
    } else {
        ReceiptUsage::from_units([(USAGE_OUTPUT_TOKEN, local_usage.output_tokens())])
    };
    Ok(prior_usage.saturating_add(&increment))
}

fn validate_provider_receipt(
    model: &GatewayModel,
    invocation: &GatewaySessionInvocation,
    provider_receipt: &ProviderSignedReceipt,
    expected: ExpectedProviderReceipt<'_>,
) -> Result<(), GatewaySessionError> {
    if invocation.spend_voucher.body.schema_version != SESSION_RECEIPT_SCHEMA_VERSION {
        return Err(GatewaySessionError::new(format!(
            "spend voucher schema_version must be {SESSION_RECEIPT_SCHEMA_VERSION}"
        )));
    }
    if provider_receipt.body.schema_version != SESSION_RECEIPT_SCHEMA_VERSION {
        return Err(GatewaySessionError::new(format!(
            "provider receipt schema_version must be {SESSION_RECEIPT_SCHEMA_VERSION}"
        )));
    }
    let body = provider_receipt.body.clone();
    validate_usage_attribution(&body.usage, &body.usage_attribution)?;
    let checks = [
        (
            body.session_id == invocation.session_id,
            "provider receipt session_id mismatch",
        ),
        (
            body.billing_id == invocation.spend_voucher.body.billing_id,
            "provider receipt billing_id mismatch",
        ),
        (
            body.billing_attempt == invocation.spend_voucher.body.billing_attempt,
            "provider receipt billing_attempt mismatch",
        ),
        (
            body.billing_prior_usage == invocation.spend_voucher.body.billing_prior_usage,
            "provider receipt billing prior usage mismatch",
        ),
        (
            body.billing_prior_au_owed_cum
                == invocation.spend_voucher.body.billing_prior_au_owed_cum,
            "provider receipt billing prior amount mismatch",
        ),
        (
            body.billing_epoch == invocation.spend_voucher.body.billing_epoch,
            "provider receipt billing epoch mismatch",
        ),
        (
            body.reservation_id == invocation.spend_voucher.body.reservation_id,
            "provider receipt reservation id mismatch",
        ),
        (
            body.payout_revision == invocation.spend_voucher.body.payout_revision,
            "provider receipt payout revision mismatch",
        ),
        (body.seq == expected.seq, "provider receipt seq mismatch"),
        (
            body.final_receipt == expected.final_receipt,
            "provider receipt finality mismatch",
        ),
        (
            body.rail == invocation.rail,
            "provider receipt rail mismatch",
        ),
        (
            body.user == invocation.user_pubkey && body.user == invocation.spend_voucher.body.user,
            "provider receipt user mismatch",
        ),
        (
            body.provider == expected.provider
                && body.provider == invocation.spend_voucher.body.provider,
            "provider receipt provider mismatch",
        ),
        (
            body.enclave_id == invocation.enclave_id,
            "provider receipt enclave mismatch",
        ),
        (
            body.model_id == model.id && body.model_id == invocation.spend_voucher.body.model_id,
            "provider receipt model mismatch",
        ),
        (
            body.price_ver == invocation.price_ver,
            "provider receipt price_ver mismatch",
        ),
        (
            body.locked_rate_map == invocation.spend_voucher.body.locked_rate_map,
            "provider receipt locked_rate_map mismatch",
        ),
        (
            body.locked_per_req_au == invocation.spend_voucher.body.locked_per_req_au,
            "provider receipt locked_per_req_au mismatch",
        ),
        (
            body.locked_min_session_au == invocation.spend_voucher.body.locked_min_session_au,
            "provider receipt locked_min_session_au mismatch",
        ),
        (
            body.served_ctx == invocation.served_ctx
                && body.served_ctx == invocation.spend_voucher.body.served_ctx,
            "provider receipt served_ctx mismatch",
        ),
        (
            body.ctx_bracket == invocation.ctx_bracket
                && body.ctx_bracket == invocation.spend_voucher.body.ctx_bracket,
            "provider receipt ctx_bracket mismatch",
        ),
        (
            body.ctx_bracket_table_ver == invocation.ctx_bracket_table_ver
                && body.ctx_bracket_table_ver
                    == invocation.spend_voucher.body.ctx_bracket_table_ver,
            "provider receipt ctx_bracket_table_ver mismatch",
        ),
        (
            body.rules_ver == invocation.rules_ver
                && body.rules_ver == invocation.spend_voucher.body.rules_ver,
            "provider receipt rules_ver mismatch",
        ),
        (
            body.workflow == invocation.spend_voucher.body.workflow,
            "provider receipt workflow binding mismatch",
        ),
        (
            if invocation.spend_voucher.body.workflow.is_some() {
                body.workflow_output.is_some()
            } else {
                body.workflow_output.is_none()
            },
            "provider receipt workflow output binding mismatch",
        ),
        (
            body.usage == expected.usage,
            "provider receipt usage mismatch",
        ),
        (
            body.au_owed_cum == expected.au_owed_cum,
            "provider receipt amount mismatch",
        ),
        (
            body.prompt_hash == expected.prompt_hash,
            "provider receipt prompt_hash mismatch",
        ),
    ];
    for (ok, message) in checks {
        if !ok {
            return Err(GatewaySessionError::new(message));
        }
    }
    verify_provider_receipt_signature(provider_receipt)
}

fn receipt_ack_for_body(
    user_seed: &[u8; 32],
    body: &ReceiptBody,
) -> Result<ReceiptAck, serde_json::Error> {
    let payload = receipt_signing_bytes(body)?;
    Ok(ReceiptAck {
        session_id: body.session_id.clone(),
        seq: body.seq,
        user_sig: sign_hex(user_seed, &payload),
    })
}

fn tool_calls_from_session_delta_resolving(
    frame: &Value,
    pending: &mut SessionDeltaPayloadChunks,
) -> Result<Option<Vec<ToolCallOutput>>, GatewaySessionError> {
    if let Some(tools) = frame.get("tools").filter(|tools| !tools.is_null()) {
        return tool_calls_from_session_value(tools).map(Some);
    }
    if let Some(tools) = resolve_session_delta_ref_field(frame, "tools", pending)? {
        return tool_calls_from_session_value(&tools).map(Some);
    }
    Ok(None)
}

fn tool_calls_from_session_value(
    tools: &Value,
) -> Result<Vec<ToolCallOutput>, GatewaySessionError> {
    let tools = tools.as_array().ok_or_else(|| {
        GatewaySessionError::new("provider tools delta must be a non-empty array")
    })?;
    if tools.is_empty() {
        return Err(GatewaySessionError::new(
            "provider tools delta must be a non-empty array",
        ));
    }
    let mut ids = BTreeSet::new();
    tools
        .iter()
        .map(|tool| {
            let id = tool
                .get("id")
                .and_then(Value::as_str)
                .filter(|id| !id.is_empty())
                .ok_or_else(|| GatewaySessionError::new("provider tool call is missing id"))?
                .to_owned();
            if !ids.insert(id.clone()) {
                return Err(GatewaySessionError::new(
                    "provider tools delta contains duplicate call ids",
                ));
            }
            let name = tool
                .get("name")
                .and_then(Value::as_str)
                .filter(|name| !name.is_empty())
                .ok_or_else(|| GatewaySessionError::new("provider tool call is missing name"))?
                .to_owned();
            let arguments = tool
                .get("arguments")
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    GatewaySessionError::new("provider tool call arguments must be JSON text")
                })?
                .to_owned();
            serde_json::from_str::<Value>(&arguments).map_err(|err| {
                GatewaySessionError::new(format!(
                    "provider tool call arguments are invalid JSON: {err}"
                ))
            })?;
            Ok(ToolCallOutput {
                id,
                name,
                arguments,
            })
        })
        .collect()
}

fn usage_from_session_delta(frame: &Value) -> Option<Usage> {
    let usage = frame.get("usage")?;
    let prompt_tokens = usage
        .get("in")
        .or_else(|| usage.get("input_token"))
        .or_else(|| usage.get("prompt_tokens"))
        .and_then(Value::as_u64)?;
    let completion_tokens = usage
        .get("out")
        .or_else(|| usage.get("output_token"))
        .or_else(|| usage.get("completion_tokens"))
        .and_then(Value::as_u64)?;
    Some(Usage {
        prompt_tokens,
        completion_tokens,
        total_tokens: prompt_tokens + completion_tokens,
    })
}

fn usage_attribution_from_session_delta(
    frame: &Value,
) -> Result<Option<BTreeMap<String, u64>>, GatewaySessionError> {
    let Some(value) = frame.get("usage_attribution") else {
        return Ok(None);
    };
    serde_json::from_value(value.clone())
        .map(Some)
        .map_err(|err| {
            GatewaySessionError::new(format!("invalid provider usage attribution: {err}"))
        })
}

fn validate_usage_attribution(
    usage: &ReceiptUsage,
    attribution: &BTreeMap<String, u64>,
) -> Result<(), GatewaySessionError> {
    for axis in attribution.keys() {
        if !matches!(
            axis.as_str(),
            "reasoning_output_tokens" | "vision_input_tokens" | "audio_input_tokens"
        ) {
            return Err(GatewaySessionError::new(format!(
                "unsupported provider usage attribution {axis}"
            )));
        }
    }
    if attribution
        .get("reasoning_output_tokens")
        .copied()
        .unwrap_or(0)
        > usage.output_tokens()
    {
        return Err(GatewaySessionError::new(
            "provider reasoning attribution exceeds billed output tokens",
        ));
    }
    if attribution.get("vision_input_tokens").copied().unwrap_or(0) > usage.input_tokens() {
        return Err(GatewaySessionError::new(
            "provider vision attribution exceeds billed input tokens",
        ));
    }
    if attribution.get("audio_input_tokens").copied().unwrap_or(0) > usage.input_tokens() {
        return Err(GatewaySessionError::new(
            "provider audio attribution exceeds billed input tokens",
        ));
    }
    if attribution
        .get("vision_input_tokens")
        .copied()
        .unwrap_or(0)
        .saturating_add(attribution.get("audio_input_tokens").copied().unwrap_or(0))
        > usage.input_tokens()
    {
        return Err(GatewaySessionError::new(
            "provider media attribution exceeds billed input tokens",
        ));
    }
    Ok(())
}

fn validate_reasoning_evidence_attribution(
    reasoning_evidence: &str,
    attribution: &BTreeMap<String, u64>,
) -> Result<(), GatewaySessionError> {
    let observed = metered_output_units("", reasoning_evidence, &[]);
    if attribution
        .get("reasoning_output_tokens")
        .copied()
        .unwrap_or(0)
        != observed
    {
        return Err(GatewaySessionError::new(
            "provider reasoning attribution did not match gateway-observed reasoning evidence",
        ));
    }
    Ok(())
}

fn receipt_usage_from_session_delta(frame: &Value) -> Option<ReceiptUsage> {
    serde_json::from_value(frame.get("usage")?.clone()).ok()
}

async fn run_embedding_with_route_retry(
    state: &GatewayState,
    model: &GatewayModel,
    request: &EmbeddingRequest,
    inputs: &[String],
    options: GatewayRequestOptions,
) -> Result<GatewayEmbeddingRun, ApiError> {
    let deadline = RouteWaitDeadline::new(options.max_wait_ms);
    let requirements = request_requirements_for_embedding(
        state,
        model,
        inputs,
        now_millis_u64(),
        options.max_price_au,
        state.throughput_floor_for_model(
            model,
            &options,
            DEFAULT_EMBEDDING_INPUT_TOKENS_FLOOR_PER_S,
        ),
    );
    let eligible_routes =
        ordered_route_candidates_for_embedding_with_options(state, model, inputs, &options);
    let RouteWaitOutcome {
        routes: eligible_routes,
        waited,
    } = wait_for_eligible_routes(
        state,
        model,
        &options,
        &requirements,
        deadline,
        eligible_routes,
        || ordered_route_candidates_for_embedding_with_options(state, model, inputs, &options),
    )
    .await;
    if eligible_routes.is_empty() {
        if let Some(error) = preferred_provider_refusal_error(state, model, &options) {
            return Err(error);
        }
    }
    if !model.mayhem.route_candidates.is_empty() && eligible_routes.is_empty() {
        if waited {
            return Err(route_wait_expired_error(&options));
        }
        return Err(no_eligible_route_error(
            state,
            model,
            &options,
            &requirements.required_modalities,
        ));
    }
    if eligible_routes.is_empty() && !state.dev_session_shim {
        return Err(ApiError::service_unavailable(
            "no provider available: production gateway requires an active provider joined to an admin-created room",
            Some("model"),
        ));
    }

    let mut recovery = RouteAdmissionRecovery::new(
        deadline,
        route_retry_total_attempt_limit(state, model, &options),
    );
    let mut pending_routes = eligible_routes;
    let mut attempt_options = options.clone();
    let mut billing = options.billing.clone().unwrap_or_else(|| {
        GatewayBillingContext::initial(logical_billing_id_for(
            &model.id,
            &embedding_prompt_text(inputs),
        ))
    });
    attempt_options.billing = Some(billing.clone());
    let mut last_retryable_error = None;
    loop {
        if !recovery.can_attempt()
            || (recovery.has_capacity_waiters() && recovery.deadline.remaining().is_zero())
        {
            break;
        }
        pending_routes = recovery.filter_routes(state, pending_routes);
        if pending_routes.is_empty() && recovery.has_capacity_waiters() {
            pending_routes = wait_for_capacity_recovery(
                state,
                &recovery,
                || {
                    ordered_route_candidates_for_embedding_with_options(
                        state,
                        model,
                        inputs,
                        &attempt_options,
                    )
                },
                Duration::from_millis(ROUTE_WAIT_POLL_MS),
            )
            .await;
        }
        let route = pending_routes.first().copied();
        if route.is_none()
            && ((!model.mayhem.route_candidates.is_empty() || !state.dev_session_shim)
                || recovery.dev_route_attempted)
        {
            break;
        }
        recovery.begin_attempt(route);
        let _modality_admission = match state.try_acquire_modality_admission(route, &requirements) {
            Ok(admission) => admission,
            Err(err) => {
                recovery.exhaust(route);
                last_retryable_error = Some(err);
                pending_routes = ordered_route_candidates_for_embedding_with_options(
                    state,
                    model,
                    inputs,
                    &attempt_options,
                );
                continue;
            }
        };
        let invocation =
            state.prepare_embedding_invocation_for_route(model, inputs, route, &attempt_options)?;
        let attempt_started = Instant::now();
        match state
            .session_backend
            .run_embedding(model, request, &invocation)
            .await
        {
            Ok(result) => {
                record_route_observation(
                    state,
                    route,
                    observation_sample_from_embedding_success(&result, attempt_started.elapsed()),
                );
                let metering_output = result.output.clone();
                return Ok(GatewayEmbeddingRun {
                    result,
                    invocation,
                    metering_inputs: inputs.to_vec(),
                    metering_output,
                });
            }
            Err(err) if is_client_disconnect_error(&err) => {
                return Err(ApiError::client_closed_request(err.message));
            }
            Err(err) if err.failure_class.is_request_scoped() => {
                return Err(request_scoped_api_error(&err).expect("request-scoped error"));
            }
            Err(err) if err.retryable => {
                record_route_attempt_error(state, route, attempt_started.elapsed(), &err);
                if let Some(refusal) = terminal_balance_refusal(&err) {
                    return Err(refusal);
                }
                billing = billing.after_attempt(None);
                attempt_options.billing = Some(billing.clone());
                let is_capacity = capacity_refusal(&err);
                last_retryable_error = Some(err.message);
                if is_capacity {
                    recovery.record_capacity_refusal(state, route);
                } else {
                    recovery.exhaust(route);
                }
                pending_routes = ordered_route_candidates_for_embedding_with_options(
                    state,
                    model,
                    inputs,
                    &attempt_options,
                );
            }
            Err(err) => {
                record_route_attempt_error(state, route, attempt_started.elapsed(), &err);
                return Err(ApiError::bad_gateway(err.message, Some("model")));
            }
        }
    }

    if recovery.has_capacity_waiters() && recovery.deadline.remaining().is_zero() {
        return Err(route_wait_expired_error(&options));
    }
    Err(ApiError::bad_gateway(
        format!(
            "all {} route attempt(s) failed before spend; last error: {}",
            recovery.attempts_made,
            last_retryable_error.unwrap_or_else(|| "no route attempted".to_owned())
        ),
        Some("model"),
    ))
}

