async fn run_hedge_probes_if_requested(
    state: &GatewayState,
    model: &GatewayModel,
    request: &ChatCompletionRequest,
    routes: &[&GatewayRouteCandidate],
    options: &GatewayRequestOptions,
) -> Result<GatewayHedgeProbeOutcome, ApiError> {
    if !options.hedge_requested
        || routes.len() < 2
        || state.preferred_provider_order(model, options).is_some()
    {
        return Ok(GatewayHedgeProbeOutcome::default());
    }
    let requirements = request_requirements_for_chat(
        state,
        model,
        request,
        now_millis_u64(),
        options.max_price_au,
        options.min_ctx,
        state.generation_floor_tok_s_for_model(model, options),
    );
    let Ok(_first_admission) = state.try_acquire_modality_admission(Some(routes[0]), &requirements)
    else {
        return Ok(GatewayHedgeProbeOutcome::default());
    };
    let Ok(_second_admission) =
        state.try_acquire_modality_admission(Some(routes[1]), &requirements)
    else {
        return Ok(GatewayHedgeProbeOutcome::default());
    };
    let first_invocation =
        state.prepare_chat_hedge_probe_invocation(model, request, routes[0], options);
    let second_invocation =
        state.prepare_chat_hedge_probe_invocation(model, request, routes[1], options);
    let (first, second) = tokio::join!(
        state
            .session_backend
            .hedge_probe(model, request, &first_invocation),
        state
            .session_backend
            .hedge_probe(model, request, &second_invocation)
    );
    let mut successes = [first.ok(), second.ok()]
        .into_iter()
        .flatten()
        .collect::<Vec<_>>();
    successes.sort_by(|left, right| left.ttft_ms.cmp(&right.ttft_ms));
    Ok(GatewayHedgeProbeOutcome {
        actual_probe_count: 2,
        winner: successes.into_iter().next(),
    })
}

