fn request_requirements_for_artifact_generation(
    state: &GatewayState,
    model: &GatewayModel,
    request: &ArtifactGenerationRequest,
    now_millis: u64,
    max_price_au: Option<MoneyAu>,
    min_throughput: Option<f64>,
) -> RequestRequirements {
    let input_tokens = rough_tokens(&request.prompt);
    let output_item_units = if let Some(workflow_output) = request.workflow_output.as_ref() {
        workflow_output
            .metrics
            .get("frame")
            .or_else(|| workflow_output.metrics.get("duration_second"))
            .copied()
            .unwrap_or(1)
            .max(1)
    } else if request.output_modality == "video" {
        request.frame_count.max(1)
    } else {
        request.duration_seconds.max(1)
    };
    let output_item_count = u32::try_from(request.artifact_count).unwrap_or(u32::MAX);
    let required_modalities = artifact_generation_required_modalities(model, request);
    let mut modality_load = BTreeMap::new();
    for modality in &required_modalities {
        let load = if let Some(workflow_output) = request.workflow_output.as_ref() {
            let artifact_count = workflow_output
                .metrics
                .get("artifact_count")
                .copied()
                .unwrap_or(u64::from(output_item_count))
                .max(1);
            let item_count = u32::try_from(artifact_count).unwrap_or(u32::MAX);
            match modality.as_str() {
                "video" => ModalityRequestLoad {
                    item_count,
                    max_item_bytes: 1,
                    max_item_units: workflow_output
                        .metrics
                        .get("frame")
                        .copied()
                        .unwrap_or(output_item_units)
                        .max(1),
                },
                "audio" => ModalityRequestLoad {
                    item_count,
                    max_item_bytes: 1,
                    max_item_units: workflow_output
                        .metrics
                        .get("duration_second")
                        .copied()
                        .unwrap_or(output_item_units)
                        .max(1),
                },
                "image" => ModalityRequestLoad {
                    item_count,
                    max_item_bytes: 1,
                    max_item_units: workflow_output
                        .metrics
                        .get("width")
                        .copied()
                        .unwrap_or(1)
                        .max(1)
                        .saturating_mul(
                            workflow_output
                                .metrics
                                .get("height")
                                .copied()
                                .unwrap_or(1)
                                .max(1),
                        ),
                },
                _ => ModalityRequestLoad {
                    item_count,
                    max_item_bytes: 1,
                    max_item_units: output_item_units,
                },
            }
        } else {
            match modality.as_str() {
                "video" => ModalityRequestLoad {
                    item_count: output_item_count,
                    max_item_bytes: 1,
                    max_item_units: request.frame_count.max(1),
                },
                "audio" if request.output_modality == "audio" => ModalityRequestLoad {
                    item_count: output_item_count.max(request.input_audio_count),
                    max_item_bytes: request.input_audio_max_bytes.max(1),
                    max_item_units: output_item_units
                        .max(request.input_audio_max_seconds)
                        .max(1),
                },
                "audio" => ModalityRequestLoad {
                    item_count: output_item_count,
                    max_item_bytes: 1,
                    max_item_units: request.duration_seconds.max(1),
                },
                "image" => ModalityRequestLoad {
                    item_count: request.input_image_count,
                    max_item_bytes: request.input_image_max_bytes,
                    max_item_units: request.input_image_max_pixels,
                },
                _ => ModalityRequestLoad {
                    item_count: output_item_count,
                    max_item_bytes: 1,
                    max_item_units: output_item_units,
                },
            }
        };
        modality_load.insert(modality.clone(), load);
    }
    RequestRequirements {
        current_rules_ver: state.receipt_config.rules_ver,
        requires_transport_peer: !state.dev_session_shim,
        requires_tools: false,
        requires_json: false,
        requires_vision: false,
        required_modalities,
        required_specialities: request.effective_specialities.clone(),
        workflow: request
            .workflow
            .as_ref()
            .map(|workflow| WorkflowRouteRequirements {
                runtime_id: workflow.runtime_id.clone(),
                outcome_class: workflow.outcome_class.clone(),
                inventory_root: model
                    .mayhem
                    .workflow
                    .as_ref()
                    .and_then(|policy| policy.inventory_root.clone()),
            }),
        modality_load,
        // Artifact endpoints bound prompt size through their calibrated endpoint
        // contract. Provider `ctx` is a text-generation capacity and is only a
        // sentinel for image, audio, music, and video routes.
        min_ctx: 1,
        input_tokens,
        output_tokens: 0,
        usage: artifact_generation_usage_for_request(request),
        min_throughput,
        now_millis,
        max_price_au,
        heartbeat_ttl_millis: state.provider_heartbeat_ttl_millis,
        ..RequestRequirements::default()
    }
}

fn artifact_generation_required_modalities(
    model: &GatewayModel,
    request: &ArtifactGenerationRequest,
) -> Vec<String> {
    if let Some(workflow_output) = request.workflow_output.as_ref() {
        return workflow_output.output_modalities.clone();
    }
    if request.output_modality == "video" {
        mayhem_proto::video_generation_required_modalities(
            &model.mayhem.caps.output_modalities,
            request.input_image_count > 0,
        )
    } else {
        vec![request.output_modality.clone()]
    }
}

fn route_selection_seed(
    model: &GatewayModel,
    request: &ChatCompletionRequest,
    now_millis: u64,
) -> u64 {
    let mut hasher = blake3::Hasher::new();
    hasher.update(model.id.as_bytes());
    hasher.update(chat_prompt_text(request).as_bytes());
    hasher.update(&request.seed.unwrap_or_default().to_le_bytes());
    hasher.update(&now_millis.to_le_bytes());
    let digest = hasher.finalize();
    let mut bytes = [0_u8; 8];
    bytes.copy_from_slice(&digest.as_bytes()[..8]);
    u64::from_le_bytes(bytes)
}

