    #[test]
    fn canary_cadence_audit_stays_inside_new_provider_holdback_window() {
        let default_policy = GatewayCanaryProbePolicy::default();
        assert_eq!(
            default_policy.audit_against_new_provider_holdback(168),
            GatewayCanaryHoldbackCadenceAudit {
                enabled: true,
                max_interval_sessions: 89,
                new_provider_holdback_epochs: 168,
                compliant: true,
            }
        );

        let mut loose_policy = default_policy;
        loose_policy.max_interval_sessions = 169;
        assert!(
            !loose_policy
                .audit_against_new_provider_holdback(168)
                .compliant
        );

        let mut disabled_policy = default_policy;
        disabled_policy.enabled = false;
        assert!(
            !disabled_policy
                .audit_against_new_provider_holdback(168)
                .compliant
        );
    }

    #[test]
    fn direct_session_watchdog_resets_idle_gap_per_delta() {
        let mut watchdog = DirectSessionWatchdog::new(
            0,
            Some(Duration::from_millis(15)),
            Some(Duration::from_millis(15)),
            None,
            None,
        );
        assert_eq!(watchdog.next_wait_millis(15), Ok(Some(1)));
        watchdog.record_delta(10);
        assert_eq!(watchdog.next_wait_millis(25), Ok(Some(1)));
        watchdog.record_delta(25);
        assert_eq!(watchdog.next_wait_millis(40), Ok(Some(1)));
        watchdog.record_delta(40);
        assert_eq!(watchdog.next_wait_millis(55), Ok(Some(1)));
        assert_eq!(
            watchdog.next_wait_millis(56),
            Err(DirectSessionTimeoutKind::IdleGap)
        );
    }

