    #[test]
    fn receipt_wallet_balance_and_rail_are_configurable() {
        let model = test_model();
        let request = test_chat_request(&model.id);
        let user_seed = [12_u8; 32];
        let state = GatewayState::from_models(vec![model.clone()])
            .with_receipt_user_seed(user_seed)
            .with_receipt_balance_au(2_000_000)
            .with_receipt_rail("tnk");
        let invocation = state
            .prepare_chat_invocation_for_route(
                &model,
                &request,
                None,
                &GatewayRequestOptions::default(),
            )
            .expect("configured wallet has enough balance");

        assert_eq!(invocation.rail, "tnk");
        assert_eq!(invocation.user_pubkey, verifying_key_hex(&user_seed));
        assert_eq!(invocation.receipt_user_seed, user_seed);

        let checkpointed = GatewayState::from_models(vec![model.clone()])
            .with_receipt_user_seed(user_seed)
            .with_receipt_balance_au(2_000_000)
            .with_receipt_checkpoint_every(CheckpointPolicy {
                tokens: 32,
                ms: 2500,
            })
            .prepare_chat_invocation_for_route(
                &model,
                &request,
                None,
                &GatewayRequestOptions::default(),
            )
            .expect("configured checkpoint policy should be accepted");
        assert_eq!(checkpointed.spend_voucher.body.checkpoint_every.tokens, 32);
        assert_eq!(checkpointed.spend_voucher.body.checkpoint_every.ms, 2500);

        let mut stream_request = request.clone();
        stream_request.stream = true;
        let stream_checkpointed = GatewayState::from_models(vec![model.clone()])
            .with_receipt_user_seed(user_seed)
            .with_receipt_balance_au(2_000_000)
            .with_receipt_checkpoint_every(CheckpointPolicy {
                tokens: 32,
                ms: 2500,
            })
            .prepare_chat_invocation_for_route(
                &model,
                &stream_request,
                None,
                &GatewayRequestOptions::default(),
            )
            .expect("stream checkpoint policy should be accepted");
        assert_eq!(
            stream_checkpointed
                .spend_voucher
                .body
                .checkpoint_every
                .tokens,
            LIVE_SSE_RECEIPT_CHECKPOINT_TOKENS
        );
        assert_eq!(
            stream_checkpointed.spend_voucher.body.checkpoint_every.ms,
            2500
        );

        let low_balance = GatewayState::from_models(vec![model.clone()])
            .with_receipt_user_seed(user_seed)
            .with_receipt_balance_au(1);
        let err = low_balance
            .prepare_chat_invocation_for_route(
                &model,
                &request,
                None,
                &GatewayRequestOptions::default(),
            )
            .expect_err("gateway rejects spend vouchers above the startup balance snapshot");
        assert!(err.message.contains("insufficient local balance"));

        let max_bid = GatewayRequestOptions {
            max_price_au: Some(84),
            ..GatewayRequestOptions::default()
        };
        let err = state
            .prepare_chat_invocation_for_route(&model, &request, None, &max_bid)
            .expect_err("gateway rejects quotes above the user max-bid");
        assert_eq!(err.param, Some("X-Mayhem-Max-Price-Au"));
    }

    #[test]
    fn chat_spend_voucher_bounds_media_expansion_by_served_context() {
        let mut model = test_model();
        model.mayhem.caps.vision = true;
        let mut request = test_chat_request(&model.id);
        request.messages[0].content = json!([
            {"type": "text", "text": "Describe this image."},
            {"type": "image_url", "image_url": {"url": test_png_data_url()}},
        ]);
        request.max_completion_tokens = Some(2_048);

        let invocation = GatewayState::from_models(vec![model.clone()])
            .prepare_chat_invocation_for_route(
                &model,
                &request,
                None,
                &GatewayRequestOptions::default(),
            )
            .expect("multimodal request receives a context-bounded voucher");
        let full_context_bound = calculate_au_owed(
            &model.mayhem.price_ref_au,
            &ReceiptUsage::text(
                u64::from(model.mayhem.caps.ctx),
                2_048 * MAX_VISIBLE_OUTPUT_UNITS_PER_REQUEST_TOKEN,
            ),
        )
        .max(1_000);
        let provider_media_receipt =
            calculate_au_owed(&model.mayhem.price_ref_au, &ReceiptUsage::text(289, 2_048));

        assert_eq!(
            invocation.spend_voucher.body.max_spend_au,
            full_context_bound
        );
        assert!(invocation.spend_voucher.body.max_spend_au >= provider_media_receipt);
    }

    #[test]
    fn spend_voucher_uses_admin_ctx_bracket_schedule() {
        let mut model = test_model();
        model.mayhem.caps.ctx = 12_000;
        let request = test_chat_request(&model.id);
        let schedule = CtxBracketSchedule {
            current: mayhem_proto::CtxBracketTableRecord {
                ver: 2,
                submitted_at: 1,
                effective_at: 1,
                brackets: vec![
                    mayhem_proto::CtxBracketEntry {
                        id: "le16k".to_owned(),
                        max_ctx: Some(16_384),
                    },
                    mayhem_proto::CtxBracketEntry {
                        id: "gt16k".to_owned(),
                        max_ctx: None,
                    },
                ],
            },
            pending: None,
        };
        let invocation = GatewayState::from_models(vec![model.clone()])
            .with_ctx_bracket_schedule(schedule)
            .prepare_chat_invocation_for_route(
                &model,
                &request,
                None,
                &GatewayRequestOptions::default(),
            )
            .expect("invocation uses custom context table");

        assert_eq!(invocation.served_ctx, 12_000);
        assert_eq!(invocation.ctx_bracket.as_deref(), Some("le16k"));
        assert_eq!(invocation.ctx_bracket_table_ver, Some(2));
        assert!(invocation.opened_at > 0);
        assert_eq!(
            invocation.spend_voucher.body.ctx_bracket.as_deref(),
            Some("le16k")
        );
        assert_eq!(invocation.spend_voucher.body.ctx_bracket_table_ver, Some(2));
    }

