    fn test_gateway_state_from_models(models: Vec<GatewayModel>) -> GatewayState {
        let now = now_millis_u64();
        let heartbeats = models
            .iter()
            .flat_map(|model| {
                model.mayhem.route_candidates.iter().map(|route| {
                    let mut heartbeat = heartbeat_for_route(model, route, now);
                    heartbeat.caps.modality_capacity = route
                        .served_modalities
                        .iter()
                        .filter(|modality| modality.as_str() != "text")
                        .map(|modality| {
                            (
                                modality.clone(),
                                HeartbeatModalityCapacity {
                                    unit: match modality.as_str() {
                                        "image" => "pixel",
                                        "audio" => "second",
                                        "video" => "frame",
                                        "embedding" => "input_token",
                                        _ => "unit",
                                    }
                                    .to_owned(),
                                    max_inflight_items: 16,
                                    active_items: 0,
                                    max_items_per_request: 4,
                                    max_item_bytes: 256 * 1024 * 1024,
                                    max_item_units: 100_000_000,
                                    working_set_bytes_per_item: 1024,
                                },
                            )
                        })
                        .collect();
                    if let Some(workflow) = model.mayhem.workflow.as_ref() {
                        let runtime_id = workflow.runtime_id.clone().unwrap_or_else(|| {
                            mayhem_proto::DEFAULT_COMFY_WORKFLOW_RUNTIME_ID.to_owned()
                        });
                        let outcome_class = workflow.outcome_class_for(
                            model
                                .mayhem
                                .caps
                                .output_modality
                                .as_deref()
                                .unwrap_or("image"),
                        );
                        heartbeat.runtime_id = Some(runtime_id);
                        heartbeat.inventory_root = workflow.inventory_root.clone();
                        heartbeat.workflow_classes.insert(
                            outcome_class,
                            crate::HeartbeatWorkflowClass {
                                min_ask_au: route.min_ask_au,
                                max_concurrent: 2,
                                active: 0,
                            },
                        );
                    }
                    heartbeat.sig = "aa".repeat(64);
                    heartbeat
                })
            })
            .collect::<Vec<_>>();
        GatewayState::from_models(models).with_provider_heartbeats(heartbeats)
    }

