    #[test]
    fn route_selection_uses_weighted_p2c_not_array_order() {
        let model = test_routed_model(4);
        let state = test_gateway_state_from_models(vec![model.clone()]);
        let request = test_chat_request(&model.id);
        let mut counts = BTreeMap::new();

        for seed in 0..256 {
            let selected = ordered_route_candidates_for_request_with_seed(
                &state, &model, &request, None, seed,
            )
            .into_iter()
            .next()
            .expect("route selected")
            .provider
            .clone();
            *counts.entry(selected).or_insert(0_u32) += 1;
        }

        assert!(
            counts.len() > 1,
            "P2C should distribute first picks instead of always using catalog array order"
        );
        assert!(
            counts[&model.mayhem.route_candidates[0].provider] < 256,
            "catalog array first provider must not win every live selection"
        );
    }

    #[test]
    fn preferred_provider_header_is_bounded_ordered_and_unique() {
        let first = "11".repeat(32);
        let second = "22".repeat(32);
        let mut headers = HeaderMap::new();
        headers.insert(
            X_MAYHEM_PREFER_PROVIDERS_HEADER,
            HeaderValue::from_str(&format!("{first}, {second}")).unwrap(),
        );
        let options = GatewayRequestOptions::from_headers(&headers).unwrap();
        assert_eq!(
            options.preferred_providers,
            Some(vec![first.clone(), second.clone()])
        );

        headers.insert(
            X_MAYHEM_PREFER_PROVIDERS_HEADER,
            HeaderValue::from_str(&format!("{first},{first}")).unwrap(),
        );
        let duplicate = GatewayRequestOptions::from_headers(&headers).unwrap_err();
        assert_eq!(duplicate.param, Some("X-Mayhem-Prefer-Providers"));

        headers.insert(
            X_MAYHEM_PREFER_PROVIDERS_HEADER,
            HeaderValue::from_static(""),
        );
        assert!(GatewayRequestOptions::from_headers(&headers).is_err());
    }

    #[test]
    fn preferred_provider_routing_restricts_orders_sweeps_and_restores_discovery() {
        let model = test_routed_model(3);
        let state = test_gateway_state_from_models(vec![model.clone()]);
        let request = test_chat_request(&model.id);
        let first = model.mayhem.route_candidates[2].provider.clone();
        let second = model.mayhem.route_candidates[0].provider.clone();
        let excluded = model.mayhem.route_candidates[1].provider.clone();
        state
            .replace_preferred_providers(BTreeMap::from([(
                model.id.clone(),
                vec![first.clone(), second.clone()],
            )]))
            .unwrap();

        let options = GatewayRequestOptions {
            max_wait_ms: 0,
            ..GatewayRequestOptions::default()
        };
        let ordered =
            ordered_route_candidates_for_request_with_options(&state, &model, &request, &options);
        assert_eq!(
            ordered
                .iter()
                .map(|route| route.provider.clone())
                .collect::<Vec<_>>(),
            vec![first.clone(), second.clone()]
        );
        assert!(!ordered.iter().any(|route| route.provider == excluded));

        state.cool_route_provider(&model.mayhem.route_candidates[2], now_millis_u64());
        let swept =
            ordered_route_candidates_for_request_with_options(&state, &model, &request, &options);
        assert_eq!(swept.len(), 1);
        assert_eq!(swept[0].provider, second);

        state.cool_route_provider(&model.mayhem.route_candidates[0], now_millis_u64());
        let exhausted =
            ordered_route_candidates_for_request_with_options(&state, &model, &request, &options);
        assert!(exhausted.is_empty());
        let refusal = preferred_provider_refusal_error(&state, &model, &options).unwrap();
        assert_eq!(refusal.status, StatusCode::SERVICE_UNAVAILABLE);
        assert!(refusal
            .message
            .contains("none of your 2 preferred providers"));
        assert!(refusal.message.contains(&model.id));

        state.replace_preferred_providers(BTreeMap::new()).unwrap();
        state
            .provider_cooloffs
            .lock_recover("provider cooloff map")
            .clear();
        let discovery =
            ordered_route_candidates_for_request_with_options(&state, &model, &request, &options);
        assert_eq!(discovery.len(), 3);
    }

    #[test]
    fn request_header_overrides_persistent_preference_and_hard_gates_still_apply() {
        let mut model = test_routed_model(3);
        model.mayhem.route_candidates[0].served_ctx = Some(4_096);
        model.mayhem.route_candidates[1].served_ctx = Some(16_384);
        model.mayhem.route_candidates[2].served_ctx = Some(16_384);
        model.mayhem.route_candidates[2].min_ask_au = MoneyAu::MAX;
        let state = test_gateway_state_from_models(vec![model.clone()]);
        let request = test_chat_request(&model.id);
        state
            .replace_preferred_providers(BTreeMap::from([(
                model.id.clone(),
                vec![model.mayhem.route_candidates[0].provider.clone()],
            )]))
            .unwrap();

        let header_order = [
            model.mayhem.route_candidates[2].provider.clone(),
            model.mayhem.route_candidates[0].provider.clone(),
            model.mayhem.route_candidates[1].provider.clone(),
        ];
        let mut headers = HeaderMap::new();
        headers.insert(
            X_MAYHEM_PREFER_PROVIDERS_HEADER,
            HeaderValue::from_str(&header_order.join(",")).unwrap(),
        );
        headers.insert(X_MAYHEM_MIN_CTX_HEADER, HeaderValue::from_static("8192"));
        headers.insert(
            X_MAYHEM_MAX_PRICE_AU_HEADER,
            HeaderValue::from_str(&(MoneyAu::MAX - 1).to_string()).unwrap(),
        );
        let options = GatewayRequestOptions::from_headers(&headers).unwrap();
        let selected =
            ordered_route_candidates_for_request_with_options(&state, &model, &request, &options);

        assert_eq!(selected.len(), 1);
        assert_eq!(
            selected[0].provider,
            model.mayhem.route_candidates[1].provider
        );
        assert_eq!(
            route_retry_total_attempt_limit(&state, &model, &options),
            usize::from(DEFAULT_MAX_OPEN_ATTEMPTS)
        );
    }

    #[test]
    fn route_selection_uses_anchored_reputation_weight() {
        let neutral_model = test_routed_model(2);
        let neutral_state = test_gateway_state_from_models(vec![neutral_model.clone()]);
        let request = test_chat_request(&neutral_model.id);
        let penalized_provider = neutral_model.mayhem.route_candidates[0].provider.clone();
        let neutral_wins = (0..512)
            .filter(|seed| {
                ordered_route_candidates_for_request_with_seed(
                    &neutral_state,
                    &neutral_model,
                    &request,
                    None,
                    *seed,
                )
                .into_iter()
                .next()
                .map(|candidate| candidate.provider == penalized_provider)
                .unwrap_or(false)
            })
            .count();

        let mut anchored_model = neutral_model.clone();
        anchored_model.mayhem.route_candidates[0].reputation_bps = 3_100;
        let anchored_state = test_gateway_state_from_models(vec![anchored_model.clone()]);
        let anchored_wins = (0..512)
            .filter(|seed| {
                ordered_route_candidates_for_request_with_seed(
                    &anchored_state,
                    &anchored_model,
                    &request,
                    None,
                    *seed,
                )
                .into_iter()
                .next()
                .map(|candidate| candidate.provider == penalized_provider)
                .unwrap_or(false)
            })
            .count();

        assert!(
            neutral_wins > 150,
            "neutral reputation should select the provider at a visible baseline"
        );
        assert_eq!(
            anchored_wins, 0,
            "anchored low reputation should not outrank a materially healthier route"
        );

        let snapshot = contract_snapshot_for_route(
            &anchored_model,
            &anchored_model.mayhem.route_candidates[0],
            3,
            None,
            &BTreeMap::new(),
            &BTreeMap::new(),
            None,
        );
        assert!((snapshot.reputation - 0.31).abs() < f64::EPSILON);
    }

    #[test]
    fn route_selection_penalizes_observed_slow_error_provider() {
        let model = test_routed_model(4);
        let state = test_gateway_state_from_models(vec![model.clone()]);
        let request = test_chat_request(&model.id);
        let penalized_provider = model.mayhem.route_candidates[0].provider.clone();
        let before = (0..256)
            .filter(|seed| {
                ordered_route_candidates_for_request_with_seed(
                    &state, &model, &request, None, *seed,
                )
                .into_iter()
                .next()
                .map(|candidate| candidate.provider == penalized_provider)
                .unwrap_or(false)
            })
            .count();

        let penalized_key = route_key(&model.mayhem.route_candidates[0]);
        {
            let mut table = state.provider_table.lock_recover("provider table");
            for _ in 0..5 {
                table.record_observation(
                    &penalized_key,
                    ProviderObservationSample {
                        ttft_ms: 5_000,
                        tok_s: None,
                        error: true,
                    },
                );
            }
        }

        let after = (0..256)
            .filter(|seed| {
                ordered_route_candidates_for_request_with_seed(
                    &state, &model, &request, None, *seed,
                )
                .into_iter()
                .next()
                .map(|candidate| candidate.provider == penalized_provider)
                .unwrap_or(false)
            })
            .count();

        assert!(before > 0, "baseline should pick the provider sometimes");
        assert!(
            after < before,
            "slow/error observations should lower future P2C selection weight"
        );
        assert_eq!(after, 0);
    }

    #[test]
    fn route_selection_prefers_previous_provider_for_same_conversation_model() {
        let model = test_routed_model(4);
        let state = test_gateway_state_from_models(vec![model.clone()]);
        let mut request = test_chat_request(&model.id);
        request
            .metadata
            .insert("conversation_id".to_owned(), json!("agent-loop-1"));
        let seed = 0x5eed;
        let baseline =
            ordered_route_candidates_for_request_with_seed(&state, &model, &request, None, seed);
        let baseline_first = baseline
            .first()
            .expect("baseline route selected")
            .provider
            .clone();
        let sticky_route = model
            .mayhem
            .route_candidates
            .iter()
            .find(|candidate| candidate.provider != baseline_first)
            .expect("alternate route");

        state.record_chat_affinity(&model, &request, sticky_route);
        let selected =
            ordered_route_candidates_for_request_with_seed(&state, &model, &request, None, seed);

        assert_eq!(selected[0].provider, sticky_route.provider);
        assert_eq!(selected.len(), model.mayhem.route_candidates.len());
    }

