    #[tokio::test]
    async fn route_retry_abandons_below_floor_provider_and_reroutes() {
        let model = test_routed_model(2);
        let providers = Arc::new(Mutex::new(Vec::new()));
        let state = test_gateway_state_from_models(vec![model.clone()]).with_session_backend(
            Arc::new(SlowQualityThenSuccessBackend {
                providers: providers.clone(),
            }),
        );
        let request = test_chat_request(&model.id);
        let options = GatewayRequestOptions {
            failover_overrides: GatewayFailoverPolicyConfig {
                min_tok_s: Some(10.0),
                ..GatewayFailoverPolicyConfig::default()
            },
            ..GatewayRequestOptions::default()
        };

        let run = run_chat_with_route_retry(&state, &model, &request, options)
            .await
            .expect("slow provider should be rerouted");

        assert_eq!(run.result.output.content.as_deref(), Some("fast"));
        let providers = providers.lock().expect("providers lock").clone();
        assert_eq!(providers.len(), 2);
        assert_ne!(providers[0], providers[1]);
        let post_failure_order =
            ordered_route_candidates_for_request_with_seed(&state, &model, &request, None, 0xfeed);
        assert!(!post_failure_order
            .iter()
            .any(|candidate| candidate.provider == providers[0]));
    }

    #[test]
    fn buyer_local_direct_session_limits_are_modality_neutral_and_unpenalized() {
        let receive_rate = direct_session_transport_closed_error(
            &["s.delta"],
            "session-buyer",
            "Session session-buyer exceeded its receive rate.",
        );
        let ingress_limit = GatewaySessionError::from(BridgeError::ResourceLimit(
            "async event queue exceeds the buyer ingress limit".to_owned(),
        ));
        let provider_fault = direct_session_transport_closed_error(
            &["s.delta"],
            "session-provider",
            "remote provider closed",
        );

        assert_eq!(
            receive_rate.failure_class,
            GatewaySessionFailureClass::BuyerLocal
        );
        assert!(receive_rate.retryable);
        assert_eq!(
            ingress_limit.failure_class,
            GatewaySessionFailureClass::BuyerLocal
        );
        assert_eq!(
            provider_fault.failure_class,
            GatewaySessionFailureClass::ProviderFault
        );

        for modality in ["text", "image", "audio", "video", "embedding"] {
            let mut model = test_routed_model(1);
            model.mayhem.route_candidates[0].served_modalities = vec![modality.to_owned()];
            let state = test_gateway_state_from_models(vec![model.clone()]);
            let route = &model.mayhem.route_candidates[0];

            for error in [&receive_rate, &ingress_limit] {
                record_route_attempt_error(&state, Some(route), Duration::from_millis(5), error);
            }

            assert!(
                !state.route_provider_in_cooloff(route, now_millis_u64()),
                "{modality} route was cooled for a buyer-local limit"
            );
            let entry = state
                .provider_table
                .lock_recover("provider table")
                .entries(now_millis_u64())
                .into_iter()
                .find(|entry| entry.key == route_key(route))
                .expect("route remains in provider table");
            assert_eq!(entry.observed.samples, 0, "{modality}");
            assert_eq!(entry.observed.consecutive_failures, 0, "{modality}");
            assert_eq!(entry.observed.ewma_error_rate, 0.0, "{modality}");
            assert!(state.reputation_events().is_empty(), "{modality}");

            record_route_attempt_error(
                &state,
                Some(route),
                Duration::from_millis(5),
                &provider_fault,
            );
            assert!(
                state.route_provider_in_cooloff(route, now_millis_u64()),
                "{modality} route was not cooled for a remote transport failure"
            );
            let entry = state
                .provider_table
                .lock_recover("provider table")
                .entries(now_millis_u64())
                .into_iter()
                .find(|entry| entry.key == route_key(route))
                .expect("route remains in provider table");
            assert_eq!(entry.observed.samples, 1, "{modality}");
            assert_eq!(entry.observed.consecutive_failures, 1, "{modality}");
        }
    }

    #[test]
    fn provider_request_error_code_matrix_covers_every_endpoint_alias() {
        let collectors = [
            (
                "chat",
                mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS,
                false,
            ),
            (
                "chat-stream",
                mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS,
                false,
            ),
            (
                "completions",
                mayhem_proto::ENDPOINT_OPENAI_COMPLETIONS,
                false,
            ),
            ("responses", mayhem_proto::ENDPOINT_OPENAI_RESPONSES, false),
            ("hf-chat", mayhem_proto::ENDPOINT_HF_MULTIMODAL_CHAT, false),
            ("embeddings", mayhem_proto::ENDPOINT_OPENAI_EMBEDDINGS, true),
            (
                "hf-embeddings",
                mayhem_proto::ENDPOINT_HF_FEATURE_EXTRACTION,
                true,
            ),
            (
                "image",
                mayhem_proto::ENDPOINT_OPENAI_IMAGE_GENERATIONS,
                true,
            ),
            ("hf-image", mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE, true),
            ("speech", mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH, true),
            ("hf-speech", mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH, true),
            (
                "transcription",
                mayhem_proto::ENDPOINT_OPENAI_AUDIO_TRANSCRIPTIONS,
                true,
            ),
            (
                "hf-transcription",
                mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION,
                true,
            ),
            ("video", mayhem_proto::ENDPOINT_OPENAI_VIDEOS, true),
            ("hf-video", mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO, true),
            (
                "audio-artifact",
                mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS,
                true,
            ),
            (
                "music-artifact",
                mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS,
                true,
            ),
            (
                "hf-audio-artifact",
                mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO,
                true,
            ),
        ];

        for (collector, endpoint_family, collector_retryable) in collectors {
            let model = test_routed_model(1);
            let state = test_gateway_state_from_models(vec![model.clone()]);
            let route = &model.mayhem.route_candidates[0];

            for (code, expected_class) in [
                ("request_invalid", GatewaySessionFailureClass::BuyerLocal),
                (
                    "request_chunk_failed",
                    GatewaySessionFailureClass::BuyerLocal,
                ),
                (
                    "request_reassembly_failed",
                    GatewaySessionFailureClass::BuyerLocal,
                ),
                (
                    "model_output_invalid",
                    GatewaySessionFailureClass::RequestScoped,
                ),
            ] {
                let error = provider_reported_session_error(
                    &json!({
                        "t": "s.error",
                        "code": code,
                        "message": "request-specific failure"
                    }),
                    &format!("{collector} {endpoint_family} session"),
                    collector_retryable,
                );
                assert_eq!(error.failure_class, expected_class, "{collector}");
                assert!(!error.retryable, "{collector}");
                record_route_attempt_error(&state, Some(route), Duration::from_millis(5), &error);
                assert!(
                    !state.route_provider_in_cooloff(route, now_millis_u64()),
                    "{collector} cooled the route for {code}"
                );
                let api_error = request_scoped_api_error(&error).expect("request-scoped API error");
                assert_eq!(api_error.status, StatusCode::BAD_REQUEST, "{collector}");
            }

            let entry = state
                .provider_table
                .lock_recover("provider table")
                .entries(now_millis_u64())
                .into_iter()
                .find(|entry| entry.key == route_key(route))
                .expect("route remains in provider table");
            assert_eq!(entry.observed.samples, 0, "{collector}");
            assert_eq!(entry.observed.consecutive_failures, 0, "{collector}");

            let provider_fault = provider_reported_session_error(
                &json!({
                    "t": "s.error",
                    "code": "provider_response_failed",
                    "message": "worker failed"
                }),
                &format!("{collector} {endpoint_family} session"),
                collector_retryable,
            );
            assert_eq!(
                provider_fault.failure_class,
                GatewaySessionFailureClass::ProviderFault,
                "{collector}"
            );
            record_route_attempt_error(
                &state,
                Some(route),
                Duration::from_millis(5),
                &provider_fault,
            );
            assert!(
                state.route_provider_in_cooloff(route, now_millis_u64()),
                "{collector} did not cool a true provider fault"
            );
            let entry = state
                .provider_table
                .lock_recover("provider table")
                .entries(now_millis_u64())
                .into_iter()
                .find(|entry| entry.key == route_key(route))
                .expect("route remains in provider table");
            assert_eq!(entry.observed.samples, 1, "{collector}");
            assert_eq!(entry.observed.consecutive_failures, 1, "{collector}");
        }
    }

    #[derive(Clone, Copy, Debug)]
    enum FocusedRouteRunner {
        Chat,
        Embedding,
        Image,
        Speech,
        Transcription,
        AudioArtifact,
        VideoArtifact,
    }

    impl FocusedRouteRunner {
        const ALL: [Self; 7] = [
            Self::Chat,
            Self::Embedding,
            Self::Image,
            Self::Speech,
            Self::Transcription,
            Self::AudioArtifact,
            Self::VideoArtifact,
        ];

        fn modalities(self) -> &'static [&'static str] {
            match self {
                Self::Chat => &["text"],
                Self::Embedding => &["embedding"],
                Self::Image => &["image"],
                Self::Speech => &["audio"],
                Self::Transcription => &["audio", "text"],
                Self::AudioArtifact => &["audio"],
                Self::VideoArtifact => &["video"],
            }
        }
    }

    fn focused_route_runner_model(runner: FocusedRouteRunner) -> GatewayModel {
        let mut model = test_routed_model(1);
        let modalities = runner
            .modalities()
            .iter()
            .map(|modality| (*modality).to_owned())
            .collect::<Vec<_>>();
        model.mayhem.adapter.modality_set = modalities.clone();
        model.mayhem.caps.vision = modalities.iter().any(|value| value == "image");
        model.mayhem.caps.image = modalities.iter().any(|value| value == "image");
        model.mayhem.caps.video = modalities.iter().any(|value| value == "video");
        model.mayhem.caps.audio = modalities.iter().any(|value| value == "audio");
        model.mayhem.caps.output_modality = Some(
            match runner {
                FocusedRouteRunner::Embedding => "embedding",
                FocusedRouteRunner::Image => "image",
                FocusedRouteRunner::Speech | FocusedRouteRunner::Transcription => "audio",
                FocusedRouteRunner::AudioArtifact => "audio",
                FocusedRouteRunner::VideoArtifact => "video",
                FocusedRouteRunner::Chat => "text",
            }
            .to_owned(),
        );
        model.mayhem.caps.output_modalities = modalities.clone();
        for route in &mut model.mayhem.route_candidates {
            route.served_modalities = modalities.clone();
        }
        model
    }

    fn focused_route_runner_error<T>(result: Result<T, ApiError>) -> ApiError {
        match result {
            Ok(_) => panic!("focused route runner unexpectedly succeeded"),
            Err(error) => error,
        }
    }

    async fn run_focused_route_runner_failure(
        runner: FocusedRouteRunner,
        code: &'static str,
    ) -> (GatewayState, GatewayModel, ApiError) {
        let model = focused_route_runner_model(runner);
        let state = test_gateway_state_from_models(vec![model.clone()])
            .with_session_backend(Arc::new(ProviderReportedFailureBackend { code }));
        let options = GatewayRequestOptions {
            max_wait_ms: 0,
            ..GatewayRequestOptions::default()
        };
        let error = match runner {
            FocusedRouteRunner::Chat => focused_route_runner_error(
                run_chat_with_route_retry(&state, &model, &test_chat_request(&model.id), options)
                    .await,
            ),
            FocusedRouteRunner::Embedding => {
                let inputs = vec!["embed this".to_owned()];
                let request = EmbeddingRequest {
                    model: model.id.clone(),
                    input: json!(inputs),
                    encoding_format: None,
                    dimensions: None,
                    user: None,
                    endpoint_family: None,
                    endpoint_request: None,
                };
                focused_route_runner_error(
                    run_embedding_with_route_retry(&state, &model, &request, &inputs, options)
                        .await,
                )
            }
            FocusedRouteRunner::Image => {
                let request = ImageGenerationRequest {
                    model: model.id.clone(),
                    prompt: "a precise test image".to_owned(),
                    background: None,
                    moderation: None,
                    n: Some(1),
                    output_compression: None,
                    output_format: None,
                    partial_images: None,
                    size: Some("512x512".to_owned()),
                    width: None,
                    height: None,
                    response_format: Some("b64_json".to_owned()),
                    quality: None,
                    style: None,
                    negative_prompt: None,
                    steps: Some(4),
                    cfg_scale: Some(1.0),
                    shift: None,
                    seed: Some(7),
                    scheduler: None,
                    stream: None,
                    user: None,
                    endpoint_family: None,
                    endpoint_request: None,
                };
                focused_route_runner_error(
                    run_image_generation_with_route_retry(&state, &model, &request, options).await,
                )
            }
            FocusedRouteRunner::Speech => {
                let request = AudioSpeechRequest {
                    model: model.id.clone(),
                    input: "speak this".to_owned(),
                    voice: None,
                    response_format: Some("wav".to_owned()),
                    speed: None,
                    instructions: None,
                    stream_format: None,
                    reference_audio: None,
                    exaggeration: None,
                    cfg_weight: None,
                    temperature: None,
                    min_p: None,
                    top_p: None,
                    repetition_penalty: None,
                    seed: None,
                    endpoint_family: None,
                    endpoint_request: None,
                };
                focused_route_runner_error(
                    run_audio_speech_with_route_retry(&state, &model, &request, options).await,
                )
            }
            FocusedRouteRunner::Transcription => {
                let request = AudioTranscriptionRequest {
                    model: model.id.clone(),
                    audio: test_wav_with_samples(8_000),
                    audio_seconds: 1,
                    content_type: Some("audio/wav".to_owned()),
                    filename: Some("test.wav".to_owned()),
                    response_format: Some("json".to_owned()),
                    language: None,
                    prompt: None,
                    temperature: None,
                    timestamp_granularities: Vec::new(),
                    stream: false,
                    endpoint_family: mayhem_proto::ENDPOINT_OPENAI_AUDIO_TRANSCRIPTIONS.to_owned(),
                    contract_request: json!({}),
                };
                focused_route_runner_error(
                    run_audio_transcription_with_route_retry(&state, &model, &request, options)
                        .await,
                )
            }
            FocusedRouteRunner::AudioArtifact | FocusedRouteRunner::VideoArtifact => {
                let is_video = matches!(runner, FocusedRouteRunner::VideoArtifact);
                let request = ArtifactGenerationRequest {
                    model: model.id.clone(),
                    prompt: if is_video {
                        "a precise test video"
                    } else {
                        "a precise test audio artifact"
                    }
                    .to_owned(),
                    endpoint_family: if is_video {
                        mayhem_proto::ENDPOINT_OPENAI_VIDEOS
                    } else {
                        mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO
                    }
                    .to_owned(),
                    contract_request: json!({}),
                    workflow: None,
                    workflow_output: None,
                    effective_specialities: BTreeMap::new(),
                    output_modality: if is_video { "video" } else { "audio" }.to_owned(),
                    transport_kind: if is_video {
                        "video_generation"
                    } else {
                        "audio_generation"
                    }
                    .to_owned(),
                    duration_seconds: 1,
                    requested_frame_count: 8,
                    frame_count: 8,
                    frame_rate: 8.0,
                    step_count: 1,
                    artifact_count: 1,
                    input_image_count: 0,
                    input_image_max_bytes: 0,
                    input_image_max_pixels: 0,
                    input_audio_count: 0,
                    input_audio_max_bytes: 0,
                    input_audio_max_seconds: 0,
                    response_format: "mp4".to_owned(),
                };
                focused_route_runner_error(
                    run_artifact_generation_with_route_retry(&state, &model, &request, options)
                        .await,
                )
            }
        };
        (state, model, error)
    }

    #[tokio::test]
    async fn chunk_and_reassembly_failures_do_not_penalize_any_route_runner() {
        for code in ["request_chunk_failed", "request_reassembly_failed"] {
            for runner in FocusedRouteRunner::ALL {
                let (state, model, error) = run_focused_route_runner_failure(runner, code).await;
                assert_eq!(error.status, StatusCode::BAD_REQUEST, "{runner:?} {code}");
                let route = &model.mayhem.route_candidates[0];
                assert!(
                    !state.route_provider_in_cooloff(route, now_millis_u64()),
                    "{runner:?} cooled the route for {code}"
                );
                let entry = state
                    .provider_table
                    .lock_recover("provider table")
                    .entries(now_millis_u64())
                    .into_iter()
                    .find(|entry| entry.key == route_key(route))
                    .expect("route remains in provider table");
                assert_eq!(entry.observed.samples, 0, "{runner:?} {code}");
                assert_eq!(entry.observed.consecutive_failures, 0, "{runner:?} {code}");
                assert!(state
                    .wallet_spend
                    .lock_recover("gateway wallet spend state")
                    .reservations
                    .is_empty());
            }
        }
    }

    #[tokio::test]
    async fn provider_faults_still_penalize_every_route_runner() {
        for runner in FocusedRouteRunner::ALL {
            let (state, model, error) =
                run_focused_route_runner_failure(runner, "provider_response_failed").await;
            assert_eq!(error.status, StatusCode::BAD_GATEWAY, "{runner:?}");
            let route = &model.mayhem.route_candidates[0];
            assert!(
                state.route_provider_in_cooloff(route, now_millis_u64()),
                "{runner:?} did not cool a provider fault"
            );
            let entry = state
                .provider_table
                .lock_recover("provider table")
                .entries(now_millis_u64())
                .into_iter()
                .find(|entry| entry.key == route_key(route))
                .expect("route remains in provider table");
            assert_eq!(entry.observed.samples, 1, "{runner:?}");
            assert_eq!(entry.observed.consecutive_failures, 1, "{runner:?}");
        }
    }

    #[test]
    fn provider_reject_session_error_marks_self_protection_codes_clean() {
        for code in [
            "CAPACITY",
            "BUSY",
            "RATE",
            "QUOTA",
            "PRICE_FLOOR",
            "DRAINING",
            "BALANCE",
        ] {
            let err = provider_reject_session_error(
                &json!({
                    "t": "s.reject",
                    "code": code,
                    "reason": "self protection",
                }),
                "session-a",
            );
            assert!(err.retryable);
            assert!(err.clean_refusal, "{code} should be a clean refusal");
            assert_eq!(err.clean_refusal_code.as_deref(), Some(code));
        }

        let err = provider_reject_session_error(
            &json!({
                "t": "s.reject",
                "code": "SIGNATURE",
                "reason": "bad open frame",
            }),
            "session-a",
        );
        assert!(err.retryable);
        assert!(!err.clean_refusal);
        assert_eq!(err.clean_refusal_code, None);
    }

    #[test]
    fn balance_reject_aborts_all_route_attempts_with_payment_required() {
        let err = provider_reject_session_error(
            &json!({
                "t": "s.reject",
                "code": "BALANCE",
                "reason": "Insufficient unreserved credit balance.",
            }),
            "session-a",
        );
        let refusal = terminal_balance_refusal(&err).expect("BALANCE reject is terminal");
        assert_eq!(refusal.status, StatusCode::PAYMENT_REQUIRED);

        for code in ["CAPACITY", "BUSY", "DRAINING"] {
            let err = provider_reject_session_error(
                &json!({
                    "t": "s.reject",
                    "code": code,
                    "reason": "self protection",
                }),
                "session-a",
            );
            assert!(
                terminal_balance_refusal(&err).is_none(),
                "{code} must stay route-retryable"
            );
        }

        for reason in [
            "spend reservation did not complete within the 90000 ms provider admission budget; no work was served",
            "contract spend reservation rejected before serving: Mayhem feature relay accepted the append but no canonical result appeared before the relay result budget.",
            "provider has no active verified fiat payout binding: missing payout binding",
        ] {
            let err = provider_reject_session_error(
                &json!({
                    "t": "s.reject",
                    "code": "BALANCE",
                    "reason": reason,
                }),
                "session-a",
            );
            assert!(
                terminal_balance_refusal(&err).is_none(),
                "{reason} must stay route-retryable"
            );
        }
    }

    #[test]
    fn capacity_refusal_only_penalizes_sustained_false_free_capacity() {
        let model = test_routed_model(1);
        let state = test_gateway_state_from_models(vec![model.clone()]);
        let route = model.mayhem.route_candidates.first().expect("route");
        let capacity = GatewaySessionError::clean_refusal_with_code(
            "provider rejected session session-a with CAPACITY: full",
            Some("CAPACITY"),
        );

        record_route_attempt_error(&state, Some(route), Duration::from_millis(5), &capacity);
        record_route_attempt_error(&state, Some(route), Duration::from_millis(5), &capacity);
        assert!(state.reputation_events().is_empty());
        record_route_attempt_error(&state, Some(route), Duration::from_millis(5), &capacity);
        assert!(state.reputation_events().is_empty());

        let received_base = now_millis_u64().saturating_add(10);
        for offset in 0..3 {
            state
                .provider_table
                .lock_recover("provider table")
                .upsert_heartbeat(
                    heartbeat_for_route(&model, route, received_base + offset),
                    received_base + offset,
                );
            record_route_attempt_error(&state, Some(route), Duration::from_millis(5), &capacity);
        }

        let events = state.reputation_events();
        assert_eq!(events.len(), 1);
        assert!(events[0].event_id.starts_with("capacity-mismatch-"));
        assert_eq!(events[0].kind, "underdelivery");
        assert_eq!(
            events[0].evidence["source"],
            json!("mayhem-gateway-capacity-mismatch-v1")
        );

        let honest_state = test_gateway_state_from_models(vec![model.clone()]);
        let mut saturated = heartbeat_for_route(&model, route, now_millis_u64());
        saturated.sat = 1.0;
        saturated.slots.active = 1;
        saturated.slots.active_requests = 1;
        saturated.slots.max = 1;
        saturated.q.free_slots = 0;
        saturated.q.engine_backlog = 0;
        honest_state
            .provider_table
            .lock_recover("provider table")
            .upsert_heartbeat(saturated, now_millis_u64());
        for _ in 0..3 {
            record_route_attempt_error(
                &honest_state,
                Some(route),
                Duration::from_millis(5),
                &capacity,
            );
        }
        assert!(honest_state.reputation_events().is_empty());
        let entry = honest_state
            .provider_table
            .lock_recover("provider table")
            .entries(now_millis_u64())
            .into_iter()
            .next()
            .expect("provider entry");
        assert_eq!(entry.observed.capacity_mismatch_streak, 0);
        assert_eq!(entry.observed.consecutive_failures, 0);
    }

    #[tokio::test]
    async fn route_retry_clean_refusal_reroutes_without_failure_penalty() {
        let model = test_routed_model(2);
        let providers = Arc::new(Mutex::new(Vec::new()));
        let billing_attempts = Arc::new(Mutex::new(Vec::new()));
        let state = test_gateway_state_from_models(vec![model.clone()]).with_session_backend(
            Arc::new(CleanRefusalThenSuccessBackend {
                providers: providers.clone(),
                billing_attempts: billing_attempts.clone(),
                refused: None,
            }),
        );
        let request = test_chat_request(&model.id);

        let run =
            run_chat_with_route_retry(&state, &model, &request, GatewayRequestOptions::default())
                .await
                .expect("clean refusal should reroute");

        assert_eq!(run.result.output.content.as_deref(), Some("recovered"));
        let providers = providers.lock().expect("providers lock").clone();
        assert_eq!(providers.len(), 2);
        assert_ne!(providers[0], providers[1]);
        assert_eq!(
            billing_attempts
                .lock()
                .expect("billing attempts lock")
                .as_slice(),
            &[0, 0]
        );
        let refused_route = model
            .mayhem
            .route_candidates
            .iter()
            .find(|candidate| candidate.provider == providers[0])
            .expect("refused provider route");
        assert!(!state.route_provider_in_cooloff(refused_route, now_millis_u64()));
        let refused_entry = state
            .provider_table
            .lock()
            .expect("provider table lock")
            .entries(now_millis_u64())
            .into_iter()
            .find(|entry| entry.key.provider == providers[0])
            .expect("refused provider table entry");
        assert_eq!(refused_entry.observed.samples, 0);
        assert_eq!(refused_entry.observed.consecutive_failures, 0);
        assert_eq!(refused_entry.observed.ewma_error_rate, 0.0);
        assert_eq!(refused_entry.observed.circuit_open_until_millis, None);
    }

