    #[tokio::test]
    async fn streaming_owned_routes_require_a_new_heartbeat_generation_after_capacity() {
        let model = test_routed_model(1);
        let state = test_gateway_state_from_models(vec![model.clone()]);
        let route = model.mayhem.route_candidates[0].clone();
        let mut recovery = RouteAdmissionRecovery::new(
            RouteWaitDeadline::new(100),
            DEFAULT_MAX_OPEN_ATTEMPTS.into(),
        );
        let initial_generation = state
            .provider_table
            .lock_recover("provider table")
            .heartbeat_received_at_millis(&route_key(&route))
            .expect("initial heartbeat generation");
        recovery.begin_attempt(Some(&route));
        let during_attempt_generation = initial_generation.saturating_add(1);
        state
            .provider_table
            .lock_recover("provider table")
            .upsert_heartbeat(
                heartbeat_for_route(&model, &route, during_attempt_generation),
                during_attempt_generation,
            );
        recovery.record_capacity_refusal(&state, Some(&route));

        assert!(recovery
            .filter_owned_routes(&state, vec![route.clone()])
            .is_empty());
        let received_at = during_attempt_generation.saturating_add(1);
        state
            .provider_table
            .lock_recover("provider table")
            .upsert_heartbeat(
                heartbeat_for_route(&model, &route, received_at),
                received_at,
            );

        let recovered = wait_for_owned_capacity_recovery(
            &state,
            &recovery,
            || model.mayhem.route_candidates.clone(),
            Duration::from_millis(1),
        )
        .await;
        assert_eq!(recovered, vec![route]);
    }

    #[tokio::test]
    async fn route_retry_records_conversation_affinity_after_success() {
        let model = test_routed_model(4);
        let providers = Arc::new(Mutex::new(Vec::new()));
        let state = test_gateway_state_from_models(vec![model.clone()]).with_session_backend(
            Arc::new(SuccessBackend {
                providers: providers.clone(),
            }),
        );
        let mut request = test_chat_request(&model.id);
        request
            .metadata
            .insert("conversation_id".to_owned(), json!("agent-loop-1"));

        run_chat_with_route_retry(&state, &model, &request, GatewayRequestOptions::default())
            .await
            .expect("request should succeed");

        let served_provider = providers
            .lock()
            .expect("providers lock")
            .first()
            .cloned()
            .expect("provider recorded");
        let affinity_key = chat_affinity_key(&model, &request).expect("affinity key");
        let sticky_key = state
            .chat_affinity
            .lock_recover("chat affinity map")
            .get(&affinity_key)
            .cloned()
            .expect("affinity recorded");
        assert_eq!(sticky_key.provider, served_provider);

        let seed = (0..256_u64)
            .find(|seed| {
                ordered_route_candidates_for_request_with_seed(
                    &state, &model, &request, None, *seed,
                )
                .into_iter()
                .next()
                .map(|candidate| candidate.provider == served_provider)
                .unwrap_or(false)
            })
            .expect("sticky provider should remain eligible");
        let selected =
            ordered_route_candidates_for_request_with_seed(&state, &model, &request, None, seed);
        assert_eq!(selected[0].provider, served_provider);
    }

