    #[test]
    fn session_artifact_delta_collects_chunks_and_verifies_digest() {
        let bytes = b"\x89PNG mayhem image".to_vec();
        let digest = blake3_hex(&bytes);
        let mut builders = SessionArtifactCollection::default();

        collect_artifact_from_session_delta(
            &json!({
                "t": "s.delta",
                "rid": "rid-1",
                "artifact": {
                    "id": "image-1",
                    "content_type": "image/png",
                    "encoding": "hex",
                    "offset": 0,
                    "len": 4,
                    "total_len": bytes.len(),
                    "blake3": digest,
                    "data": hex::encode(&bytes[..4]),
                    "final": false,
                }
            }),
            &mut builders,
        )
        .unwrap();
        collect_artifact_from_session_delta(
            &json!({
                "t": "s.delta",
                "rid": "rid-1",
                "artifact": {
                    "id": "image-1",
                    "content_type": "image/png",
                    "encoding": "hex",
                    "offset": 4,
                    "len": bytes.len() - 4,
                    "total_len": bytes.len(),
                    "blake3": digest,
                    "data": hex::encode(&bytes[4..]),
                    "final": true,
                }
            }),
            &mut builders,
        )
        .unwrap();

        let artifacts = finish_session_artifacts(builders).unwrap();
        assert_eq!(artifacts.len(), 1);
        assert_eq!(artifacts[0].id, "image-1");
        assert_eq!(artifacts[0].content_type, "image/png");
        assert_eq!(artifacts[0].bytes, bytes);
        assert_eq!(artifacts[0].blake3, blake3_hex(&artifacts[0].bytes));
    }

    #[test]
    fn session_artifact_delta_rejects_corrupt_digest() {
        let bytes = b"not the claimed image".to_vec();
        let mut builders = SessionArtifactCollection::default();
        collect_artifact_from_session_delta(
            &json!({
                "t": "s.delta",
                "rid": "rid-1",
                "artifact": {
                    "id": "image-1",
                    "content_type": "image/png",
                    "encoding": "hex",
                    "offset": 0,
                    "len": bytes.len(),
                    "total_len": bytes.len(),
                    "blake3": "00".repeat(32),
                    "data": hex::encode(&bytes),
                    "final": true,
                }
            }),
            &mut builders,
        )
        .unwrap();

        let err = finish_session_artifacts(builders).expect_err("digest mismatch must reject");
        assert!(err.message.contains("blake3 mismatch"));
    }

    #[test]
    fn session_artifact_delta_enforces_aggregate_budget_and_finality() {
        let bytes = b"12345";
        let digest = blake3_hex(bytes);
        let mut too_large = SessionArtifactCollection {
            builders: BTreeMap::new(),
            total_bytes: 0,
            max_total_bytes: 4,
            max_artifacts: 1,
        };
        let err = collect_artifact_from_session_delta(
            &json!({
                "artifact": {
                    "id": "a",
                    "content_type": "application/octet-stream",
                    "encoding": "hex",
                    "offset": 0,
                    "len": bytes.len(),
                    "total_len": bytes.len(),
                    "blake3": digest,
                    "data": hex::encode(bytes),
                    "final": true,
                }
            }),
            &mut too_large,
        )
        .unwrap_err();
        assert!(err.message.contains("session budget"));

        let one = b"1";
        let mut finalized = SessionArtifactCollection {
            builders: BTreeMap::new(),
            total_bytes: 0,
            max_total_bytes: 16,
            max_artifacts: 1,
        };
        let frame = json!({
            "artifact": {
                "id": "a",
                "content_type": "application/octet-stream",
                "encoding": "hex",
                "offset": 0,
                "len": 1,
                "total_len": 1,
                "blake3": blake3_hex(one),
                "data": hex::encode(one),
                "final": true,
            }
        });
        collect_artifact_from_session_delta(&frame, &mut finalized).unwrap();
        assert!(collect_artifact_from_session_delta(&frame, &mut finalized)
            .unwrap_err()
            .message
            .contains("after its final"));
    }

